using System.Collections;
using Chaos.VectorExtensions;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityStandardAssets.ImageEffects;

public class CameraController : MonoBehaviour
{
	public const float defaultShakeIntensity = 12f;

	public static int pixelsPerUnit = 16;

	public static float originalCameraSize;

	[HideInInspector]
	public static float shakeIntensityMultiplier = 1f;

	private Vector3 shakeOffsetVector = Vector3.zero;

	public float shakeDuration;

	public Vector3 avgPlayerPos;

	public Vector3 spawnPos;

	public bool disablePlayerTracking;

	public bool lockToSpawnPos;

	private Vector2 moveLockVector = Vector2.zero;

	public bool horiMoveOnly;

	public bool vertMoveOnly;

	public float maxHorizontalDistBetweenPlayers = 25f;

	public float maxVerticalDistBetweenPlayers = 15f;

	public float teleportToOtherPlayerRange = 32f;

	private bool lockCamera;

	private bool disableLockCamera;

	private Vector3 cameraLockLocation;

	private Vector3 lockedLocDistToPlayer;

	private float lerpDistTime;

	public static bool lerp;

	public static float lerpSpeed;

	private const float defaultLerpSpeed = 12f;

	private float distanceBetweenPlayers;

	private Vector2 playerDiff;

	private Movement p1Movement;

	private Movement p2Movement;

	public bool overrideCameraUpdate;

	private bool overrideCameraInProgress;

	private bool overrideCameraFollowPlayer = true;

	private static int currentOverrideAndMoveCount;

	public Blur blur;

	public static int shakeCounter;

	public int shakeCounterMax;

	public Movement movement;

	public static CameraHurtEffect cameraHurtEffect;

	[HideInInspector]
	public Transform cameraWorldTrans;

	private static CameraController instance;

	private WaitForSeconds waitForShakeDelay = new WaitForSeconds(0.0166f);

	private static float sctpuXAbs;

	private static float sctpuYAbs;

	private static float sctpuXDiff;

	private static float sctpuYDiff;

	public static Vector2 V2Position => (!(instance == null)) ? ((Vector2)instance.transform.position) : Vector2.zero;

	public bool HoriMoveOnly
	{
		get
		{
			return horiMoveOnly;
		}
		set
		{
			horiMoveOnly = value;
			if (value)
			{
				moveLockVector.y = transform.position.y;
			}
		}
	}

	public bool VertMoveOnly
	{
		get
		{
			return vertMoveOnly;
		}
		set
		{
			vertMoveOnly = value;
			if (value)
			{
				moveLockVector.x = transform.position.x;
			}
		}
	}

	public static CameraController Instance => instance;

	public void Awake()
	{
		if (instance != null && instance != this)
		{
			Object.Destroy(gameObject);
			return;
		}
		instance = this;
		Object.DontDestroyOnLoad(gameObject);
		spawnPos = transform.position;
		shakeDuration = 0.15f;
		shakeCounter = 0;
		shakeCounterMax = 4;
		lerp = false;
		lerpSpeed = 12f;
		overrideCameraUpdate = false;
		originalCameraSize = Camera.main.orthographicSize;
		blur = GetComponent<Blur>();
		blur.enabled = false;
		movement = GetComponent<Movement>();
		cameraHurtEffect = transform.Find("CameraHurtEffect").GetComponent<CameraHurtEffect>();
		cameraWorldTrans = transform.Find("CameraWorldPosition");
	}

	private void Update()
	{
		if (overrideCameraUpdate)
		{
			return;
		}
		Camera.main.orthographicSize = originalCameraSize;
		if (GameController.playerScripts[0] != null && GameController.playerScripts[1] != null)
		{
			if (p1Movement == null)
			{
				p1Movement = GameController.playerScripts[0].movement;
			}
			if (p2Movement == null)
			{
				p2Movement = GameController.playerScripts[1].movement;
			}
			playerDiff = GameController.playerScripts[0].transform.position - GameController.playerScripts[1].transform.position;
			distanceBetweenPlayers = playerDiff.magnitude;
			if (GameController.pvpOn || SceneManager.GetActiveScene().name.Contains("PvP"))
			{
				distanceBetweenPlayers *= 0.42f;
				Camera.main.orthographicSize = ((!(distanceBetweenPlayers > originalCameraSize)) ? originalCameraSize : distanceBetweenPlayers);
			}
			else if (GameController.coopOn)
			{
				if (GameController.PlayerIsDead())
				{
					distanceBetweenPlayers = -1f;
				}
				if (distanceBetweenPlayers > teleportToOtherPlayerRange)
				{
					Vector2 givenLocation = Vector2.zero;
					Player[] activePlayers = GameController.activePlayers;
					foreach (Player player in activePlayers)
					{
						if (player.playerID == 0)
						{
							givenLocation = player.transform.position;
						}
						else if (player.IsAvailable && !player.IsDead)
						{
							player.RequestTeleportMoveToLocation(givenLocation);
						}
					}
				}
				if (distanceBetweenPlayers > maxVerticalDistBetweenPlayers)
				{
					if (Mathf.Abs(playerDiff.y) > maxVerticalDistBetweenPlayers)
					{
						if (playerDiff.y > 0f)
						{
							p1Movement.preventUpMovement = true;
							p2Movement.preventDownMovement = true;
						}
						else
						{
							p1Movement.preventDownMovement = true;
							p2Movement.preventUpMovement = true;
						}
					}
					else
					{
						p1Movement.RemoveAllPrevents(xAxis: false);
						p2Movement.RemoveAllPrevents(xAxis: false);
					}
					if (Mathf.Abs(playerDiff.x) > maxHorizontalDistBetweenPlayers)
					{
						if (playerDiff.x > 0f)
						{
							p1Movement.preventRightMovement = true;
							p2Movement.preventLeftMovement = true;
						}
						else
						{
							p1Movement.preventLeftMovement = true;
							p2Movement.preventRightMovement = true;
						}
					}
					else
					{
						p1Movement.RemoveAllPrevents(xAxis: true, yAxis: false);
						p2Movement.RemoveAllPrevents(xAxis: true, yAxis: false);
					}
				}
				else
				{
					p1Movement.RemoveAllPrevents();
					p2Movement.RemoveAllPrevents();
				}
			}
		}
		if (disablePlayerTracking)
		{
			if (lockToSpawnPos)
			{
				transform.position = spawnPos;
			}
		}
		else
		{
			if (GameController.GetAlivePlayerCount() == 0)
			{
				return;
			}
			avgPlayerPos = GameController.GetPlayerPositionAverage();
			disableLockCamera = overrideCameraFollowPlayer && !HoriMoveOnly && !VertMoveOnly && Vector2.Distance(avgPlayerPos, transform.position) > 3f;
			if (lockCamera && !disableLockCamera)
			{
				if (cameraLockLocation == Vector3.zero)
				{
					cameraLockLocation = transform.position;
					lockedLocDistToPlayer = avgPlayerPos - cameraLockLocation;
					lockedLocDistToPlayer.z = 0f;
				}
				SetCameraPosition(avgPlayerPos - lockedLocDistToPlayer);
			}
			else if ((GameController.coopOn && distanceBetweenPlayers > 0f) || lerp)
			{
				LerpCamera(avgPlayerPos, lerpSpeed);
			}
			else
			{
				SetCameraPosition(avgPlayerPos);
			}
		}
	}

	public void SetCameraPosition(Vector3 newPosition)
	{
		newPosition.z = transform.position.z;
		if (horiMoveOnly)
		{
			newPosition.y = moveLockVector.y;
		}
		if (vertMoveOnly)
		{
			newPosition.x = moveLockVector.x;
		}
		transform.position = newPosition;
	}

	private void LerpCamera(Vector3 targetPosition, float speed)
	{
		SetCameraPosition(Vector3.Lerp(transform.position, targetPosition, speed * Time.deltaTime));
	}

	public void OverrideAndMoveCameraToLocation(Transform targetTrans = null, Vector3? targetLoc = null, float duration = 1f, bool followPlayer = false, bool setLocks = false, bool vertLockStatus = false, bool horiLockStatus = false)
	{
		if (followPlayer || !(targetTrans == null) || targetLoc.HasValue)
		{
			if (!targetLoc.HasValue)
			{
				targetLoc = Vector3.zero;
			}
			StartCoroutine(OverrideAndMoveToLocation(targetTrans, targetLoc.Value, duration, followPlayer, setLocks, vertLockStatus, horiLockStatus));
		}
	}

	private IEnumerator OverrideAndMoveToLocation(Transform targetTransform, Vector3 targetLocation, float duration, bool followPlayer, bool setLocks, bool vertLockStatus, bool horiLockStatus)
	{
		if (!setLocks && VertMoveOnly && HoriMoveOnly)
		{
			yield break;
		}
		currentOverrideAndMoveCount++;
		while (currentOverrideAndMoveCount > 1)
		{
			overrideCameraInProgress = false;
			yield return null;
		}
		overrideCameraInProgress = true;
		overrideCameraUpdate = true;
		overrideCameraFollowPlayer = followPlayer;
		if (setLocks)
		{
			HoriMoveOnly = false;
			VertMoveOnly = false;
		}
		int durationStopwatchID = ChaosStopwatch.Begin(duration);
		while (overrideCameraUpdate && overrideCameraInProgress && !ChaosStopwatch.Check(durationStopwatchID))
		{
			if (targetTransform != null)
			{
				targetLocation = targetTransform.position;
			}
			else if (GameController.GetAlivePlayerCount() > 0)
			{
				if (followPlayer)
				{
					targetLocation = GameController.GetPlayerPositionAverage();
				}
				else if (vertLockStatus && !horiLockStatus)
				{
					targetLocation.x = GameController.GetPlayerPositionAverage().x;
				}
				else if (!vertLockStatus && horiLockStatus)
				{
					targetLocation.y = GameController.GetPlayerPositionAverage().y;
				}
			}
			SetCameraPosition(Vector3.Lerp(transform.position, targetLocation, ChaosStopwatch.GetTimePercentage(durationStopwatchID)));
			yield return null;
		}
		SetCameraPosition(targetLocation);
		if (setLocks)
		{
			HoriMoveOnly = vertLockStatus;
			VertMoveOnly = horiLockStatus;
		}
		currentOverrideAndMoveCount--;
		overrideCameraInProgress = false;
		overrideCameraUpdate = currentOverrideAndMoveCount != 0;
	}

	public static void ShakeCamera(float intensityMultiplier = 1f, bool ignoreShakeCount = false)
	{
		if (!(Instance == null) && shakeIntensityMultiplier != 0f)
		{
			Instance.StartCoroutine(Instance.Shake(12f * intensityMultiplier, ignoreShakeCount));
		}
	}

	private IEnumerator Shake(float shakeIntensity, bool ignoreShakeCounter = false)
	{
		if (disableLockCamera)
		{
			yield break;
		}
		lockCamera = true;
		if (shakeCounter < shakeCounterMax || ignoreShakeCounter)
		{
			shakeCounter++;
			shakeIntensity *= shakeIntensityMultiplier;
			int shakeStopwatchID = ChaosStopwatch.Begin(shakeDuration);
			while (!ChaosStopwatch.Check(shakeStopwatchID))
			{
				transform.position += shakeOffsetVector.Randomize(1f, 1f) * shakeIntensity * 0.0166f;
				yield return waitForShakeDelay;
			}
			shakeCounter--;
			if (shakeCounter == 0)
			{
				lockCamera = false;
				cameraLockLocation = Vector3.zero;
			}
		}
	}

	public static void SnapCameraToPixelUnit(Transform trans)
	{
		sctpuXAbs = Mathf.Abs(trans.position.x);
		sctpuYAbs = Mathf.Abs(trans.position.y);
		sctpuXDiff = sctpuXAbs - (float)(int)sctpuXAbs;
		sctpuYDiff = sctpuYAbs - (float)(int)sctpuYAbs;
		sctpuXDiff *= pixelsPerUnit;
		sctpuYDiff *= pixelsPerUnit;
		sctpuXDiff = ((!(sctpuXDiff - (float)(int)sctpuXDiff > 0.5f)) ? ((int)sctpuXDiff) : ((int)sctpuXDiff + 1));
		sctpuYDiff = ((!(sctpuYDiff - (float)(int)sctpuYDiff > 0.5f)) ? ((int)sctpuYDiff) : ((int)sctpuYDiff + 1));
		sctpuXDiff /= pixelsPerUnit;
		sctpuYDiff /= pixelsPerUnit;
		sctpuXAbs = sctpuXDiff + (float)(int)sctpuXAbs;
		sctpuYAbs = sctpuYDiff + (float)(int)sctpuYAbs;
		if (trans.position.x < 0f)
		{
			sctpuXAbs = 0f - sctpuXAbs;
		}
		if (trans.position.y < 0f)
		{
			sctpuYAbs = 0f - sctpuYAbs;
		}
		trans.position = new Vector3(sctpuXAbs, sctpuYAbs, trans.position.z);
	}
}
using UnityEngine;
using UnityEngine.SceneManagement;

public class AirStageCameraEffects : MonoBehaviour
{
	private Transform cloudTrans;

	private Transform cloudBGTrans;

	private Transform cloudFGTrans;

	private static Color skyColor = new Color32(146, 174, 174, byte.MaxValue);

	private Vector2 startPos;

	private Vector2 lastPos;

	private Vector3 lastPosV3;

	private Vector3 calcPos;

	private const float PanRatio = 48f;

	private const float PanRatioBG = 54f;

	private const float CloudZPos = 10f;

	public void Awake()
	{
		cloudTrans = transform.Find("Clouds");
		cloudFGTrans = cloudTrans.Find("Foreground");
		cloudBGTrans = cloudTrans.Find("Background");
		cloudTrans.localScale = ((!(Random.value > 0.5f)) ? Globals.Vector3NegativeX : Vector3.one);
	}

	public void Start()
	{
		SceneManager.sceneLoaded += OnSceneLoaded;
		Toggle();
	}

	public void OnSceneLoaded(Scene scene, LoadSceneMode loadSceneMode)
	{
		if (scene.name != "Air" && scene.name != "AirBossLevel")
		{
			SceneManager.sceneLoaded -= OnSceneLoaded;
			Camera.main.backgroundColor = Color.black;
		}
	}

	public void Toggle(bool enable = true)
	{
		if (enable)
		{
			if (gameObject != null)
			{
				gameObject.SetActive(value: true);
			}
			Camera.main.backgroundColor = skyColor;
			InitPosition();
		}
		else
		{
			if (gameObject != null)
			{
				gameObject.SetActive(value: false);
			}
			Camera.main.backgroundColor = Color.black;
		}
	}

	public void InitPosition()
	{
		startPos = MinimapFullscreen.stageOrigin;
		if (Application.loadedLevelName.Contains("Test"))
		{
			startPos = GameObject.Find("PlayerSpawnArea").transform.position;
		}
		else if (Application.loadedLevelName.Contains("PvPArena"))
		{
			startPos = GameObject.Find("PvpController/PlayerSpawnLocations/P1Spawn").transform.position;
		}
		lastPos = startPos;
		lastPosV3 = startPos;
	}

	public void LateUpdate()
	{
		if (!GameController.cameraController.disablePlayerTracking && !GameController.cameraController.lockToSpawnPos && (!GameController.cameraController.HoriMoveOnly || !GameController.cameraController.VertMoveOnly) && GameController.activePlayers.Length != 0 && !(GameController.activePlayers[0] == null) && !(lastPosV3 == GameController.activePlayers[0].transform.position))
		{
			lastPos = GameController.activePlayers[0].transform.position;
			if (GameController.cameraController.HoriMoveOnly)
			{
				lastPos = new Vector3(lastPos.x, 0f, 0f);
			}
			else if (GameController.cameraController.VertMoveOnly)
			{
				lastPos = new Vector3(0f, lastPos.y, 0f);
			}
			lastPosV3 = lastPos;
			calcPos = startPos - lastPos;
			cloudFGTrans.transform.localPosition = new Vector3(calcPos.x / 48f, calcPos.y / 48f, 10f);
			cloudBGTrans.transform.localPosition = new Vector3(calcPos.x / 48f, calcPos.y / 54f, 10f);
		}
	}
}
