using UnityEngine;

public class CameraHurtEffect : MonoBehaviour
{
	private Animator singlePlayerAnim;

	private Animator P1HurtAnim;

	private Animator P2HurtAnim;

	private void Awake()
	{
		singlePlayerAnim = transform.Find("RedBorderFull").GetComponent<Animator>();
		P1HurtAnim = transform.Find("RedBorderP1").GetComponent<Animator>();
		P2HurtAnim = transform.Find("RedBorderP2").GetComponent<Animator>();
	}

	public void FlashRed(int playerID, float normalizedTime)
	{
		if (!GameController.coopOn)
		{
			singlePlayerAnim.Play("FlashRed", -1, normalizedTime);
		}
		else if (playerID == 0)
		{
			P1HurtAnim.Play("FlashRed", -1, normalizedTime);
		}
		else
		{
			P2HurtAnim.Play("FlashRed", -1, normalizedTime);
		}
	}
}

