private static void HandleBGMTrack(string givenTrackName)
{
	switch (bgmTrack)
	{
	case BGMTrackType.Original:
		instance.StartCoroutine(BGMTransition(givenTrackName + oriPostStr, bgmOriginalVol));
		break;
	case BGMTrackType.Jazz:
		instance.StartCoroutine(BGMTransition(givenTrackName + jazzPostStr, bgmJazzVol));
		break;
	case BGMTrackType.Piano:
		instance.StartCoroutine(BGMTransition(givenTrackName + pianoPostStr, bgmPianoVol));
		break;
	}
}

private static IEnumerator BGMTransition(string givenTrackName, float givenVol = 0.25f)
{
	if (muteAudio)
	{
		yield break;
	}
	while (BGMTransitionInProgress)
	{
		yield return null;
	}
	bgmTransInProgress = true;
	if (BGMPaused)
	{
		BGMPaused = false;
	}
	if (currentBGM != null && currentBGM.isPlaying && currentBGM.clip != null && currentBGM.clip.name == givenTrackName)
	{
		bgmTransInProgress = false;
		yield break;
	}
	if (!bgmSet.Contains(givenTrackName))
	{
		if (currentBGM != null)
		{
			float tempMulti = currentBGM.volume / 0.25f * 0.25f;
			while (currentBGM.volume > 0f)
			{
				currentBGM.volume -= Time.deltaTime * tempMulti;
				yield return null;
			}
			currentBGM.volume = 0f;
			currentBGM.Stop();
		}
		bgmTransInProgress = false;
		yield break;
	}
	ChaosBundle.LoadBGM(givenTrackName);
	while (ChaosBundle.bgmLoadInProgress)
	{
		yield return null;
	}
	currentBGM = bgmSourceArr[mainBgmAudio ? 1 : 0];
	nextBGM = bgmSourceArr[(!mainBgmAudio) ? 1u : 0u];
	nextBGM.clip = ChaosBundle.GetBGM(bgmPathStr + givenTrackName + bgmFormat);
	if (currentBGM == null || !currentBGM.isPlaying)
	{
		currentBGM = nextBGM;
		if (currentBGM.clip != null)
		{
			currentBGM.volume = givenVol;
			currentBGM.Play();
			mainBgmAudio = !mainBgmAudio;
		}
		bgmTransInProgress = false;
		yield break;
	}
	nextBGM.volume = 0f;
	nextBGM.Play();
	float tempCurMulti = currentBGM.volume / 0.25f * 0.25f;
	float tempNextMulti = givenVol / 0.25f * 0.25f;
	bool tempCheck = true;
	while (tempCheck)
	{
		tempCheck = false;
		if (currentBGM.volume > 0f)
		{
			currentBGM.volume -= Time.deltaTime * tempCurMulti;
			tempCheck = true;
		}
		if (nextBGM.volume < givenVol)
		{
			nextBGM.volume += Time.deltaTime * tempNextMulti;
			tempCheck = true;
		}
		yield return null;
	}
	nextBGM.volume = givenVol;
	currentBGM.volume = 0f;
	currentBGM.Stop();
	currentBGM = nextBGM;
	bgmTransInProgress = false;
	mainBgmAudio = !mainBgmAudio;
}

private void InitializeMixerGroups()
{
	if (mixerGroupDict == null)
	{
		mixerGroupDict = new Dictionary<string, AudioMixerGroup>();
		mixerGroupDict["Master/SFX/Game"] = masterMixer.FindMatchingGroups("Master/SFX/Game")[0];
		mixerGroupDict[uiMixerGroup] = masterMixer.FindMatchingGroups(uiMixerGroup)[0];
		mixerGroupDict[bgmMixerGroup] = masterMixer.FindMatchingGroups(bgmMixerGroup)[0];
	}
}

private void Initialize()
{
	InitializeMixerGroups();
	masterMixer.FindSnapshot("Default").TransitionTo(0f);
	audioSources = new AudioSource[audioSourceCount];
	audioWithDistVars = new AudioWithDistVar[audioSourceCount];
	availableAudioSources = new bool[audioSourceCount];
	for (int i = 0; i < audioSourceCount; i++)
	{
		availableAudioSources[i] = true;
	}
	currentAudioSourceIndex = 0;
	soundClipDict = new Dictionary<string, SoundClip>();
	soundPlayedTime = new Dictionary<string, float>();
	for (int j = 0; j < audioSourceCount; j++)
	{
		audioSources[j] = gameObject.AddComponent<AudioSource>();
		audioSources[j].outputAudioMixerGroup = mixerGroupDict[uiMixerGroup];
	}
	LoadSoundClipDict();
	foreach (SoundClip value in soundClipDict.Values)
	{
		value.volume *= globalClipVolumeModifier;
	}
	if (bgmGameObject != null)
	{
		UnityEngine.Object.Destroy(bgmGameObject);
	}
	bgmGameObject = new GameObject("BgmPlayer");
	bgmGameObject.transform.SetParent(transform);
	InitBGMSettings();
	pausedAudioSourceList = new List<AudioSource>();
}

