	private void LoadExternal(string givenName)
	{
		StartCoroutine(LoadExternalSoundFile(givenName));
	}

	private IEnumerator LoadAllExternalSoundFiles()
	{
		currentResourcePath = "file://" + Application.dataPath + "/Sounds/";
		Debug.LogError("STARTING: Current sound directory: " + currentResourcePath);
		int externalCount = externalSFXList.Count;
		int counter = 0;
		while (counter < externalCount)
		{
			yield return StartCoroutine(LoadExternalSoundFile(externalSFXList[counter]));
			counter++;
			yield return null;
		}
		while (externalClipLoadCount > 0)
		{
			yield return null;
		}
		yield return null;
		Debug.LogError("FINISHED loading sound files");
	}

	private IEnumerator LoadExternalSoundFile(string givenName)
	{
		WWW loader = new WWW(currentResourcePath + givenName + ".wav");
		yield return loader;
		if (loader.error != null)
		{
			loader.Dispose();
			yield break;
		}
		externalClip = loader.GetAudioClip(threeD: false, stream: false, AudioType.WAV);
		externalClip.LoadAudioData();
		externalClip.name = givenName;
		if (externalClip == null || externalClip.loadState.Equals(AudioDataLoadState.Failed))
		{
			loader.Dispose();
			yield break;
		}
		externalClipLoadCount++;
		while (externalClip.loadState == AudioDataLoadState.Loading)
		{
			yield return null;
		}
		externalClipLoadCount--;
		if (externalClip.loadState == AudioDataLoadState.Unloaded)
		{
			loader.Dispose();
			yield break;
		}
		AddClipToDict(givenName);
		soundClipDict[givenName].audioClip = externalClip;
		loader.Dispose();
	}

	public void AutoPlayBGM(Scene scene, LoadSceneMode loadSceneMode)
	{
		string text = scene.name;
		if (text.Contains("Boss"))
		{
			PlayBGM(string.Empty);
		}
		else if (text == "PvP")
		{
			PlayBGM("Hub");
		}
		else
		{
			PlayBGM(Application.loadedLevelName);
		}
	}

