	public static ChaosInputDevice ClaimController(int playerID, Controller controller)
	{
		switch (playerID)
		{
		case 0:
			tempPlayer = Player0;
			break;
		case 1:
			tempPlayer = Player1;
			break;
		default:
			tempPlayer = null;
			break;
		}
		if (tempPlayer == null || !chaosInputs.ContainsKey(tempPlayer))
		{
			return null;
		}
		if (IsControllerAssigned(controller, tempPlayer))
		{
			return null;
		}
		if (!ChaosInputDevice.lockControllerInput)
		{
			if (playerID == 0 && !GameController.coopOn && !GameController.pvpOn)
			{
				AssignAllControllersToPlayer(tempPlayer, removeFromOtherPlayers: true, controller);
			}
			else if (playerID == 1 && controller.type != ControllerType.Keyboard && controller.type != ControllerType.Mouse && Player0.controllers != null && !Player0.controllers.hasKeyboard && Player1.controllers != null && !Player1.controllers.hasKeyboard)
			{
				AssignKeyboardMouseToPlayer(Player0);
			}
		}
		AssignControllerToPlayer(tempPlayer, controller, removeFromOtherPlayers: true);
		chaosInputs[tempPlayer].SetPrimaryController(controller);
		return chaosInputs[tempPlayer];
	}

	public static bool IsControllerAssigned(Controller controller, Rewired.Player excludePlayer = null)
	{
