	private void OnControllerConnected(ControllerStatusChangedEventArgs args)
	{
		for (int i = 0; i < Players.Length; i++)
		{
			if (Players[i] == null)
			{
				continue;
			}
			if (chaosInputs[Players[i]].primaryController == args.controller)
			{
				AssignControllerToPlayer(Players[i], args.controller, removeFromOtherPlayers: true);
				return;
			}
			if (chaosInputs[Players[i]].controllerCount == 0 && ((i == 0 && GameController.p1Joined) || (i == 1 && GameController.p2Joined)))
			{
				tempController = GetFreeController();
				if (tempController != null)
				{
					AssignControllerToPlayer(Players[i], tempController, removeFromOtherPlayers: false);
					return;
				}
			}
			else if (i == 0 && GameController.p1Joined && !GameController.coopOn && !GameController.pvpOn)
			{
				AssignControllerToPlayer(Players[i], args.controller, removeFromOtherPlayers: true);
				return;
			}
		}
		AssignControllerToPlayer(SysPlayer, args.controller, removeFromOtherPlayers: true);
	}

	private void OnControllerDisconnected(ControllerStatusChangedEventArgs args)
	{
		for (int i = 0; i < Players.Length; i++)
		{
			if (Players[i] == null)
			{
				continue;
			}
			if (chaosInputs[Players[i]].primaryController != null && args.controller != null && chaosInputs[Players[i]].primaryController == args.controller && !GameUI.pauseMenu.paused)
			{
				GameController.pauseQueued = true;
			}
			Players[i].controllers.RemoveController(args.controllerType, args.controllerId);
			if (!ChaosInputDevice.lockControllerInput && chaosInputs[Players[i]].controllerCount <= 0 && chaosInputs != null && chaosInputs.ContainsKey(Players[i]) && chaosInputs[Players[i]].controllerCount == 0 && ((i == 0 && GameController.p1Joined) || (i == 1 && GameController.p2Joined)))
			{
				tempController = GetFreeController();
				if (tempController != null)
				{
					AssignControllerToPlayer(Players[i], tempController, removeFromOtherPlayers: false);
				}
			}
		}
	}

	public static void AssignAllControllersToPlayer(Rewired.Player player, bool removeFromOtherPlayers, Controller excludeController = null)
	{
		foreach (Controller controller in ReInput.controllers.Controllers)
		{
			if (controller != null && (excludeController == null || (controller != excludeController && (excludeController.type != ControllerType.Mouse || controller.type != ControllerType.Keyboard) && (excludeController.type != ControllerType.Keyboard || controller.type != ControllerType.Mouse))))
			{
				AssignControllerToPlayer(player, controller, removeFromOtherPlayers);
			}
		}
	}

	public static void AssignControllerToPlayer(Rewired.Player player, Controller controller, bool removeFromOtherPlayers, bool ignoreKBMouseCheck = false)
	{
		if (player != null && controller != null && !player.controllers.ContainsController(controller))
		{
			if (!ignoreKBMouseCheck && (controller.type == ControllerType.Keyboard || controller.type == ControllerType.Mouse))
			{
				AssignKeyboardMouseToPlayer(tempPlayer);
			}
			else
			{
				player.controllers.AddController(controller, removeFromOtherPlayers);
			}
		}
	}

	public static void AssignKeyboardMouseToPlayer(Rewired.Player player)
	{
		for (int i = 0; i < Players.Length; i++)
		{
			foreach (Controller controller in Players[i].controllers.Controllers)
			{
				if (controller.type == ControllerType.Mouse || controller.type == ControllerType.Keyboard)
				{
					AssignControllerToPlayer(player, controller, removeFromOtherPlayers: true, ignoreKBMouseCheck: true);
				}
			}
		}
	}

	public static void LoadDefaultMaps()
	{
		Rewired.Player[] players = Players;
		foreach (Rewired.Player player in players)
		{
			player.controllers.maps.LoadDefaultMaps(ControllerType.Mouse);
			player.controllers.maps.LoadDefaultMaps(ControllerType.Keyboard);
			player.controllers.maps.LoadDefaultMaps(ControllerType.Joystick);
			player.controllers.maps.LoadDefaultMaps(ControllerType.Custom);
			InputMapHelper.InitAllMaps();
		}
	}

