using System.Collections.Generic;
using Rewired;
using UnityEngine;

public class InputMapHelper
{
	private static List<ControllerMap> keyboardMaps;

	private static List<ControllerMap> mouseMaps;

	private static List<ActionElementMap> actionMaps = new List<ActionElementMap>(5);

	private static List<ControllerMap> tempMaps = new List<ControllerMap>(10);

	private static List<KeyCode> MouseKeyCodes = new List<KeyCode>
	{
		KeyCode.Mouse0,
		KeyCode.Mouse1,
		KeyCode.Mouse2,
		KeyCode.Mouse3,
		KeyCode.Mouse4,
		KeyCode.Mouse5
	};

	private static List<ElementAssignmentConflictInfo> tempConflicts = new List<ElementAssignmentConflictInfo>();

	private static ActionElementMap tempActionMap;

	private static int tempActionID = 0;

	private static int tempCounter = 0;

	private static int tempIndex = 0;

	public static List<ControllerMap> KeyboardMaps
	{
		get
		{
			if (keyboardMaps == null)
			{
				InitAllMaps();
			}
			return keyboardMaps;
		}
	}

	public static List<ControllerMap> MouseMaps
	{
		get
		{
			if (mouseMaps == null)
			{
				InitAllMaps();
			}
			return mouseMaps;
		}
	}

	public static void InitAllMaps()
	{
		if (keyboardMaps == null)
		{
			keyboardMaps = new List<ControllerMap>();
		}
		else
		{
			keyboardMaps.Clear();
		}
		if (mouseMaps == null)
		{
			mouseMaps = new List<ControllerMap>();
		}
		else
		{
			mouseMaps.Clear();
		}
		Rewired.Player[] players = InputController.Players;
		foreach (Rewired.Player player in players)
		{
			tempMaps.Clear();
			player.controllers.maps.GetAllMaps(ControllerType.Keyboard, tempMaps);
			foreach (ControllerMap tempMap in tempMaps)
			{
				keyboardMaps.Add(tempMap);
			}
			tempMaps.Clear();
			player.controllers.maps.GetAllMaps(ControllerType.Mouse, tempMaps);
			foreach (ControllerMap tempMap2 in tempMaps)
			{
				mouseMaps.Add(tempMap2);
			}
		}
	}

	public static void CreateElementMapForAll(string actionName, KeyCode keyCode, Pole pole)
	{
		DeleteElementMapForAll(actionName, pole);
		tempActionID = ReInput.mapping.GetAction(actionName).id;
		if (MouseKeyCodes.Contains(keyCode))
		{
			foreach (Controller controller in ReInput.controllers.Controllers)
			{
				if (controller is Mouse)
				{
					tempCounter = 0;
					tempIndex = GetMouseButtonIndex(keyCode);
					foreach (ControllerElementIdentifier buttonElementIdentifier in controller.ButtonElementIdentifiers)
					{
						if (tempCounter == tempIndex)
						{
							break;
						}
					}
					if (tempIndex >= 0)
					{
						foreach (ControllerMap mouseMap in MouseMaps)
						{
							if (mouseMap.controllerId == controller.id)
							{
								tempActionMap = new ActionElementMap(tempActionID, controller.ButtonElementIdentifiers[tempIndex].elementType, controller.ButtonElementIdentifiers[tempIndex].id);
								mouseMap.RemoveElementAssignmentConflicts(tempActionMap);
								mouseMap.CreateElementMap(new ElementAssignment(ControllerType.Mouse, controller.ButtonElementIdentifiers[tempIndex].elementType, controller.ButtonElementIdentifiers[tempIndex].id, AxisRange.Full, keyCode, ModifierKeyFlags.None, tempActionID, pole, invert: false));
							}
						}
					}
				}
			}
			return;
		}
		foreach (ControllerMap keyboardMap in KeyboardMaps)
		{
			tempActionMap = new ActionElementMap(tempActionID, ControllerElementType.Button, pole, UnityToRewiredKeyCode(keyCode), ModifierKey.None, ModifierKey.None, ModifierKey.None);
			HandleConflicts(keyboardMap, tempActionMap);
			keyboardMap.CreateElementMap(ReInput.mapping.GetAction(actionName).id, pole, keyCode, ModifierKeyFlags.None);
		}
	}

	public static void HandleConflicts(ControllerMap cMap, ActionElementMap actionMap)
	{
		tempConflicts.Clear();
		foreach (ElementAssignmentConflictInfo item in cMap.ElementAssignmentConflicts(actionMap))
		{
			if (item.actionId != ReInput.mapping.GetAction("Cancel").id && item.actionId != ReInput.mapping.GetAction("Confirm").id && item.actionId != ReInput.mapping.GetAction("Menu").id && (item.actionId != ReInput.mapping.GetAction("MoveHorizontal").id || (item.keyCode != KeyCode.LeftArrow && item.keyCode != KeyCode.RightArrow)) && (item.actionId != ReInput.mapping.GetAction("MoveVertical").id || (item.keyCode != KeyCode.UpArrow && item.keyCode != KeyCode.DownArrow)))
			{
				tempConflicts.Add(item);
			}
		}
		for (int i = 0; i < tempConflicts.Count; i++)
		{
			cMap.DeleteElementMap(tempConflicts[i].elementMapId);
		}
	}

	public static void DeleteElementMapForAll(string actionName, Pole pole)
	{
		if (!actionName.Contains("Horizontal") && !actionName.Contains("Vertical"))
		{
			foreach (ControllerMap keyboardMap in KeyboardMaps)
			{
				keyboardMap.DeleteElementMapsWithAction(actionName);
			}
			{
				foreach (ControllerMap mouseMap in MouseMaps)
				{
					mouseMap.DeleteElementMapsWithAction(actionName);
				}
				return;
			}
		}
		foreach (ControllerMap keyboardMap2 in KeyboardMaps)
		{
			actionMaps.Clear();
			ActionElementMap[] buttonMapsWithAction = keyboardMap2.GetButtonMapsWithAction(actionName);
			foreach (ActionElementMap actionElementMap in buttonMapsWithAction)
			{
				if (actionElementMap.axisContribution == pole && (pole != Pole.Positive || (actionElementMap.keyCode != KeyCode.UpArrow && actionElementMap.keyCode != KeyCode.RightArrow)) && (pole != Pole.Negative || (actionElementMap.keyCode != KeyCode.DownArrow && actionElementMap.keyCode != KeyCode.LeftArrow)))
				{
					actionMaps.Add(actionElementMap);
				}
			}
			for (int j = 0; j < actionMaps.Count; j++)
			{
				keyboardMap2.DeleteElementMap(actionMaps[j].id);
			}
		}
		foreach (ControllerMap mouseMap2 in MouseMaps)
		{
			actionMaps.Clear();
			ActionElementMap[] buttonMapsWithAction2 = mouseMap2.GetButtonMapsWithAction(actionName);
			foreach (ActionElementMap actionElementMap2 in buttonMapsWithAction2)
			{
				if (actionElementMap2.axisContribution == pole)
				{
					actionMaps.Add(actionElementMap2);
				}
			}
			for (int l = 0; l < actionMaps.Count; l++)
			{
				mouseMap2.DeleteElementMap(actionMaps[l].id);
			}
		}
	}

