	public static string GetActionElementName(string actionName, bool useAxis = false, bool positive = true)
	{
		Rewired.Player[] players = InputController.Players;
		foreach (Rewired.Player player in players)
		{
			if (!player.controllers.hasKeyboard)
			{
				continue;
			}
			tempMaps.Clear();
			player.controllers.maps.GetAllMaps(ControllerType.Keyboard, tempMaps);
			foreach (ControllerMap tempMap in tempMaps)
			{
				tempActionMap = null;
				ActionElementMap[] buttonMapsWithAction = tempMap.GetButtonMapsWithAction(actionName);
				foreach (ActionElementMap actionElementMap in buttonMapsWithAction)
				{
					if (!(actionElementMap.elementIdentifierName == "None") && (!useAxis || (actionElementMap.axisContribution == Pole.Positive && positive) || (actionElementMap.axisContribution == Pole.Negative && !positive)))
					{
						if (actionElementMap.keyCode != KeyCode.UpArrow && actionElementMap.keyCode != KeyCode.DownArrow && actionElementMap.keyCode != KeyCode.LeftArrow && actionElementMap.keyCode != KeyCode.RightArrow)
						{
							return actionElementMap.elementIdentifierName;
						}
						tempActionMap = actionElementMap;
					}
				}
				if (tempActionMap != null)
				{
					return tempActionMap.elementIdentifierName;
				}
			}
			if (!player.controllers.hasMouse)
			{
				continue;
			}
			tempMaps.Clear();
			player.controllers.maps.GetAllMaps(ControllerType.Mouse, tempMaps);
			foreach (ControllerMap tempMap2 in tempMaps)
			{
				ActionElementMap[] buttonMapsWithAction2 = tempMap2.GetButtonMapsWithAction(actionName);
				foreach (ActionElementMap actionElementMap2 in buttonMapsWithAction2)
				{
					if (!(actionElementMap2.elementIdentifierName == "None") && (!useAxis || (actionElementMap2.axisContribution == Pole.Positive && positive) || (actionElementMap2.axisContribution == Pole.Negative && !positive)))
					{
						return actionElementMap2.elementIdentifierName;
					}
				}
			}
		}
		return "None";
	}

	public static KeyCode GetActionKeyCode(string actionName, bool useAxis, bool positive = true)
	{
		Rewired.Player[] players = InputController.Players;
		foreach (Rewired.Player player in players)
		{
			if (!player.controllers.hasKeyboard)
			{
				continue;
			}
			tempMaps.Clear();
			player.controllers.maps.GetAllMaps(ControllerType.Keyboard, tempMaps);
			foreach (ControllerMap tempMap in tempMaps)
			{
				tempActionMap = null;
				ActionElementMap[] buttonMapsWithAction = tempMap.GetButtonMapsWithAction(actionName);
				foreach (ActionElementMap actionElementMap in buttonMapsWithAction)
				{
					if (!(actionElementMap.elementIdentifierName == "None") && (!useAxis || (actionElementMap.axisContribution == Pole.Positive && positive) || (actionElementMap.axisContribution == Pole.Negative && !positive)))
					{
						if (actionElementMap.keyCode != KeyCode.UpArrow && actionElementMap.keyCode != KeyCode.DownArrow && actionElementMap.keyCode != KeyCode.LeftArrow && actionElementMap.keyCode != KeyCode.RightArrow)
						{
							return actionElementMap.keyCode;
						}
						tempActionMap = actionElementMap;
					}
				}
				if (tempActionMap != null)
				{
					return tempActionMap.keyCode;
				}
			}
			if (!player.controllers.hasMouse)
			{
				continue;
			}
			tempMaps.Clear();
			player.controllers.maps.GetAllMaps(ControllerType.Mouse, tempMaps);
			foreach (ControllerMap tempMap2 in tempMaps)
			{
				ActionElementMap[] buttonMapsWithAction2 = tempMap2.GetButtonMapsWithAction(actionName);
				foreach (ActionElementMap actionElementMap2 in buttonMapsWithAction2)
				{
					if (actionElementMap2.elementIdentifierName == "None" || (useAxis && (actionElementMap2.axisContribution != Pole.Positive || !positive) && (actionElementMap2.axisContribution != Pole.Negative || positive)))
					{
						continue;
					}
					tempCounter = 0;
					if (!(tempMap2.controller is Mouse))
					{
						continue;
					}
					foreach (ControllerElementIdentifier buttonElementIdentifier in ((Mouse)tempMap2.controller).ButtonElementIdentifiers)
					{
						if (actionElementMap2.elementIdentifierId != buttonElementIdentifier.id)
						{
							tempCounter++;
							continue;
						}
						return GetMouseButtonKeyCode(tempCounter);
					}
				}
			}
		}
		return KeyCode.None;
	}

	private static KeyCode GetMouseButtonKeyCode(int buttonIndex)
	{
		return buttonIndex switch
		{
			0 => KeyCode.Mouse0, 
			1 => KeyCode.Mouse1, 
			2 => KeyCode.Mouse2, 
			3 => KeyCode.Mouse3, 
			4 => KeyCode.Mouse4, 
			5 => KeyCode.Mouse5, 
			_ => KeyCode.None, 
		};
	}

	private static int GetMouseButtonIndex(KeyCode keyCode)
	{
		return keyCode switch
		{
			KeyCode.Mouse0 => 0, 
			KeyCode.Mouse1 => 1, 
			KeyCode.Mouse2 => 2, 
			KeyCode.Mouse3 => 3, 
			KeyCode.Mouse4 => 4, 
			KeyCode.Mouse5 => 5, 
			_ => -1, 
		};
	}

