public class ConfigMenu : MonoBehaviour
{
	public enum CInput
	{
		MoveUp,
		MoveDown,
		MoveLeft,
		MoveRight,
		Skill0,
		Skill1,
		Skill2,
		Skill3,
		Skill4,
		Skill5,
		Interact,
		Menu,
		MouseAim,
		MouseDash,
		Reset,
		Back,
		Map
	}

	private class ConfigMenuObjectReferences
	{
		public Dictionary<CInput, Text> fieldNameDict;

		public Dictionary<CInput, Text> fieldValueDict;

		public List<CInput> inputList;

		public GameObject confirmationWindow;

		public Image mouseAimFill;

		public Image mouseDashFill;

		public ConfigMenuObjectReferences()
		{
			fieldNameDict = new Dictionary<CInput, Text>();
			fieldValueDict = new Dictionary<CInput, Text>();
			inputList = new List<CInput>();
		}

		public void SetRef(CInput givenCInput, Transform givenTrans)
		{
			inputList.Add(givenCInput);
			Transform transform = givenTrans.Find("Text");
			if (transform != null)
			{
				fieldNameDict[givenCInput] = transform.GetComponent<Text>();
				TextManager.AddUIRef(string.Empty, fieldNameDict[givenCInput]);
			}
			transform = givenTrans.Find("FieldValue");
			if (transform != null)
			{
				fieldValueDict[givenCInput] = transform.GetComponent<Text>();
				TextManager.AddUIRef(string.Empty, fieldValueDict[givenCInput]);
			}
