	public void LoadMenu()
	{
		if (!isActive)
		{
			currentIndex = 0;
			firstFrame = true;
		}
		inConfirmWindow = false;
		exitConfirmWindow = false;
		isActive = true;
		LoadSettings();
		gameObject.SetActive(value: true);
		HighlightOption(currentIndex);
		RefreshFields();
	}

	public void ExitMenu(bool saveSettings = true)
	{
		if (saveSettings)
		{
			SaveSettings();
		}
		isActive = false;
		gameObject.SetActive(value: false);
	}

	private void Update()
	{
		if (firstFrame)
		{
			firstFrame = false;
		}
		else if (inConfirmWindow)
		{
			if (exitConfirmWindow)
			{
				exitConfirmWindow = false;
				inConfirmWindow = false;
				navLocked = true;
			}
			else if (Input.GetKeyUp(KeyCode.Escape) || InputKeyRecorded(currentCInput))
			{
				exitConfirmWindow = true;
				cmRef.confirmationWindow.SetActive(value: false);
				RefreshFields();
			}
		}
		else
		{
			HandleNavigation();
			if (InputController.GetAnyDeviceButtonUp("Cancel") != null)
			{
				CancelSelected();
			}
			if (InputController.GetAnyDeviceButtonDown("Confirm") != null)
			{
				ConfirmSelected();
			}
		}
	}

	private void RefreshFields()
	{
		cmRef.mouseAimFill.enabled = ChaosInputDevice.allowMouseAim;
		cmRef.mouseDashFill.enabled = ChaosInputDevice.allowMouseDash;
		foreach (KeyValuePair<CInput, Text> item in cmRef.fieldValueDict)
		{
			if (!(item.Value == null) && inputToHandleDict.ContainsKey(item.Key))
			{
				if (item.Key.ToString().Contains("Move"))
				{
					item.Value.text = InputMapHelper.GetActionElementName(InputToActionName[item.Key], useAxis: true, item.Key == CInput.MoveUp || item.Key == CInput.MoveRight);
				}
				else
				{
					item.Value.text = InputMapHelper.GetActionElementName(InputToActionName[item.Key]);
				}
			}
		}
	}

	private bool InputKeyRecorded(CInput givenInput)
	{
		if (Input.anyKeyDown)
		{
			KeyCode[] array = KeyCodeValues;
			for (int i = 0; i < array.Length; i++)
			{
				KeyCode keyCode = array[i];
				if (keyCode != KeyCode.Escape && keyCode != KeyCode.Return && !keyCode.ToString().Contains("Joystick") && Input.GetKeyDown(keyCode))
				{
					AssignKeyToInput(givenInput, keyCode);
					SoundManager.PlayConfirmAudio();
					return true;
				}
			}
		}
		return false;
	}

	private void AssignKeyToInput(CInput givenInput, KeyCode givenKey)
	{
		InputMapHelper.CreateElementMapForAll(InputToActionName[givenInput], givenKey, (givenInput == CInput.MoveDown || givenInput == CInput.MoveLeft) ? Pole.Negative : Pole.Positive);
	}

	private void RequestConfirm()
	{
		inConfirmWindow = true;
		cmRef.confirmationWindow.SetActive(value: true);
	}

	private void ConfirmSelected()
	{
		currentCInput = cmRef.inputList[currentIndex];
		switch (currentCInput)
		{
		case CInput.MouseAim:
			ChaosInputDevice.allowMouseAim = !ChaosInputDevice.allowMouseAim;
			if (!ChaosInputDevice.allowMouseAim)
			{
				ChaosInputDevice.allowMouseDash = false;
			}
			RefreshFields();
			SoundManager.PlayConfirmAudio();
			break;
		case CInput.MouseDash:
			ChaosInputDevice.allowMouseDash = !ChaosInputDevice.allowMouseDash;
			if (ChaosInputDevice.allowMouseDash)
			{
				ChaosInputDevice.allowMouseAim = true;
			}
			RefreshFields();
			SoundManager.PlayConfirmAudio();
			break;
		case CInput.Reset:
			GameDataManager.gameSettings.inputSettings.Reset();
			LoadMenu();
			RefreshFields();
			SoundManager.PlayConfirmAudio();
			break;
		case CInput.Back:
			ExitMenu();
			break;
		default:
			RequestConfirm();
			break;
		}
	}

	private void CancelSelected()
	{
		ExitMenu();
	}

	private void HandleNavigation(int givenIndex = -1)
	{
		if (givenIndex != -1 && givenIndex != currentIndex)
		{
			currentIndex = givenIndex;
		}
		else
		{
			switch (GetInputDirection())
			{
			case InputDirection.Up:
				if (!navLocked)
				{
					currentIndex--;
					if (currentIndex < 0)
					{
						currentIndex = cmRef.inputList.Count - 1;
					}
				}
				break;
			case InputDirection.Down:
				if (!navLocked)
				{
					currentIndex++;
					if (currentIndex >= cmRef.inputList.Count)
					{
						currentIndex = 0;
					}
				}
				break;
			default:
				navLocked = false;
				return;
			}
		}
		if (!navLocked)
		{
			SoundManager.PlayAudio("MenuMove", 1f, ignoreTimeRestriction: true);
		}
		HighlightOption(currentIndex);
		navLocked = true;
	}

	private void HighlightOption(int givenIndex)
	{
		for (int i = 0; i < cmRef.inputList.Count; i++)
		{
			CInput key = cmRef.inputList[i];
			if (i == givenIndex)
			{
				if (cmRef.fieldNameDict.ContainsKey(key))
				{
					cmRef.fieldNameDict[cmRef.inputList[i]].color = Globals.uiSelectedColor;
				}
				if (cmRef.fieldValueDict.ContainsKey(key))
				{
					cmRef.fieldValueDict[cmRef.inputList[i]].color = Globals.uiSelectedColor;
				}
			}
			else
			{
				if (cmRef.fieldNameDict.ContainsKey(key))
				{
					cmRef.fieldNameDict[cmRef.inputList[i]].color = Globals.uiNotSelectedColor;
				}
				if (cmRef.fieldValueDict.ContainsKey(key))
				{
					cmRef.fieldValueDict[cmRef.inputList[i]].color = Globals.uiNotSelectedColor;
				}
			}
		}
	}

	private InputDirection GetInputDirection()
	{
		if (InputController.GetAnyDeviceDirection(InputDirection.Down))
		{
			return InputDirection.Down;
		}
		if (InputController.GetAnyDeviceDirection(InputDirection.Up))
		{
			return InputDirection.Up;
		}
		return InputDirection.None;
	}

	public void FieldHovered(int value)
	{
		if (!inConfirmWindow)
		{
			HandleNavigation(value);
		}
	}

	public void FieldClicked()
	{
		if (!inConfirmWindow)
		{
			ConfirmSelected();
		}
	}

	public void LoadSettings()
	{
		InputSettings inputSettings = GameDataManager.gameSettings.inputSettings;
		InputController.LoadDefaultMaps();
		if (inputSettings != null)
		{
			ChaosInputDevice.allowMouseAim = inputSettings.useMouseAim;
			ChaosInputDevice.allowMouseDash = inputSettings.useMouseDash;
			foreach (KeyValuePair<string, KeyCode> item in inputSettings.inputKeyDict)
			{
				switch (item.Key)
				{
				case "MoveUp":
					AssignKeyToInput(CInput.MoveUp, item.Value);
					break;
				case "MoveDown":
					AssignKeyToInput(CInput.MoveDown, item.Value);
					break;
				case "MoveLeft":
					AssignKeyToInput(CInput.MoveLeft, item.Value);
					break;
				case "MoveRight":
					AssignKeyToInput(CInput.MoveRight, item.Value);
					break;
				case "Skill0":
					AssignKeyToInput(CInput.Skill0, item.Value);
					break;
				case "Skill1":
					AssignKeyToInput(CInput.Skill1, item.Value);
					break;
				case "Skill2":
					AssignKeyToInput(CInput.Skill2, item.Value);
					break;
				case "Skill3":
					AssignKeyToInput(CInput.Skill3, item.Value);
					break;
				case "Skill4":
					AssignKeyToInput(CInput.Skill4, item.Value);
					break;
				case "Skill5":
					AssignKeyToInput(CInput.Skill5, item.Value);
					break;
				case "Interact":
					AssignKeyToInput(CInput.Interact, item.Value);
					break;
				case "LeftTrigger":
					AssignKeyToInput(CInput.Menu, item.Value);
					break;
				case "Map":
					AssignKeyToInput(CInput.Map, item.Value);
					break;
				}
			}
		}
		GameUI.LoadInputButtonSprites();
	}

	public void SaveSettings()
	{
		if (GameDataManager.gameSettings.inputSettings == null)
		{
			GameDataManager.gameSettings.inputSettings = new InputSettings();
		}
		InputSettings inputSettings = GameDataManager.gameSettings.inputSettings;
		inputSettings.useMouseAim = ChaosInputDevice.allowMouseAim;
		inputSettings.useMouseDash = ChaosInputDevice.allowMouseDash;
		List<string> list = new List<string>(inputSettings.inputKeyDict.Keys);
		foreach (string item in list)
		{
			if (InputStrToActionName.ContainsKey(item))
			{
				if (item.Contains("Move"))
				{
					inputSettings.inputKeyDict[item] = InputMapHelper.GetActionKeyCode(InputStrToActionName[item], useAxis: true, !item.Contains("Down") && !item.Contains("Left"));
				}
				else
				{
					inputSettings.inputKeyDict[item] = InputMapHelper.GetActionKeyCode(InputStrToActionName[item], useAxis: false);
				}
			}
		}
		GameDataManager.SaveSettings();
		GameUI.LoadInputButtonSprites();
		GameUI.RefreshCDUI();
	}
}

