private void Update()
{
	if (!releaseControlToParent && !configMenu.isActive && HandleConfirmationProgress())
	{
		if (InputController.GetAnyDeviceButtonDown("Confirm") != null)
		{
			inputReceived = true;
		}
		else if (InputController.GetAnyDeviceButtonUp("Cancel") != null)
		{
			releaseControlToParent = true;
			return;
		}
		HandleValueUpdates(currentIndex);
		HandleNavigation();
	}
}

public void HandleNavigation(int forcedIndex = -1)
{
	if (configMenu.isActive || !HandleConfirmationProgress())
	{
		return;
	}
	if (forcedIndex != -1 && forcedIndex != currentIndex)
	{
		currentIndex = forcedIndex;
		SelectOption(currentIndex);
		SoundManager.PlayAudio("MenuMove", 1f, ignoreTimeRestriction: true);
	}
	else if (!vertNavLocked)
	{
		if (InputController.GetAnyDeviceDirection(InputDirection.Down))
		{
			currentIndex++;
			if (currentIndex >= settingsTextList.Count)
			{
				currentIndex = 0;
			}
			SelectOption(currentIndex);
			vertNavLocked = true;
			SoundManager.PlayAudio("MenuMove", 1f, ignoreTimeRestriction: true);
		}
		else if (InputController.GetAnyDeviceDirection(InputDirection.Up))
		{
			currentIndex--;
			if (currentIndex < 0)
			{
				currentIndex = settingsTextList.Count - 1;
			}
			SelectOption(currentIndex);
			vertNavLocked = true;
			SoundManager.PlayAudio("MenuMove", 1f, ignoreTimeRestriction: true);
		}
	}
	else if (!InputController.GetAnyDeviceDirection(InputDirection.Down) && !InputController.GetAnyDeviceDirection(InputDirection.Up))
	{
		vertNavLocked = false;
	}
}

public void SelectOption(int index)
{
	if (!configMenu.isActive && HandleConfirmationProgress())
	{
		for (int i = 0; i < settingsTextList.Count; i++)
		{
			settingsTextList[i].color = ((i != index) ? Globals.uiNotSelectedColor : Globals.uiSelectedColor);
		}
	}
}

public static IEnumerator SetCursorLock()
{
	yield return null;
	yield return null;
	Cursor.lockState = CursorLockMode.Confined;
}

private void HandleValueUpdates(int index)
{
	switch (index)
	{
	case 0:
		if (!horiNavLocked)
		{
			if (InputController.GetAnyDeviceDirection(InputDirection.Left))
			{
				resolutionSelectionIndex--;
				if (resolutionSelectionIndex < 0)
				{
					resolutionSelectionIndex = supportedResolutions.Count - 1;
				}
				horiNavLocked = true;
			}
			else if (InputController.GetAnyDeviceDirection(InputDirection.Right))
			{
				resolutionSelectionIndex++;
				if (resolutionSelectionIndex >= supportedResolutions.Count)
				{
					resolutionSelectionIndex = 0;
				}
				horiNavLocked = true;
			}
			tempResolution = supportedResolutions[resolutionSelectionIndex];
		}
		if (inputReceived)
		{
			Screen.SetResolution(tempResolution.width, tempResolution.height, Screen.fullScreen);
			SoundManager.PlayConfirmAudio();
			StartCoroutine(SetCursorLock());
		}
		break;
	case 1:
		if (inputReceived)
		{
			Screen.SetResolution(Screen.width, Screen.height, !Screen.fullScreen);
			SoundManager.PlayConfirmAudio();
			StartCoroutine(SetCursorLock());
		}
		break;
	case 2:
		HandleSlider(brightnessIntensity);
		break;
	case 3:
		if (inputReceived)
		{
			vSyncFill.SetActive(!vSyncFill.activeSelf);
			QualitySettings.vSyncCount = (vSyncFill.activeSelf ? 1 : 0);
			SoundManager.PlayConfirmAudio();
		}
		break;
	case 4:
		if (inputReceived)
		{
			systemCursorFill.SetActive(!systemCursorFill.activeSelf);
			GameController.mouseCursor.Toggle(!systemCursorFill.activeSelf);
			SoundManager.PlayConfirmAudio();
		}
		break;
	case 5:
		if (SoundManager.BGMPaused)
		{
			SoundManager.BGMPaused = false;
		}
		HandleSlider(bgmVolume);
		break;
	case 6:
		HandleSlider(sfxVolume);
		break;
	case 7:
		HandleSlider(cameraShakeIntensity);
		break;
	case 8:
		HandleSlider(minimapSize);
		break;
	case 9:
		if (inputReceived)
		{
			OverheadNumberPool.showNumbers = !OverheadNumberPool.showNumbers;
			SoundManager.PlayConfirmAudio();
		}
		break;
	case 10:
		if (!horiNavLocked)
		{
			if (InputController.GetAnyDeviceDirection(InputDirection.Left))
			{
				tempGamepadValue--;
				horiNavLocked = true;
			}
			else if (InputController.GetAnyDeviceDirection(InputDirection.Right))
			{
				tempGamepadValue++;
				horiNavLocked = true;
			}
			tempGamepadValue = Mathf.Clamp((tempGamepadValue + 3) % 3, 0, 2);
		}
		if (inputReceived)
		{
			currentGamepadValue = tempGamepadValue;
			SetGamepadType(currentGamepadValue);
		}
		break;
	case 11:
		if (inputReceived)
		{
			ChaosInputDevice.lockControllerAim = !ChaosInputDevice.lockControllerAim;
			SoundManager.PlayConfirmAudio();
		}
		break;
	case 12:
		if (inputReceived)
		{
			ChaosInputDevice.lockControllerInput = !ChaosInputDevice.lockControllerInput;
			SoundManager.PlayConfirmAudio();
		}
		break;
	case 13:
		if (!horiNavLocked)
		{
			if (InputController.GetAnyDeviceDirection(InputDirection.Left))
			{
				languageSelectionIndex--;
				if (languageSelectionIndex < 0)
				{
					languageSelectionIndex = Globals.availableLangList.Count - 1;
				}
				horiNavLocked = true;
			}
			else if (InputController.GetAnyDeviceDirection(InputDirection.Right))
			{
				languageSelectionIndex++;
				if (languageSelectionIndex >= Globals.availableLangList.Count)
				{
					languageSelectionIndex = 0;
				}
				horiNavLocked = true;
			}
			tempChaosLang = Globals.availableLangList[languageSelectionIndex];
		}
		if (inputReceived && currentChaosLang != tempChaosLang)
		{
			if (!HandleConfirmationRequest(3))
			{
				return;
			}
			currentChaosLang = tempChaosLang;
			TextManager.SetLanguage(currentChaosLang);
			GameUI.dialogManager.InitDialogDicts(currentChaosLang);
			SoundManager.PlayConfirmAudio();
			releaseControlToParent = true;
			GameController.LoadLevel("TitleScreen");
		}
		break;
	case 14:
		if (inputReceived)
		{
			configMenu.LoadMenu();
			SoundManager.PlayConfirmAudio();
		}
		break;
	case 15:
		if (inputReceived)
		{
			if (!HandleConfirmationRequest())
			{
				return;
			}
			confirmCount++;
			if (confirmCount < resetConfirmReq)
			{
				ResetConfirmation(resetCount: false);
				inputReceived = true;
				HandleConfirmationRequest();
				vertNavLocked = true;
				return;
			}
			GameController.resetGameDataQueued = true;
			releaseControlToParent = true;
		}
		break;
	case 16:
		if (inputReceived)
		{
			ResetAllValuesToDefault();
			SoundManager.PlayConfirmAudio();
		}
		break;
	case 17:
		if (inputReceived)
		{
			releaseControlToParent = true;
			return;
		}
		break;

		lockControllerInputFill.gameObject.SetActive(ChaosInputDevice.lockControllerInput);
		if (index == 13)
		{
			TextManager.SetUITextFromDict(currentLanguageText, tempChaosLang);
			currentLanguageText.text = TextManager.GetUIText("language-" + tempChaosLang);
		}
		else
		{
			TextManager.SetUITextFromDict(currentLanguageText, currentChaosLang);
			currentLanguageText.text = TextManager.GetUIText("language-" + currentChaosLang);
			languageSelectionIndex = Globals.availableLangList.IndexOf(currentChaosLang);
		}
		inputReceived = false;
	}

	private List<Resolution> GetSupportedResolutions()
	{
		List<Resolution> list = new List<Resolution>();
		Resolution[] resolutions = Screen.resolutions;
		foreach (Resolution item in resolutions)
		{
			list.Add(item);
		}
		return list;
	}

	private void HandleSlider(Slider slider)
	{
		if (InputController.GetAnyDeviceDirection(InputDirection.Left, downPressOnly: false))
		{
			slider.value -= sliderIncrementAmount;
		}
		else if (InputController.GetAnyDeviceDirection(InputDirection.Right, downPressOnly: false))
		{
			slider.value += sliderIncrementAmount;
		}
	}

	private void HandleAudioMixerValue(Slider slider, AudioMixer mixer, string volParamString)
	{
		mixer.SetFloat(volParamString, (slider.value != 0f) ? ((slider.value - 0.5f) * 30f - 5f) : (-80f));
	}

	private void SetGamepadType(int givenValue)
	{
		switch (givenValue)
		{
		case 1:
			GameUI.psGamepad = true;
			GameUI.switchGamepad = false;
			break;
		case 2:
			GameUI.psGamepad = false;
			GameUI.switchGamepad = true;
			break;
		default:
			GameUI.psGamepad = false;
			GameUI.switchGamepad = false;
			break;
		}
		GameUI.RefreshCDUI();
	}

	private void ResetAllValuesToDefault()
	{
		brightnessIntensity.value = 0.5f;
		bgmVolume.value = 0.5f;
		sfxVolume.value = 0.5f;
		cameraShakeIntensity.value = 0.5f;
		minimapSize.value = 0.5f;
		OverheadNumberPool.showNumbers = true;
		SaveSettings();
	}

	public void OptionClicked()
	{
		if (!configMenu.isActive && HandleConfirmationProgress())
		{
			inputReceived = true;
		}
	}

	public void PlayMenuMoveSound()
	{
		if (currentIndex == 6)
		{
			SoundManager.PlayAudio("MenuMove", 1f, ignoreTimeRestriction: true);
		}
	}

	private bool HandleConfirmationRequest(int overrideValue = -1)
	{
		if (confirmationStatus)
		{
			return true;
		}
		ConfirmHandlerUI.RequestConfirmation((overrideValue <= -1) ? confirmCount : overrideValue);
		confirmationRequested = true;
		inputReceived = false;
		hasFocus = false;
		return false;
	}

	private bool HandleConfirmationProgress()
	{
		if (confirmationRequested)
		{
			if (ConfirmHandlerUI.RequestInProgress)
			{
				confirmationStatus = ConfirmHandlerUI.RequestConfirmation();
				return false;
			}
			confirmationRequested = false;
			if (confirmationStatus)
			{
				inputReceived = true;
			}
			else
			{
				inputReceived = false;
				ResetConfirmation();
			}
			hasFocus = true;
		}
		return true;
	}

	private void ResetConfirmation(bool resetCount = true)
	{
		hasFocus = true;
		confirmationRequested = false;
		confirmationStatus = false;
		if (resetCount)
		{
			confirmCount = 0;
		}
	}
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class OptionsWindowUI : MonoBehaviour
{
	public Player currentPlayer;

	public bool hasFocus;

	public MainWindow.Option selectedOption;

	public bool optionWasClicked;

	private Image skillIcon;

	private Text skillName;

	private bool isMaxed;

	private bool isUltimate;

	private List<Image> optionsList;

	private List<Text> optionsListText;

	private Color maxedColor;

	private Color transparentColor;

	private bool inputReceived;

	private Vector2 cursorVector;

	private int currentIndex;

	private int prevIndex;

	private int originalIndex;

	private int optionsCount;

	private bool objectsSet;

	private void Start()
	{
		skillIcon = transform.Find("Title/SkillIcon").GetComponent<Image>();
		skillName = transform.Find("Title/SkillName").GetComponent<Text>();
		optionsList = new List<Image>();
		optionsList.Add(transform.Find("BuyOption").GetComponent<Image>());
		optionsList.Add(transform.Find("EquipOption").GetComponent<Image>());
		optionsList.Add(transform.Find("InfoOption").GetComponent<Image>());
		optionsList.Add(transform.Find("UltimateOption").GetComponent<Image>());
		optionsListText = new List<Text>();
		optionsListText.Add(transform.Find("BuyOption/Text").GetComponent<Text>());
		optionsListText.Add(transform.Find("EquipOption/Text").GetComponent<Text>());
		optionsListText.Add(transform.Find("InfoOption/Text").GetComponent<Text>());
		optionsListText.Add(transform.Find("UltimateOption/Text").GetComponent<Text>());
		transparentColor = Color.white;
		transparentColor.a = 0f;
		maxedColor = new Color(1f, 0.725f, 0f, 1f);
		objectsSet = true;
	}

	public void LoadMenu(Player.SkillState selectedSkill, bool updating = false)
	{
		if (!objectsSet)
		{
			Start();
		}
		skillIcon.sprite = IconManager.GetSkillIcon(selectedSkill.skillID);
		skillName.text = TextManager.GetSkillName(selectedSkill.skillID);
		isUltimate = selectedSkill.isUltimate;
		foreach (Image options in optionsList)
		{
			options.color = transparentColor;
		}
		foreach (Text item in optionsListText)
		{
			item.color = Color.white;
		}
		optionsListText[0].text = "Buy";
		optionsList[3].gameObject.SetActive(value: false);
		optionsCount = 3;
		isMaxed = false;
		if (selectedSkill.currentLevel == SkillStats.maxSkillLevel)
		{
			isMaxed = true;
			optionsListText[0].text = "MAX";
			optionsListText[0].color = maxedColor;
			optionsList[3].gameObject.SetActive(value: true);
			if (selectedSkill.isUltimate)
			{
				optionsListText[3].color = maxedColor;
			}
			else
			{
				optionsListText[3].color = Color.white;
			}
			optionsCount = 4;
		}
		else if (selectedSkill.skillData.GetValue<int>("goldCost", selectedSkill.currentLevel + 1) > Player.goldWallet.balance)
		{
			optionsListText[0].color = Color.gray;
		}
		if (selectedSkill.currentLevel == 0)
		{
			optionsListText[1].color = Color.gray;
		}
		if (!updating)
		{
			currentIndex = 0;
		}
		SelectOption(currentIndex);
		optionWasClicked = false;
	}

	private void Update()
	{
		if (hasFocus)
		{
			HandleNavigation();
		}
	}

	private void HandleNavigation()
	{
		originalIndex = currentIndex;
		if (optionsListText[currentIndex].color == Color.gray)
		{
			currentIndex = ChangeIndex(currentIndex, add: true);
			SelectOption(currentIndex);
		}
		cursorVector = currentPlayer.inputDevice.GetMoveVector();
		if (inputReceived && Mathf.Abs(cursorVector.y) < 0.2f)
		{
			inputReceived = false;
		}
		else
		{
			if (inputReceived || !(Mathf.Abs(cursorVector.y) > 0.3f))
			{
				return;
			}
			inputReceived = true;
			prevIndex = currentIndex;
			if (cursorVector.y > 0f)
			{
				originalIndex = currentIndex;
				currentIndex = ChangeIndex(currentIndex, add: false);
				while (currentIndex != originalIndex && optionsListText[currentIndex].color == Color.gray)
				{
					currentIndex = ChangeIndex(currentIndex, add: false);
				}
			}
			else
			{
				originalIndex = currentIndex;
				currentIndex = ChangeIndex(currentIndex, add: true);
				while (currentIndex != originalIndex && optionsListText[currentIndex].color == Color.gray)
				{
					currentIndex = ChangeIndex(currentIndex, add: true);
				}
			}
			SelectOption(currentIndex);
			if (currentIndex != originalIndex)
			{
				SoundManager.PlayAudio("MenuMove");
			}
		}
	}

	private int ChangeIndex(int index, bool add)
	{
		int num = index;
		num = ((!add) ? (num - 1) : (num + 1));
		if (num < 0)
		{
			num = optionsCount - 1;
		}
		else if (num >= optionsCount)
		{
			num = 0;
		}
		return num;
	}

	public void SelectOption(int index)
	{
		if (optionsListText[prevIndex].color != Color.gray)
		{
			optionsListText[prevIndex].color = Color.white;
		}
		if (prevIndex == 0 && isMaxed)
		{
			optionsListText[prevIndex].color = maxedColor;
		}
		else if (prevIndex == 3 && isUltimate)
		{
			optionsListText[prevIndex].color = maxedColor;
		}
		prevIndex = index;
		if (optionsListText[index].color != Color.gray)
		{
			optionsListText[index].color = Color.green;
		}
		currentIndex = index;
		switch (index)
		{
		case 0:
			selectedOption = MainWindow.Option.Buy;
			break;
		case 1:
			selectedOption = MainWindow.Option.Equip;
			break;
		case 2:
			selectedOption = MainWindow.Option.Info;
			break;
		case 3:
			selectedOption = MainWindow.Option.Ultimate;
			break;
		}
	}

	public bool BuySkill(Player.SkillState selectedSkill)
	{
		int num = 0;
		if (selectedSkill.currentLevel == SkillStats.maxSkillLevel)
		{
			SoundManager.PlayAudio("MenuError");
			return false;
		}
		num = selectedSkill.skillData.GetValue<int>("goldCost", selectedSkill.currentLevel + 1);
		if (Player.goldWallet.Withdraw(num))
		{
			selectedSkill.SetSkillLevel(selectedSkill.currentLevel + 1);
			SoundManager.PlayAudio("MenuBuy");
			return true;
		}
		SoundManager.PlayAudio("MenuError");
		return false;
	}

	public void MakeSelectionTransparent()
	{
		optionsListText[currentIndex].color = Color.white;
	}

	public void OptionClicked(int selection)
	{
		prevIndex = currentIndex;
		currentIndex = selection;
		SelectOption(currentIndex);
		optionWasClicked = true;
	}
}
