using UnityEngine;
using UnityEngine.UI;

public class PlayerStatusBar : MonoBehaviour
{
	private Player player;

	private Image statusBarBG;

	private Image playerPortrait;

	private bool initialized;

	private Image HPBarFill;

	private Image HPBarHurtFill;

	private Text HPText;

	private float currentHealth;

	private float prevHealth;

	private float changingHealth;

	private bool isHealthChanging;

	private float healthUpdateDelayTime = 1.5f;

	private int healthDelayStopwatchID = -1;

	public static float healthBlinkThreshold = 0.3f;

	private bool healthLowAudioPlayed;

	private float blinkSpeed;

	private float healthColorLerpValue;

	private bool healthLerpDown;

	private Canvas canvas;

	private Image overdriveBarFill;

	private Color overdriveFadeColor = Color.white;

	private bool overdriveFadeOut;

	public ItemStatusBar itemStatusBar;

	public ItemStatusBar.ItemWindow ItemWindow;

	public static ItemStatusBar.ItemWindow[] _itemWindows;

	public static ItemStatusBar.ItemWindow[] ItemWindows
	{
		get
		{
			if (_itemWindows == null)
			{
				_itemWindows = new ItemStatusBar.ItemWindow[GameController.maxPlayerCount];
			}
			return _itemWindows;
		}
	}

	private void Awake()
	{
		Object.DontDestroyOnLoad(gameObject);
		canvas = GetComponent<Canvas>();
		Transform transform = base.transform.Find("HealthBar");
		statusBarBG = transform.Find("StatusBarBG").GetComponent<Image>();
		HPText = transform.Find("HPText").GetComponent<Text>();
		HPBarHurtFill = transform.Find("HPBarHurtFill").GetComponent<Image>();
		HPBarFill = HPBarHurtFill.transform.Find("HPBarFill").GetComponent<Image>();
		playerPortrait = transform.Find("PlayerPortrait").GetComponent<Image>();
		overdriveBarFill = transform.Find("OverdriveBarFill").GetComponent<Image>();
		itemStatusBar = base.transform.Find("ItemBar").GetComponent<ItemStatusBar>();
	}

	public static PlayerStatusBar ClaimPlayerStatusBar(Player newPlayer)
	{
		PlayerStatusBar playerStatusBar = GameController.playerStatusBars[(newPlayer.playerID != 0) ? 1u : 0u];
		playerStatusBar.Claim(newPlayer);
		ItemWindows[newPlayer.playerID] = playerStatusBar.itemStatusBar.itemWindow;
		playerStatusBar.itemStatusBar.playerID = newPlayer.playerID;
		playerStatusBar.itemStatusBar.itemWindow.playerID = newPlayer.playerID;
		if (newPlayer.playerID == 1)
		{
			playerStatusBar.itemStatusBar.itemWindow.Initialize(playerStatusBar.itemStatusBar.transform, playerStatusBar.itemStatusBar);
		}
		return playerStatusBar;
	}

	public static void ClaimWithoutInit(Player newPlayer)
	{
		if (!(newPlayer == null))
		{
			int num = ((newPlayer.playerID != 0) ? 1 : 0);
			if (GameController.playerStatusBars[num] != null && GameController.playerStatusBars[num].gameObject != null)
			{
				GameController.playerStatusBars[num].Claim(newPlayer);
			}
		}
	}

	private void Claim(Player givenPlayer)
	{
		Reset();
		player = givenPlayer;
		if (playerPortrait != null)
		{
			Material material = Object.Instantiate(playerPortrait.material);
			material.SetFloat("_PaletteIndex", player.outfitColorIndex);
			playerPortrait.material = material;
		}
		if (!initialized && player.playerID > 0)
		{
			foreach (Transform item in base.transform)
			{
				RectTransform component = item.GetComponent<RectTransform>();
				if (component.gameObject.name == "ItemBar")
				{
					component.anchoredPosition = new Vector2(component.anchoredPosition.x + 264f, component.anchoredPosition.y);
				}
				else
				{
					component.anchoredPosition = new Vector2(component.anchoredPosition.x + 366f, component.anchoredPosition.y);
				}
			}
			initialized = true;
		}
		if (canvas != null)
		{
			canvas.enabled = true;
		}
		if (gameObject != null)
		{
			gameObject.SetActive(value: true);
		}
	}

	private void Release()
	{
		Reset();
		canvas.enabled = false;
		gameObject.SetActive(value: false);
	}

	private void Reset()
	{
		player = null;
		isHealthChanging = false;
		changingHealth = 0f;
		currentHealth = 0f;
		prevHealth = 0f;
		if (itemStatusBar != null)
		{
			itemStatusBar.playerID = -1;
		}
	}

	private void Update()
	{
		if (player == null)
		{
			if (gameObject.activeSelf)
			{
				Release();
			}
		}
		else
		{
			HandleHealth();
			HandleOverdrive();
		}
	}

	private void HandleHealth()
	{
		currentHealth = player.health.healthStat.CurrentValue;
		if (currentHealth < prevHealth)
		{
			if (ChaosStopwatch.Check(healthDelayStopwatchID))
			{
				changingHealth = prevHealth;
			}
			healthDelayStopwatchID = ChaosStopwatch.Begin(healthUpdateDelayTime);
		}
		changingHealth -= ((!(changingHealth > currentHealth)) ? 0f : (Time.deltaTime * 25f));
		prevHealth = currentHealth;
		HPBarFill.fillAmount = player.health.HealthPercentage;
		HPBarHurtFill.fillAmount = changingHealth / player.health.healthStat.ModifiedValue;
		HPText.text = (int)currentHealth/*cast due to constrained. prefix*/ + "/" + (int)player.health.healthStat.ModifiedValue/*cast due to constrained. prefix*/;
		if (HPBarFill.fillAmount <= healthBlinkThreshold && HPBarFill.fillAmount != 0f)
		{
			blinkSpeed = Mathf.Max(healthBlinkThreshold - HPBarFill.fillAmount, 0.1f) * 22f;
			if (healthColorLerpValue >= 1f)
			{
				healthLerpDown = true;
			}
			if (healthColorLerpValue <= 0f)
			{
				healthLerpDown = false;
			}
			healthColorLerpValue += blinkSpeed * Time.deltaTime * (float)((!healthLerpDown) ? 1 : (-1));
			statusBarBG.color = Color.Lerp(Color.white, Color.red, healthColorLerpValue);
			playerPortrait.color = statusBarBG.color;
			if (!healthLowAudioPlayed && !LoadingScreen.loading)
			{
				healthLowAudioPlayed = true;
				SoundManager.PlayAudio("HealthLow");
			}
		}
		else
		{
			statusBarBG.color = Color.white;
			playerPortrait.color = Color.white;
			healthLowAudioPlayed = false;
		}
	}

	private void HandleOverdrive()
	{
		float overdrivePercentage = player.OverdrivePercentage;
		overdriveBarFill.fillAmount = overdrivePercentage;
		if (player.overdriveReady)
		{
			overdriveBarFill.color = overdriveFadeColor;
			if (overdriveFadeColor.a >= 1f)
			{
				overdriveFadeOut = true;
			}
			else if (overdriveFadeColor.a <= 0.4f)
			{
				overdriveFadeOut = false;
			}
			overdriveFadeColor.a += Time.deltaTime * 2.5f * (float)((!overdriveFadeOut) ? 1 : (-1));
		}
		else
		{
			overdriveFadeColor.a = 1f;
			overdriveBarFill.color = Color.white;
		}
	}
}
