	protected Image uiBarImage;

	public bool destroyOnNullParent = true;

	public virtual void Awake()
	{
		uiBarImage = transform.Find("BarImage").GetComponent<Image>();
	}

	public virtual void LateUpdate()
	{
		if (parentTrans == null)
		{
			if (destroyOnNullParent)
			{
				Object.Destroy(gameObject);
			}
		}
		else
		{
			transform.position = parentTrans.position;
		}
	}

	public virtual void SetBarDimensions(float xMin, float xMax, float yMin, float yMax)
	{
		RectTransform component = uiBarImage.transform.GetComponent<RectTransform>();
		component.anchorMin = new Vector2(xMin, yMin);
		component.anchorMax = new Vector2(xMax, yMax);
		component.offsetMin = Vector2.zero;
		component.offsetMax = Vector2.zero;
	}

	public virtual void SetBarColor(Color givenColor)
	{
		uiBarImage.color = givenColor;
	}

	public virtual void SetBarVisible(bool givenStatus)
	{
		uiBarImage.enabled = givenStatus;
	}

	public virtual void SetFillValue(float givenValue)
	{
		uiBarImage.fillAmount = givenValue;
	}
}
