using System.Collections.Generic;
using System.Linq;
using UnityEngine;
using UnityEngine.UI;

public class ItemStatusBar : MonoBehaviour
{
	public enum ItemState
	{
		Disabled,
		Ready,
		Active
	}

	public class ItemWindow
	{
		public class ItemObj
		{
			public ItemState itemState;

			public GameObject obj;

			public Image iconImage;

			public Image iconBG;

			public Image iconBorder;

			public ItemStatusBar parentItemStatusBar;

			public ItemObj(GameObject givenObj, Image givenImg, Image givenIconBG, Image givenIconBorder, ItemStatusBar parentBar)
			{
				itemState = ItemState.Disabled;
				obj = givenObj;
				iconImage = givenImg;
				iconBG = givenIconBG;
				iconBorder = givenIconBorder;
				parentItemStatusBar = parentBar;
			}

			public void Clear()
			{
				itemState = ItemState.Disabled;
				if (iconImage != null)
				{
					iconImage.sprite = null;
				}
				if (obj != null)
				{
					obj.SetActive(value: false);
				}
			}

			public void SetObjVars(ItemState givenState, Sprite givenSprite = null)
			{
				if (!(obj == null))
				{
					if (!obj.activeSelf)
					{
						obj.SetActive(value: true);
					}
					if (givenSprite != null)
					{
						iconImage.sprite = givenSprite;
					}
					switch (givenState)
					{
					case ItemState.Disabled:
						iconImage.color = disabledColor;
						iconBG.sprite = parentItemStatusBar.defaultBG;
						iconBG.color = defaultBGColor;
						iconBorder.color = defaultBorderColor;
						break;
					case ItemState.Ready:
						iconImage.color = readyColor;
						iconBG.sprite = parentItemStatusBar.defaultBG;
						iconBG.color = defaultBGColor;
						iconBorder.color = defaultBorderColor;
						break;
					case ItemState.Active:
						iconImage.color = readyColor;
						iconBG.sprite = parentItemStatusBar.activeBG;
						iconBG.color = activeBGColor;
						iconBorder.color = activeBorderColor;
						break;
					}
				}
			}
		}

		public class ItemInfo
		{
			public string itemID = string.Empty;

			public int index;

			public ItemState itemState;

			public ItemInfo(string givenID = "", ItemState givenState = ItemState.Disabled)
			{
				SetInfo(givenID, givenState);
			}

			public void SetInfo(string givenID = "", ItemState givenState = ItemState.Disabled, int givenIndex = 0)
			{
				itemID = givenID;
				index = givenIndex;
				itemState = givenState;
			}
		}

		public int playerID = -1;

		private Dictionary<string, ItemInfo> itemsDict = new Dictionary<string, ItemInfo>();

		private ItemObj[] itemObjs = new ItemObj[12];

		private int ItemsCount => itemsDict.Count;

		public ItemWindow(Transform givenTrans, ItemStatusBar parentItemStatusBar)
		{
			Initialize(givenTrans, parentItemStatusBar);
		}

		public void Initialize(Transform givenTrans, ItemStatusBar parentItemStatusBar)
		{
			if (playerID == 1)
			{
				int num = 0;
				for (int num2 = 11; num2 >= 0; num2--)
				{
					itemObjs[num] = new ItemObj(givenTrans.Find("Icon" + num2).gameObject, givenTrans.Find("Icon" + num2 + "/Icon").GetComponent<Image>(), givenTrans.Find("Icon" + num2 + "/IconBG").GetComponent<Image>(), givenTrans.Find("Icon" + num2 + "/IconBorder").GetComponent<Image>(), parentItemStatusBar);
					itemObjs[num].Clear();
					num++;
				}
			}
			else
			{
				for (int i = 0; i < 12; i++)
				{
					itemObjs[i] = new ItemObj(givenTrans.Find("Icon" + i).gameObject, givenTrans.Find("Icon" + i + "/Icon").GetComponent<Image>(), givenTrans.Find("Icon" + i + "/IconBG").GetComponent<Image>(), givenTrans.Find("Icon" + i + "/IconBorder").GetComponent<Image>(), parentItemStatusBar);
					itemObjs[i].Clear();
				}
			}
			itemsDict.Clear();
		}

		public void UpdateItem(string givenID, ItemState givenState)
		{
			if (!itemsDict.ContainsKey(givenID))
			{
				itemsDict[givenID] = new ItemInfo(givenID);
				Rearrange();
			}
			if (itemsDict[givenID].itemState != givenState)
			{
				itemsDict[givenID].itemState = givenState;
				switch (givenState)
				{
				case ItemState.Active:
					SoundManager.PlayAudio("ItemActivate");
					break;
				case ItemState.Ready:
					SoundManager.PlayAudio("ItemReady");
					break;
				case ItemState.Disabled:
					SoundManager.PlayAudio("ItemDeactivate");
					break;
				}
				Rearrange();
			}
		}

		public void RemoveItem(string givenID)
		{
			itemsDict.Remove(givenID);
			Rearrange();
		}

		private void Rearrange()
		{
			string[] array = itemsDict.Keys.ToArray();
			for (int i = 0; i < 12; i++)
			{
				if (i < array.Length)
				{
					itemsDict[array[i]].index = i;
					itemObjs[i].SetObjVars(itemsDict[array[i]].itemState, IconManager.GetItemIcon(array[i]));
				}
				else
				{
					itemObjs[i].Clear();
				}
			}
		}
	}

	private static GameObject prefab;

	private const int maxItemCount = 12;

	private static Color disabledColor = new Color(0.4f, 0.4f, 0.4f, 0.7f);

	private static Color readyColor = new Color(1f, 1f, 1f, 0.8f);

	private static Color activeBGColor = new Color32(208, 247, byte.MaxValue, 102);

	private static Color activeBorderColor = new Color32(219, 249, byte.MaxValue, 115);

	private static Color defaultBorderColor = new Color32(109, 109, 109, 80);

	private static Color defaultBGColor = new Color(0f, 0f, 0f, 0.31f);

	public Sprite defaultBG;

	public Sprite activeBG;

	public int playerID = -1;

	public ItemWindow itemWindow;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/UI/ItemStatusBar.prefab"));

	private void Awake()
	{
		itemWindow = new ItemWindow(transform, this);
	}

	public static void UpdateItem(int playerID, string givenID, ItemState givenState)
	{
		PlayerStatusBar.ItemWindows[playerID].UpdateItem(givenID, givenState);
	}

	public static void RemoveItem(int playerID, string givenID)
	{
		PlayerStatusBar.ItemWindows[playerID].RemoveItem(givenID);
	}
}
using UnityEngine;
using UnityEngine.UI;

public class LowerHUD
{
	private GameObject hudObj;

	public Player player;

	public CooldownUI cooldownUI;

	private bool equipMenuActive;

	private bool equipMenuAllowed;

	private OutfitMenu outfitMenu;

	private EquipMenu equipMenu;

	private InventoryMenu inventoryMenu;

	private GameObject infoWindow;

	private Text infoText;

	private StockSkillUI stockSkill;

	private bool MenuAvailable => player != null && player.enabled && (player.currentStateName == "Idle" || player.currentStateName == "Run" || player.currentStateName == "Paused");

	public LowerHUD(Transform hudTrans)
	{
		player = null;
		hudObj = hudTrans.gameObject;
		cooldownUI = hudTrans.Find("CooldownUI").GetComponent<CooldownUI>();
		outfitMenu = hudTrans.Find("OutfitMenu").GetComponent<OutfitMenu>();
		equipMenu = hudTrans.Find("EquipMenu").GetComponent<EquipMenu>();
		stockSkill = hudTrans.Find("StockSkill").GetComponent<StockSkillUI>();
		inventoryMenu = hudTrans.Find("InventoryMenu").GetComponent<InventoryMenu>();
		infoWindow = hudTrans.Find("Info").gameObject;
		TextManager.AddUIRef("playerMenu-infoTitle", hudTrans.Find("Info/TitleBar/Text").GetComponent<Text>());
		infoText = hudTrans.Find("Info/InfoText").GetComponent<Text>();
		TextManager.AddUIRef(string.Empty, infoText);
		infoWindow.SetActive(value: false);
		outfitMenu.equipMenu = equipMenu;
		outfitMenu.inventoryMenu = inventoryMenu;
		outfitMenu.infoText = infoText;
		equipMenu.outfitMenu = outfitMenu;
		equipMenu.inventoryMenu = inventoryMenu;
		equipMenu.infoText = infoText;
		inventoryMenu.equipMenu = equipMenu;
		inventoryMenu.outfitMenu = outfitMenu;
		inventoryMenu.infoText = infoText;
		cooldownUI.stockSkill = stockSkill;
		stockSkill.skillBGSprites = cooldownUI.skillBGSprites;
		equipMenuActive = false;
		equipMenuAllowed = true;
		Release();
	}

	public void Update()
	{
		if (!(player == null))
		{
			HandleEquipMenu();
		}
	}

	private void HandleEquipMenu()
	{
		if (!equipMenuAllowed)
		{
			if (equipMenuActive)
			{
				SetEquipMenuStatus(givenStatus: false);
			}
			return;
		}
		if (player.inputDevice.GetButtonDown("EquipMenu") && MenuAvailable)
		{
			if (equipMenu.gameObject.activeSelf)
			{
				SetEquipMenuStatus(givenStatus: false);
			}
			else if (player.fsm.currentStateName != "Paused")
			{
				SetEquipMenuStatus(givenStatus: true);
			}
		}
		if (equipMenuActive && (player.inputDevice.GetButtonUp("Cancel") || !MenuAvailable))
		{
			SetEquipMenuStatus(givenStatus: false);
		}
	}

	public void SetEquipMenuStatus(bool givenStatus)
	{
		if (givenStatus)
		{
			equipMenu.gameObject.SetActive(value: true);
			equipMenu.LoadEquipMenu();
			inventoryMenu.LoadMenu(player);
			outfitMenu.LoadMenu(player);
			if (!infoWindow.activeSelf)
			{
				infoWindow.SetActive(value: true);
			}
			equipMenuActive = true;
		}
		else
		{
			equipMenu.ExitMenu();
			inventoryMenu.ExitMenu();
			outfitMenu.ExitMenu();
			if (infoWindow.activeSelf)
			{
				infoWindow.SetActive(value: false);
			}
			equipMenuActive = false;
		}
	}

	public void SetEquipMenuAllowed(bool givenStatus)
	{
		equipMenuAllowed = givenStatus;
		if (!equipMenuAllowed && equipMenuActive)
		{
			SetEquipMenuStatus(givenStatus: false);
		}
	}

	public void Claim(Player newPlayer)
	{
		player = newPlayer;
		cooldownUI.Claim(newPlayer);
		stockSkill.Claim(newPlayer);
		equipMenu.referencesFound = false;
		equipMenu.player = newPlayer;
		equipMenu.parentHUD = this;
		SetEquipMenuStatus(givenStatus: false);
		SetVisibleStatus();
	}

	public void Release()
	{
		if (!(hudObj == null))
		{
			player = null;
			cooldownUI.Release();
			stockSkill.Release();
			equipMenu.Release();
			SetVisibleStatus(givenStatus: false);
		}
	}

	public void SetVisibleStatus(bool givenStatus = true)
	{
		hudObj.SetActive(givenStatus);
	}
}

using System;
using System.Collections.Generic;
using Chaos.ArrayExtensions;
using UnityEngine;

public class CooldownUI : MonoBehaviour
{
	public Sprite[] skillBGSprites;

	public static Color readyBorderColor = new Color32(160, 160, 160, byte.MaxValue);

	public static Color notReadyBorderColor = new Color32(170, 170, 170, 60);

	public static Color signatureColor = new Color32(byte.MaxValue, 204, 0, byte.MaxValue);

	public static Color fullColor = new Color(1f, 1f, 1f, 1f);

	public static Color transparent = new Color(1f, 1f, 1f, 0.6f);

	public static Color darkened = new Color(0.4f, 0.4f, 0.4f, 0.6f);

	private CooldownEntry[] cooldownEntries;

	private Player player;

	public StockSkillUI stockSkill;

	private float cooldownPingDelay = 0.5f;

	private int cdPingStopwatchID;

	public void Awake()
	{
		List<CooldownEntry> list = new List<CooldownEntry>();
		int num = 0;
		Transform transform = base.transform.Find("Skill" + num);
		while (transform != null)
		{
			CooldownEntry item = new CooldownEntry(transform, this);
			list.Add(item);
			num++;
			transform = base.transform.Find("Skill" + num);
		}
		cooldownEntries = list.ToArray();
		Release();
	}

	public void Claim(Player newPlayer)
	{
		this.player = newPlayer;
		RefreshEntries();
		gameObject.SetActive(value: true);
		cdPingStopwatchID = ChaosStopwatch.Begin(cooldownPingDelay);
		Player player = this.player;
		player.assignSkillSlotEventHandlers = (Player.AssignSkillSlotEventHandler)Delegate.Combine(player.assignSkillSlotEventHandlers, new Player.AssignSkillSlotEventHandler(AssignSkillEvent));
	}

	public void Release()
	{
		if (this.player != null)
		{
			Player player = this.player;
			player.assignSkillSlotEventHandlers = (Player.AssignSkillSlotEventHandler)Delegate.Remove(player.assignSkillSlotEventHandlers, new Player.AssignSkillSlotEventHandler(AssignSkillEvent));
		}
		this.player = null;
		if (gameObject != null)
		{
			gameObject.SetActive(value: false);
		}
	}

	public void RefreshEntries()
	{
		if (!(player == null) && !GameController.hideUI && GameController.activePlayers.Contains(player))
		{
			for (int i = 0; i < player.assignedSkills.Length; i++)
			{
				cooldownEntries[i].SetSkill(player.assignedSkills[i], player.inputDevice, i);
			}
			if (stockSkill != null)
			{
				stockSkill.RefreshUI();
			}
		}
	}

	public void LateUpdate()
	{
		if (!(player == null) && !GameController.hideUI)
		{
			CooldownEntry[] array = cooldownEntries;
			foreach (CooldownEntry cooldownEntry in array)
			{
				cooldownEntry.EntryUpdate();
			}
		}
	}

	public void RequestCDPing(string skillID)
	{
		if (ChaosStopwatch.Check(cdPingStopwatchID))
		{
			cdPingStopwatchID = ChaosStopwatch.Begin(cooldownPingDelay);
			player.hud.CooldownPing(skillID);
		}
	}

	public static Sprite GetKeySpriteFromSkillSlot(int skillSlot, ChaosInputDevice inputDev)
	{
		string inputName = "Slot" + skillSlot;
		if (skillSlot < 0 || skillSlot > 5)
		{
			inputName = "EquipMenu";
		}
		return GameUI.GetInputSprite(inputDev.inputScheme, inputName);
	}

	public void AssignSkillEvent(Player.SkillState newSkill, int skillSlotNum)
	{
		if (cooldownEntries[skillSlotNum] != null)
		{
			if (newSkill == null)
			{
				cooldownEntries[skillSlotNum].SetSkillBGSprite(isSignature: false, isEmpowered: false);
			}
			else
			{
				cooldownEntries[skillSlotNum].SetSkillBGSprite(newSkill.isSignature, newSkill.IsEmpowered);
			}
		}
	}
}
