	private static void LoadKeyboardSprite(string inputKey, string iconKey)
	{
		if (iconKey.Contains("Mouse"))
		{
			iconKey = "M" + iconKey.Substring(5);
		}
		else if (iconKey.Contains("Alpha"))
		{
			iconKey = iconKey.Substring(5);
		}
		else if (iconKey.Contains("Keypad"))
		{
			iconKey = iconKey.Substring(6);
		}
		InputButtonSprites[inputKey] = ((!KeyboardKeyIcons.ContainsKey(iconKey)) ? KeyboardKeyIcons["KeyNotFound"] : KeyboardKeyIcons[iconKey]);
	}

	private static bool IsValidInputKeyDict(Dictionary<string, KeyCode> givenDict)
	{
		if (givenDict == null)
		{
			return false;
		}
		for (int i = 0; i < 6; i++)
		{
			if (!givenDict.ContainsKey("Skill" + i))
			{
				return false;
			}
		}
		if (!givenDict.ContainsKey("Interact") || !givenDict.ContainsKey("LeftTrigger") || !givenDict.ContainsKey("Map"))
		{
			return false;
		}
		return true;
	}

