	public static Sprite GetInputSprite(ChaosInputDevice.InputScheme inputScheme, string inputName = "Confirm")
	{
		if (inputName == string.Empty)
		{
			inputName = "Confirm";
		}
		string text = "KB";
		if (inputScheme != ChaosInputDevice.InputScheme.Keyboard)
		{
			text = ((!psGamepad) ? "XBox" : "PS");
			if (switchGamepad)
			{
				text = "Switch";
			}
		}
		return (!InputButtonSprites.ContainsKey(inputName + text)) ? null : InputButtonSprites[inputName + text];
	}

	public void Awake()
	{
		if (instance != null && instance != this)
		{
			Object.Destroy(gameObject);
			return;
		}
		instance = this;
		Object.DontDestroyOnLoad(gameObject);
		money = transform.Find("MoneyCount").gameObject;
		goldText = transform.Find("MoneyCount/GoldText").GetComponent<Text>();
		goldIcon = transform.Find("MoneyCount/GoldIcon").GetComponent<Image>();
		platinumText = transform.Find("MoneyCount/PlatinumText").GetComponent<Text>();
		pauseMenu = transform.Find("PauseMenu").GetComponent<PauseMenuUI>();
		pauseMenu.gameObject.SetActive(value: false);
		notice = transform.Find("NoticeBox/Text").GetComponent<Text>();
		notice.gameObject.SetActive(value: false);
		TextManager.AddUIRef(string.Empty, notice);
		P1Hud = new LowerHUD(transform.Find("P1LowerHUD"));
		P2Hud = new LowerHUD(transform.Find("P2LowerHUD"));
		dialogManager = transform.Find("DialogBox").GetComponent<DialogManager>();
		deathSummary = transform.Find("DeathSummary").GetComponent<DeathSummaryUI>();
	}

	private void Update()
	{
		if (Level.isBossRushMode && GameController.inGameScene && ChaosStopwatch.Check(noticeStopwatchID))
		{
			BroadcastNoticeMessage(Globals.TimeFlatToString((int)GameController.totalTime), 0.5f);
		}
		else
		{
			if (noticeText != string.Empty && ChaosStopwatch.Check(noticeStopwatchID))
			{
				noticeText = string.Empty;
			}
			SetNoticeText(noticeText);
		}
		P1Hud.Update();
		P2Hud.Update();
		if (moneyStatus && Player.platWallet != null && Player.goldWallet != null)
		{
			if (!money.activeSelf)
			{
				money.SetActive(value: true);
			}
			platinumText.text = Player.platWallet.balance.ToString();
			goldText.text = Player.goldWallet.balance.ToString();
		}
		else if (money.activeSelf)
		{
			money.SetActive(value: false);
		}
	}

	public static void SetMoneyStatus(bool givenStatus = true)
	{
		moneyStatus = givenStatus;
	}

	public static void ToggleLowerHud(bool givenStatus = true, int givenID = -1)
	{
		switch (givenID)
		{
		case -1:
			P1Hud.SetVisibleStatus(givenStatus);
			P2Hud.SetVisibleStatus(givenStatus);
			break;
		case 0:
			P1Hud.SetVisibleStatus(givenStatus);
			break;
		default:
			P2Hud.SetVisibleStatus(givenStatus);
			break;
		}
	}

	public static void UpdateWalletCount()
	{
		goldText.text = Player.goldWallet.balance.ToString();
		platinumText.text = Player.platWallet.balance.ToString();
	}

	public static void BroadcastNoticeMessage(string givenMsg, float givenTime = 3f)
	{
		noticeText = givenMsg;
		noticeStopwatchID = ChaosStopwatch.Begin(givenTime);
	}

	private void SetNoticeText(string msg = "")
	{
		if (msg == string.Empty)
		{
			notice.gameObject.SetActive(value: false);
			return;
		}
		notice.text = msg;
		notice.gameObject.SetActive(value: true);
	}

	public static LowerHUD ClaimLowerHUD(Player newPlayer)
	{
		if (newPlayer.playerID == 0)
		{
			P1Hud.Claim(newPlayer);
			return P1Hud;
		}
		if (newPlayer.playerID == 1)
		{
			P2Hud.Claim(newPlayer);
			return P2Hud;
		}
		return null;
	}

	public static void TogglePause()
	{
		if (pauseMenu.gameObject.activeSelf)
		{
			if (pauseMenu.hasFocus)
			{
				pauseMenu.TogglePause();
				pauseMenu.gameObject.SetActive(value: false);
			}
		}
		else
		{
			pauseMenu.gameObject.SetActive(value: true);
