using System.Collections.Generic;
using UnityEngine;

public static class IconManager
{
	public static readonly string unavailableSkillName = "RandomSkill";

	public static readonly string unavailableItemName = "UnknownItem";

	public static readonly string unavailablePaintingName = "Unknown";

	private static Dictionary<string, Sprite> skillIcons;

	private static Dictionary<string, Sprite> itemIcons;

	private static Dictionary<string, Sprite> paintingSprites;

	private static Dictionary<string, Sprite> cooldownUISprites;

	private static Dictionary<string, Sprite> relicUISprites;

	private static Dictionary<string, Sprite> wizardSprites;

	private static List<Sprite> wizardSpriteList;

	private static List<Sprite> tsbgSpriteList;

	private static Dictionary<string, Sprite> SkillIcons => skillIcons ?? (skillIcons = LoadSprites("Assets/Sprites/UI/Skills.png"));

	private static Dictionary<string, Sprite> ItemIcons => itemIcons ?? (itemIcons = LoadSprites("Assets/Sprites/Items/ItemIcons.png"));

	private static Dictionary<string, Sprite> PaintingSprites => paintingSprites ?? (paintingSprites = LoadSprites("Assets/Sprites/Environment/Paintings.png"));

	private static Dictionary<string, Sprite> CooldownUISprites => cooldownUISprites ?? (cooldownUISprites = LoadSprites("Assets/Sprites/UI/CooldownUI.png"));

	private static Dictionary<string, Sprite> RelicUISprites => relicUISprites ?? (relicUISprites = LoadSprites("Assets/Sprites/UI/RelicUI.png"));

	private static Dictionary<string, Sprite> WizardSprites
	{
		get
		{
			if (wizardSprites == null)
			{
				wizardSprites = new Dictionary<string, Sprite>();
				Sprite[] withSubAssets = ChaosBundle.GetWithSubAssets<Sprite>("Assets/Sprites/Player/NewWizard.png");
				for (int i = 0; i < withSubAssets.Length; i++)
				{
					if (!withSubAssets[i].name.Contains("Hood"))
					{
						wizardSprites[withSubAssets[i].name] = withSubAssets[i];
					}
				}
			}
			return wizardSprites;
		}
	}

	private static List<Sprite> WizardSpriteList
	{
		get
		{
			if (wizardSpriteList == null)
			{
				wizardSpriteList = new List<Sprite>();
				Sprite[] withSubAssets = ChaosBundle.GetWithSubAssets<Sprite>("Assets/Sprites/Player/NewWizard.png");
				for (int i = 0; i < withSubAssets.Length; i++)
				{
					if (!withSubAssets[i].name.Contains("Hood"))
					{
						wizardSpriteList.Add(withSubAssets[i]);
					}
				}
			}
			return wizardSpriteList;
		}
	}

	private static List<Sprite> TSBGSpriteList
	{
		get
		{
			if (tsbgSpriteList == null)
			{
				tsbgSpriteList = new List<Sprite>();
				for (int i = 0; i < TitleScreen.bgCount; i++)
				{
					tsbgSpriteList.Add(ChaosBundle.Get<Sprite>("Assets/Sprites/UI/TitleScreen/Background" + i + ".png"));
				}
			}
			return tsbgSpriteList;
		}
	}

	private static Dictionary<string, Sprite> LoadSprites(string resourcePath)
	{
		Dictionary<string, Sprite> dictionary = new Dictionary<string, Sprite>();
		Sprite[] withSubAssets = ChaosBundle.GetWithSubAssets<Sprite>(resourcePath);
		int num = withSubAssets.Length;
		for (int i = 0; i < num; i++)
		{
			dictionary[withSubAssets[i].name] = withSubAssets[i];
		}
		return dictionary;
	}

