	{
		return skillType switch
		{
			2 => (!filled) ? CooldownUISprites["GoldPanelUnfilled"] : CooldownUISprites["GoldPanelFilled"], 
			1 => (!filled) ? CooldownUISprites["TealPanelUnfilled"] : CooldownUISprites["TealPanelFilled"], 
