using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class PauseMenuUI : MonoBehaviour
{
	public bool hasFocus;

	public bool paused;

	private int currentIndex;

	private int previousIndex;

	private int optionsCount;

	private bool inputReceived;

	private bool optionClicked;

	private int inputVal;

	private List<Text> pauseMenuOptions = new List<Text>();

	private bool refsFound;

	private OptionsMenu optionsMenu;

	private bool confirmationRequested;

	private bool confirmationStatus;

	private Text titleScreenText;

	private void GetOptionRefs()
	{
		Text component = transform.Find("Resume/Text").GetComponent<Text>();
		Text component2 = transform.Find("Options/Text").GetComponent<Text>();
		Text component3 = transform.Find("Quit/Text").GetComponent<Text>();
		titleScreenText = transform.Find("TitleScreen/Text").GetComponent<Text>();
		TextManager.AddUIRef("pauseMenu-title", transform.Find("Title").GetComponent<Text>());
		TextManager.AddUIRef("pauseMenu-resume", component);
		TextManager.AddUIRef("pauseMenu-titleScreen", titleScreenText);
		TextManager.AddUIRef("pauseMenu-options", component2);
		TextManager.AddUIRef("pauseMenu-quit", component3);
		pauseMenuOptions.Add(component);
		pauseMenuOptions.Add(titleScreenText);
		pauseMenuOptions.Add(component2);
		pauseMenuOptions.Add(component3);
		optionsMenu = GameController.optionsMenu;
		refsFound = true;
	}

	public void TogglePause()
	{
		if (optionsMenu != null)
		{
			optionsMenu.releaseControlToParent = true;
			optionsMenu.gameObject.SetActive(value: false);
		}
		ConfirmHandlerUI.ForceQuitConfirmation();
	}

	private void Update()
	{
		if (!paused || !HandleConfirmationProgress())
		{
			return;
		}
		HandleConfirmInput();
		if (optionClicked)
		{
			switch (currentIndex)
			{
			case 0:
				TogglePause();
				gameObject.SetActive(value: false);
				break;
			case 1:
				if (!HandleConfirmationRequest())
				{
					return;
				}
				TogglePause();
				gameObject.SetActive(value: false);
				if (Globals.IsTutorial)
				{
					GameController.LoadLevel("PlayerRoom");
				}
				else
				{
					GameController.LoadLevel("TitleScreen");
				}
				break;
			case 2:
				if (!optionsMenu.gameObject.activeSelf)
				{
					optionsMenu.gameObject.SetActive(value: true);
					optionsMenu.releaseControlToParent = false;
					hasFocus = false;
					SoundManager.PlayConfirmAudio();
					break;
				}
				if (optionsMenu.releaseControlToParent)
				{
					SoundManager.BGMPaused = true;
					optionClicked = false;
					optionsMenu.gameObject.SetActive(value: false);
					hasFocus = true;
					if (GameController.resetGameDataQueued)
					{
						TogglePause();
						gameObject.SetActive(value: false);
						GameController.LoadLevel("InitialLoad");
					}
					break;
				}
				return;
			case 3:
				if (!HandleConfirmationRequest())
				{
					return;
				}
				GameController.Quit();
				break;
			}
		}
		HandleNavigation();
	}

	private void HandleConfirmInput()
	{
		if (hasFocus && (InputController.GetAnyDeviceButtonDown("Confirm") != null || Input.GetKeyDown(KeyCode.Space)))
		{
			optionClicked = true;
		}
	}

	private void HandleNavigation()
	{
		if (!hasFocus)
		{
			return;
		}
		inputVal = (InputController.GetAnyDeviceDirection(InputDirection.Down) ? 1 : (InputController.GetAnyDeviceDirection(InputDirection.Up) ? (-1) : 0));
		if (inputVal == 0)
		{
			inputReceived = false;
		}
		else if (!inputReceived)
		{
			inputReceived = true;
			previousIndex = currentIndex;
			currentIndex += inputVal;
			if (currentIndex < 0)
			{
				currentIndex = optionsCount - 1;
			}
			else if (currentIndex >= optionsCount)
			{
				currentIndex = 0;
			}
			SelectOption(currentIndex);
		}
	}

	public void SelectOption(int index)
	{
		if (hasFocus)
		{
			pauseMenuOptions[previousIndex].color = Globals.uiNotSelectedColor;
			previousIndex = index;
			currentIndex = index;
			pauseMenuOptions[index].color = Globals.uiSelectedColor;
			SoundManager.PlayAudio("MenuMove", 1f, ignoreTimeRestriction: true);
		}
	}

	public void OptionWasClicked()
	{
		if (hasFocus)
		{
			optionClicked = true;
		}
	}

	private bool HandleConfirmationRequest()
	{
		if (confirmationStatus)
		{
			return true;
		}
		ConfirmHandlerUI.RequestConfirmation();
		confirmationRequested = true;
		optionClicked = false;
		hasFocus = false;
		return false;
	}

	private bool HandleConfirmationProgress()
	{
		if (confirmationRequested)
		{
			if (ConfirmHandlerUI.RequestInProgress)
			{
				confirmationStatus = ConfirmHandlerUI.RequestConfirmation();
				return false;
			}
			confirmationRequested = false;
			optionClicked = confirmationStatus;
			hasFocus = true;
		}
		return true;
	}
}
using UnityEngine;
using UnityEngine.UI;

public class ConfirmHandlerUI : MonoBehaviour
{
	private static ConfirmHandlerUI instance;

	private static Canvas canvas;

	private static GameObject confirmWindow;

	private static Text titleText;

	private static Text cancelText;

	private static Text confirmText;

	private static bool readyStatus;

	private static bool optionSelected;

	private static bool inputReset;

	private static bool confirmationStatus;

	private static bool confirmationRequested;

	public static bool RequestInProgress => confirmationRequested;

	private void Awake()
	{
		if (instance != null && instance != this)
		{
			Object.Destroy(gameObject);
			return;
		}
		instance = this;
		Object.DontDestroyOnLoad(gameObject);
		canvas = GetComponent<Canvas>();
		confirmWindow = transform.Find("ConfirmWindow").gameObject;
		titleText = confirmWindow.transform.Find("Title/Text").GetComponent<Text>();
		cancelText = confirmWindow.transform.Find("Options/Cancel/Text").GetComponent<Text>();
		confirmText = confirmWindow.transform.Find("Options/Confirm/Text").GetComponent<Text>();
		TextManager.AddUIRef("confirmWindow-title", titleText);
		TextManager.AddUIRef("confirmWindow-cancel", cancelText);
		TextManager.AddUIRef("confirmWindow-confirm", confirmText);
		readyStatus = false;
		cancelText.color = Globals.uiSelectedColor;
		confirmText.color = Globals.uiNotSelectedColor;
		confirmWindow.SetActive(value: false);
		canvas.enabled = false;
	}

	public static void ForceQuitConfirmation()
	{
		readyStatus = true;
		SetReadyStatus(givenStatus: false);
	}

	public static bool RequestConfirmation(int confirmCount = 0)
	{
		if (!readyStatus)
		{
			switch (confirmCount)
			{
			case 0:
				titleText.text = TextManager.GetUIText("confirmWindow-title");
				break;
			case 1:
				titleText.text = TextManager.GetUIText("confirmWindow-titleSecond");
				break;
			case 2:
				titleText.text = TextManager.GetUIText("confirmWindow-titleThird");
				break;
			case 3:
				titleText.text = TextManager.GetUIText("confirmWindow-titleRestart");
				break;
			}
			SetConfirmStatus(givenStatus: false);
			SetReadyStatus(givenStatus: true);
			SoundManager.PlayConfirmAudio();
			return false;
		}
		if (!inputReset)
		{
			inputReset = true;
			return false;
		}
		HandleSelection();
		if (optionSelected)
		{
			SetReadyStatus(givenStatus: false);
			if (confirmationStatus)
			{
				SoundManager.PlayConfirmAudio();
			}
			return confirmationStatus;
		}
		return false;
	}

	private static void SetReadyStatus(bool givenStatus)
	{
		if (readyStatus != givenStatus)
		{
			readyStatus = givenStatus;
			if (confirmWindow != null)
			{
				confirmWindow.SetActive(readyStatus);
				canvas.enabled = readyStatus;
			}
			confirmationRequested = readyStatus;
			optionSelected = !readyStatus;
			inputReset = !readyStatus;
		}
	}

	private static void HandleSelection()
	{
		if (InputController.GetAnyDeviceDirection(InputDirection.Down))
		{
			SetConfirmStatus(givenStatus: true);
			SoundManager.PlayAudio("MenuMove", 1f, ignoreTimeRestriction: true);
		}
		else if (InputController.GetAnyDeviceDirection(InputDirection.Up))
		{
			SetConfirmStatus(givenStatus: false);
			SoundManager.PlayAudio("MenuMove", 1f, ignoreTimeRestriction: true);
		}
		if (InputController.GetAnyDeviceButtonDown("Confirm") != null)
		{
			ConfirmSelected();
		}
		else if (InputController.GetAnyDeviceButtonUp("Cancel") != null)
		{
			CancelSelected();
		}
	}

	private static void SetConfirmStatus(bool givenStatus)
	{
		confirmationStatus = givenStatus;
		SetColors(confirmationStatus);
	}

	private static void SetColors(bool givenStatus)
	{
		if (givenStatus)
		{
			cancelText.color = Globals.uiNotSelectedColor;
			confirmText.color = Globals.uiSelectedColor;
		}
		else
		{
			cancelText.color = Globals.uiSelectedColor;
			confirmText.color = Globals.uiNotSelectedColor;
		}
	}

	private static void ConfirmSelected()
	{
		optionSelected = true;
	}

	private static void CancelSelected()
	{
		optionSelected = true;
		SetConfirmStatus(givenStatus: false);
	}

	public void OptionClicked()
	{
		ConfirmSelected();
	}

	public void OptionHovered(bool givenStatus)
	{
		SetConfirmStatus(givenStatus);
	}
}

using System;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

public class EnemyCounterBar : MonoBehaviour
{
	private MiniBossAltar miniBossAltar;

	private MiniBossActivationCircle miniBossActivationCircle;

	public static readonly int maxSkulls = 3;

	private bool hidden;

	private Animator[] skullAnimArray;

	private Image[] skullImageArray;

	private bool[] skullEnabledArray;

	private float[] skullDisableThreshold = new float[3] { 0.3f, 0.6f, 0.9f };

	private int currentDisableIndex;

	private bool skullAltered;

	private int lastActiveSkull = -1;

	private float thresholdMin;

	private bool skipFrame;

	private void Awake()
	{
		skullAnimArray = new Animator[maxSkulls];
		skullEnabledArray = new bool[maxSkulls];
		skullImageArray = new Image[maxSkulls];
		for (int i = 0; i < maxSkulls; i++)
		{
			skullAnimArray[i] = transform.Find("EnemyCounterBarSkull" + i).GetComponent<Animator>();
			skullEnabledArray[i] = true;
			skullImageArray[i] = skullAnimArray[i].transform.Find("Skull").GetComponent<Image>();
			skullImageArray[i].fillAmount = 1f;
		}
		SceneManager.sceneLoaded += OnSceneLoaded;
		LevelGenerator.levelGeneratedEventHandlers = (LevelGenerator.LevelGeneratedEventHandler)Delegate.Combine(LevelGenerator.levelGeneratedEventHandlers, new LevelGenerator.LevelGeneratedEventHandler(OnLevelGenerated));
	}

	private void Update()
	{
		if (hidden)
		{
			return;
		}
		if (skipFrame)
		{
			skipFrame = false;
			return;
		}
		skullAltered = false;
		lastActiveSkull = -1;
		for (int i = 0; i < maxSkulls; i++)
		{
			if (skullEnabledArray[i])
			{
				lastActiveSkull = i;
			}
		}
		if (currentDisableIndex < skullEnabledArray.Length && Level.EnemyDefeatedPercentage >= skullDisableThreshold[currentDisableIndex])
		{
			skullAnimArray[lastActiveSkull].Play("Disable", -1, 0f);
			skullEnabledArray[lastActiveSkull] = false;
			skullAltered = true;
			skullImageArray[lastActiveSkull].fillAmount = 1f;
			thresholdMin = skullDisableThreshold[currentDisableIndex];
			currentDisableIndex++;
			lastActiveSkull = -1;
		}
		if (lastActiveSkull != -1)
		{
			if (thresholdMin == 0f)
			{
				skullImageArray[lastActiveSkull].fillAmount = 1f - Level.EnemyDefeatedPercentage / skullDisableThreshold[currentDisableIndex];
			}
			else
			{
				skullImageArray[lastActiveSkull].fillAmount = 1f - Mathf.InverseLerp(thresholdMin, skullDisableThreshold[currentDisableIndex], Level.EnemyDefeatedPercentage);
			}
		}
		if (skullAltered)
		{
			bool[] array = (bool[])skullEnabledArray.Clone();
			Array.Reverse(array);
			if (MiniBossAltar.currentMiniBossAltar != null)
			{
				MiniBossAltar.currentMiniBossAltar.SetSkullStates(array);
			}
			if (MiniBossActivationCircle.currentMiniBossActivationCircle != null)
			{
				MiniBossActivationCircle.currentMiniBossActivationCircle.SetSkullStates(array);
			}
		}
	}

	private void Hide()
	{
		if (!hidden)
		{
			hidden = true;
			gameObject.SetActive(value: false);
		}
	}

	private void Show()
	{
		if (hidden)
		{
			hidden = false;
			gameObject.SetActive(value: true);
		}
	}

	private void Reset()
	{
		for (int i = 0; i < maxSkulls; i++)
		{
			skullEnabledArray[i] = true;
			if (!hidden)
			{
				skullAnimArray[i].Play("Enabled", -1, 0f);
			}
			skullImageArray[i].fillAmount = 1f;
		}
		thresholdMin = 0f;
		currentDisableIndex = 0;
	}

	private void OnSceneLoaded(Scene scene, LoadSceneMode loadSceneMode)
	{
		if (!NextLevelLoader.InTierScene(scene.name))
		{
			Reset();
			Hide();
		}
		LevelGenerator.levelGeneratedEventHandlers = (LevelGenerator.LevelGeneratedEventHandler)Delegate.Remove(LevelGenerator.levelGeneratedEventHandlers, new LevelGenerator.LevelGeneratedEventHandler(OnLevelGenerated));
		LevelGenerator.levelGeneratedEventHandlers = (LevelGenerator.LevelGeneratedEventHandler)Delegate.Combine(LevelGenerator.levelGeneratedEventHandlers, new LevelGenerator.LevelGeneratedEventHandler(OnLevelGenerated));
	}

	private void OnLevelGenerated()
	{
		Reset();
		Show();
		skipFrame = true;
	}

	private void OnDestroy()
	{
		SceneManager.sceneLoaded -= OnSceneLoaded;
		LevelGenerator.levelGeneratedEventHandlers = (LevelGenerator.LevelGeneratedEventHandler)Delegate.Remove(LevelGenerator.levelGeneratedEventHandlers, new LevelGenerator.LevelGeneratedEventHandler(OnLevelGenerated));
	}
}
