		HPBarHurtFill.fillAmount = 0f;
		shieldBarFill.fillAmount = 0f;
		fillingIn = false;
		fadeInTime = 0.5f;
		fillInTime = 1f;
		fillInTimer = fillInTime;
	}

	public void Claim(Enemy enemy)
	{
		Reset();
		this.enemy = enemy;
		gameObject.SetActive(value: true);
	}

	public void FadeIn()
	{
		if (!gameObject.activeSelf)
		{
			gameObject.SetActive(value: true);
		}
		Graphic[] allGraphics = AllGraphics;
		foreach (Graphic graphic in allGraphics)
		{
			graphic.canvasRenderer.SetAlpha(0.01f);
			graphic.enabled = true;
			graphic.CrossFadeAlpha(1f, 0.25f, ignoreTimeScale: false);
		}
		fillingIn = true;
	}

	private void HandleFillIn()
	{
		if (fillingIn)
		{
			if (fillInTimer <= 0f)
			{
				fillingIn = false;
				return;
			}
			fillInTimer -= Time.deltaTime;
			fillAmount = 1f - fillInTimer / fillInTime;
			HPBarFill.fillAmount = fillAmount;
			HPBarHurtFill.fillAmount = fillAmount;
		}
	}

	private void HandleHealth()
	{
		currentHealth = enemy.health.healthStat.CurrentValue;
		if (currentHealth < prevHealth)
		{
			if (ChaosStopwatch.Check(healthDelayStopwatchID))
			{
				changingHealth = prevHealth;
			}
			healthDelayStopwatchID = ChaosStopwatch.Begin(healthUpdateDelayTime);
		}
		changingHealth -= ((!(changingHealth > currentHealth)) ? 0f : (Time.deltaTime * hurtFillSpeed));
		prevHealth = currentHealth;
		HPBarFill.fillAmount = enemy.health.HealthPercentage;
		HPBarHurtFill.fillAmount = changingHealth / enemy.health.healthStat.ModifiedValue;
	}

	private void HandleShield()
	{
		shieldBarFill.fillAmount = enemy.health.ShieldPercentage;
	}

	public void SetName(string givenName)
	{
		enemyNameText.text = givenName;
	}
}
using UnityEngine;

public class EnemyTargetLine : TargetLine
{
	public int skillTimerID = -1;

	public float flashThreshold = 0.85f;

	public float solidRedThreshold = 0.9f;

	public float flashInterval = 0.018f;

	public float maxOpacity = 0.6f;

	private ChaosQuickStopwatch flashTimer;

	public Color curColor;

	public Color lineColor0;

	public Color lineColor1;

	private bool setColor0 = true;

	internal new static GameObject _prefab;

	public new static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/UI/EnemyTargetLine.prefab");
			}
			return _prefab;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		lineColor0 = new Color(0.8f, 0f, 0f, 0f);
		lineColor1 = new Color(1f, 1f, 1f, 0.75f);
		curColor = lineColor0;
	}

	private void Start()
	{
		line.SetColors(curColor, curColor);
	}

	private void Update()
	{
		if (skillTimerID == -1)
		{
			return;
		}
		float timePercentage = ChaosStopwatch.GetTimePercentage(skillTimerID);
		if (timePercentage >= 0.9f)
		{
			curColor = lineColor0;
			curColor.a = 1f;
		}
		else if (timePercentage >= 0.8f)
		{
			if (flashTimer == null)
			{
				flashTimer = new ChaosQuickStopwatch(flashInterval);
				flashTimer.IsRunning = true;
				curColor.a = 1f;
			}
			else if (!flashTimer.IsRunning)
			{
				if (setColor0)
				{
					curColor = lineColor0;
					curColor.a = 1f;
					setColor0 = false;
				}
				else
				{
					setColor0 = true;
					curColor = lineColor1;
				}
				flashTimer = new ChaosQuickStopwatch(flashInterval);
				flashTimer.IsRunning = true;
			}
		}
		else
		{
			curColor.a = maxOpacity * timePercentage;
		}
		line.SetColors(curColor, curColor);
	}
}
using System.Collections.Generic;
using UnityEngine;

public class TargetLine : MonoBehaviour
{
	private Entity parentEntity;

	private Player playerScript;

	private ChaosInputDevice playerInput;

	[HideInInspector]
	public SpriteRenderer sprite;

	public bool showDotSprite = true;

	[HideInInspector]
	public LineRenderer line;

	public bool collisionOccurred;

	[HideInInspector]
	public Transform transPosOverride;

	[HideInInspector]
	public bool skipSideCheck;

	[HideInInspector]
	public Vector2 transPos;

	[HideInInspector]
	public Vector2 aimVector;

	private Vector3 rotationalVector;

	private Vector2 aimVectorOffset;

	public bool setThickness = true;

	public float thickness = 0.25f;

	public float initialThickness;

	public float initialThicknessOverride;

	public float maxRange = 20f;

	public float minRange;

	public float range;

	public float rangeSafety;

	[HideInInspector]
	public int collisionLayerMask;

	private Vector2 yOnlyVec;

	public Vector2 startPositionOffset = new Vector2(0f, 0.5f);

	public float linecastOffset;

	public float targetIndicatorSpeed = 10f;

	private bool lineVisible;

	private float timeElapsed;

	private List<string> targetNames = new List<string>();

	private LayerMask enemyLayerMask;

	internal static GameObject _prefab;

	private float calcRange;

	public RaycastHit2D[] obsResults = new RaycastHit2D[20];

	private int collisionCount;

	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/UI/TargetLine.prefab");
			}
			return _prefab;
		}
	}

	protected virtual void Awake()
	{
		collisionLayerMask = ChaosCollisions.layerUpperWall;
		yOnlyVec = new Vector2(0f, 1f);
		aimVector = Vector2.one;
		aimVectorOffset = Vector2.one;
		if (transform.parent != null)
		{
			parentEntity = transform.parent.gameObject.GetComponent<Entity>();
			playerScript = transform.parent.gameObject.GetComponent<Player>();
		}
		sprite = transform.Find("Sprite").GetComponent<SpriteRenderer>();
		line = transform.Find("BGSprite").GetComponent<LineRenderer>();
		line.sortingLayerName = sprite.sortingLayerName;
		line.sortingOrder = -20000;
		enemyLayerMask = LayerMask.NameToLayer("Enemy");
	}

	private void Start()
	{
		if (initialThicknessOverride != 0f)
		{
			initialThickness = initialThicknessOverride;
		}
		else
		{
			initialThickness = thickness;
		}
	}

	private void LateUpdate()
	{
		if (lineVisible)
		{
			if (playerScript != null)
			{
				if (playerInput == null)
				{
					playerInput = playerScript.inputDevice;
				}
				aimVector = playerInput.GetAimVector();
			}
			if (aimVector == Vector2.zero && parentEntity != null)
			{
				aimVector = Entity.GetFacingDirectionVector(parentEntity.facingDirection);
			}
			if (transPosOverride != null)
			{
				transPos = transPosOverride.position;
			}
			else
			{
				transPos = transform.position;
			}
			range = maxRange;
			range = GetUnobstructedRange(transPos, transPos + aimVector * range, range, collisionLayerMask);
			if (!skipSideCheck)
			{
				aimVectorOffset.x = aimVector.y;
				aimVectorOffset.y = aimVector.x;
				aimVectorOffset *= initialThickness * 0.51f;
				aimVectorOffset.x *= -1f;
				range = GetUnobstructedRange(transPos + aimVectorOffset, transPos + aimVectorOffset + aimVector * range, range, collisionLayerMask);
				aimVectorOffset *= -1f;
				range = GetUnobstructedRange(transPos + aimVectorOffset, transPos + aimVectorOffset + aimVector * range, range, collisionLayerMask);
			}
			if (range < minRange)
			{
				range = minRange;
			}
			yOnlyVec.y = range;
			line.SetPosition(1, yOnlyVec);
			if (setThickness)
			{
				float num = Mathf.Clamp(thickness, 0.0625f, 9999f);
				line.SetWidth(num, num);
			}
			rotationalVector = aimVector;
			if (parentEntity != null && !parentEntity.isFacingRight)
			{
				rotationalVector.x *= -1f;
			}
			transform.localEulerAngles = Globals.GetRotationVector(rotationalVector);
			line.SetPosition(0, startPositionOffset);
			if (showDotSprite && range > 0f)
			{
				timeElapsed += Time.deltaTime * targetIndicatorSpeed;
				timeElapsed %= range;
				sprite.transform.position = transPos + aimVector * timeElapsed;
			}
			else
			{
				timeElapsed = 0f;
			}
		}
		sprite.enabled = lineVisible && showDotSprite;
		line.enabled = lineVisible;
	}

	public void IsVisible(bool status)
	{
		if (!lineVisible && status)
		{
			timeElapsed = 0f;
		}
		lineVisible = status;
	}

	public void SetCollisionLayerMask(string sortingLayerName = "", bool stopOnDestructible = true, bool stopOnEnemy = true, List<string> targets = null)
	{
		if (sortingLayerName != string.Empty)
		{
			line.sortingLayerName = sortingLayerName;
		}
		collisionLayerMask = ChaosCollisions.layerUpperWallAndObst;
		if (stopOnDestructible)
		{
			collisionLayerMask |= 1 << LayerMask.NameToLayer("Destructible");
		}
		if (stopOnEnemy && targets != null)
		{
			collisionLayerMask |= 1 << LayerMask.NameToLayer("Enemy");
			targetNames = targets;
		}
	}

	private float GetUnobstructedRange(Vector2 start, Vector2 end, float maxRange, int collisionLayerMask)
	{
		calcRange = maxRange;
		if (linecastOffset != 0f)
		{
			start += (start - end).normalized * linecastOffset;
		}
		collisionCount = Physics2D.LinecastNonAlloc(start, end, obsResults, collisionLayerMask);
		if (targetNames.Count > 0)
		{
			for (int i = 0; i < collisionCount; i++)
			{
				if (targetNames.Contains(obsResults[i].collider.name) && !IsPassThrough(obsResults[i].collider))
				{
					calcRange = Vector2.Distance(obsResults[i].point, start);
					collisionOccurred = true;
					break;
				}
			}
		}
		else if (collisionCount > 0)
		{
			for (int j = 0; j < collisionCount; j++)
			{
				if ((bool)obsResults[j] != (bool?)null && !(obsResults[j].collider == null) && !IsPassThrough(obsResults[j].collider))
				{
					collisionOccurred = true;
					calcRange = Vector2.Distance(obsResults[j].point, start);
					break;
				}
			}
		}
		return Mathf.Clamp(calcRange + rangeSafety, minRange, maxRange);
	}

	private bool IsPassThrough(Collider2D other)
	{
		Health componentInParent = other.gameObject.GetComponentInParent<Health>();
		if (componentInParent == null)
		{
			return false;
		}
		if (componentInParent.passThroughAttack)
		{
			return true;
		}
		return false;
	}
}

