	public void SetPlayerPiece()
	{
		int num = GameController.tierCount * curMaxStagesPerTier + Mathf.Clamp(GameController.stageCount, 0, curMaxStagesPerTier);
		p1PieceCrown.enabled = false;
		p2PieceCrown.enabled = false;
		if (!GameController.coopOn)
		{
			p2PieceAnim.Play("Hidden", -1, 0f);
		}
		else
		{
			p2PieceAnim.Play("Idle", -1, 0f);
			if (num > 0 && !Level.isBossRushMode)
			{
				switch (GameController.levelSummary.player1Wins)
				{
				case 0:
					p1PieceCrown.enabled = true;
					p2PieceCrown.enabled = true;
					break;
				case 1:
					p1PieceCrown.enabled = true;
					p2PieceCrown.enabled = false;
					break;
				case -1:
					p1PieceCrown.enabled = false;
					p2PieceCrown.enabled = true;
					break;
				}
			}
		}
		pieceFinishedMoving = false;
		if (num == 0 && GameController.loopCount > 0)
		{
			p1Piece.position = stagesInOrder[curFinalStageIndex].position;
		}
		else
		{
			p1Piece.position = stagesInOrder[num].position;
		}
		if (GameController.coopOn)
		{
			p2Piece.position = p1Piece.position + (Vector3)coopPieceOffset[1];
			p2PieceAnim.Play("Idle");
		}
		p1PieceAnim.Play("Idle");
		for (int i = 0; i < curTotalStageCount - 1; i++)
		{
			if (i <= num - 1)
			{
				dimmersInOrder[i].color = disabledColor;
			}
			else
			{
				dimmersInOrder[i].color = defaultColor;
			}
		}
		startPos = p1Piece.position;
		endPos = stagesInOrder[num + 1].position;
		StartCoroutine(MovePlayerPiece(num));
	}

	private IEnumerator MovePlayerPiece(int stageIndex)
	{
		ChaosQuickStopwatch delayStopWatch = new ChaosQuickStopwatch(0.25f)
		{
			IsRunning = true
		};
		while (delayStopWatch.IsRunning)
		{
			yield return null;
		}
		if (stageIndex != 0 || GameController.loopCount == 0)
		{
			p1PieceAnim.Play("Bounce", -1, Random.value);
			if (GameController.coopOn)
			{
				p2PieceAnim.Play("Bounce", -1, Random.value);
			}
		}
		bool p1PieceLanded = false;
		ChaosQuickStopwatch pieceStopWatch = new ChaosQuickStopwatch(1.5f)
		{
			IsRunning = true
		};
		while (pieceStopWatch.IsRunning)
		{
			if (GameController.coopOn)
			{
				p2Piece.position = Vector2.Lerp(startPos + coopPieceOffset[1], endPos + coopPieceOffset[1], pieceStopWatch.TimePercentage);
				if (!p1PieceLanded)
				{
					if (pieceStopWatch.TimePercentage + 0.33f >= 1f)
					{
						p1PieceAnim.Play("Land", -1, 0f);
						p1PieceLanded = true;
					}
					else
					{
						p1Piece.position = Vector2.Lerp(startPos + coopPieceOffset[0], endPos + coopPieceOffset[0], pieceStopWatch.TimePercentage + 0.33f);
					}
				}
			}
			else
			{
				p1Piece.position = Vector2.Lerp(startPos, endPos, pieceStopWatch.TimePercentage);
			}
			dimmersInOrder[stageIndex].color = Color.Lerp(defaultColor, disabledColor, pieceStopWatch.TimePercentage);
			yield return null;
		}
		if (GameController.coopOn)
		{
			p1Piece.position = endPos + coopPieceOffset[0];
			p2Piece.position = endPos + coopPieceOffset[1];
			p2PieceAnim.Play("Land", -1, 0f);
		}
		else
		{
			p1PieceAnim.Play("Land", -1, 0f);
			p1Piece.position = endPos;
		}
		dimmersInOrder[stageIndex].color = disabledColor;
		yield return new WaitForSeconds(0.25f);
		pieceFinishedMoving = true;
	}

	private void SetModeVars()
	{
		if (Level.isBossRushMode)
		{
			curMaxStagesPerTier = 2;
			curStagePositions = bossRushStagePositions;
		}
		else
		{
			curMaxStagesPerTier = 3;
			curStagePositions = stagePositions;
		}
		curMaxTierCount = GameController.MaxTierCount;
	}

	public void InitializeTierOrders()
	{
		if (!initializationReady)
		{
			return;
		}
		SetModeVars();
		HideRegularStages();
		curTotalStageCount = curMaxTierCount * curMaxStagesPerTier + 2;
		curFinalStageIndex = curTotalStageCount - 1;
		stagesInOrder[curFinalStageIndex] = finalBossCircle;
		dimmersInOrder[curFinalStageIndex] = finalBossDimmer;
		string text = null;
		int num = 0;
		for (int i = 1; i < curTotalStageCount - 1; i += curMaxStagesPerTier)
		{
			num = (i - 1) / curMaxStagesPerTier;
			text = NextLevelLoader.GetCurrentTierScene(num);
			switch (text)
			{
			case "Ice":
				if (visible)
				{
					iceBossCircle.gameObject.SetActive(value: true);
				}
				iceBossCircle.anchoredPosition = curStagePositions[num];
				break;
			case "Earth":
				if (visible)
				{
					earthBossCircle.gameObject.SetActive(value: true);
				}
				earthBossCircle.anchoredPosition = curStagePositions[num];
				break;
			case "Fire":
				if (visible)
				{
					fireBossCircle.gameObject.SetActive(value: true);
				}
				fireBossCircle.anchoredPosition = curStagePositions[num];
				break;
			case "Air":
				if (visible)
				{
					airBossCircle.gameObject.SetActive(value: true);
				}
				airBossCircle.anchoredPosition = curStagePositions[num];
				break;
			case "Lightning":
				if (visible)
				{
					lightningBossCircle.gameObject.SetActive(value: true);
				}
				lightningBossCircle.anchoredPosition = curStagePositions[num];
				break;
			}
			int num2 = levelDimmers[text].Length - 1;
			int num3 = curMaxStagesPerTier - 2;
			while (num2 >= 0)
			{
				if (num3 >= 0)
				{
					dimmersInOrder[i + num3] = levelDimmers[text][num2];
					stagesInOrder[i + num3] = levelMarkers[text][num2];
					levelDimmers[text][num2].gameObject.SetActive(value: true);
					levelMarkers[text][num2].gameObject.SetActive(value: true);
				}
				else
				{
					levelDimmers[text][num2].gameObject.SetActive(value: false);
					levelMarkers[text][num2].gameObject.SetActive(value: false);
				}
				num2--;
				num3--;
			}
			dimmersInOrder[i + curMaxStagesPerTier - 1] = bossDimmers[text];
			stagesInOrder[i + curMaxStagesPerTier - 1] = bossCircles[text];
			bossesInOrder[num] = bossCircles[text];
		}
	}

	public void ToggleFade(bool fadeIn = true, float duration = 0.25f)
	{
		Graphic[] array = graphicComps;
		foreach (Graphic graphic in array)
		{
			graphic.CrossFadeAlpha((!fadeIn) ? 0f : 1f, duration, ignoreTimeScale: false);
		}
	}

	public void SetPlayerColors()
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (player.playerID == 0)
			{
				p1PieceImage.material.SetFloat("_PaletteIndex", player.outfitColorIndex);
			}
			else
			{
				p2PieceImage.material.SetFloat("_PaletteIndex", player.outfitColorIndex);
			}
		}
	}

	public void HideRegularStages()
	{
		iceBossCircle.gameObject.SetActive(value: false);
		fireBossCircle.gameObject.SetActive(value: false);
		airBossCircle.gameObject.SetActive(value: false);
		earthBossCircle.gameObject.SetActive(value: false);
		lightningBossCircle.gameObject.SetActive(value: false);
	}

	public void Enable()
	{
		visible = true;
		InitializeTierOrders();
		SetPlayerColors();
		ToggleFade();
		pieceFinishedMoving = false;
		SetPlayerPiece();
	}

	public void Disable()
	{
		visible = false;
		HideRegularStages();
		ToggleFade(fadeIn: false);
	}
}

