using Chaos.AnimatorExtensions;
using UnityEngine;
using UnityEngine.UI;

public class LoadingScreen : MonoBehaviour
{
	public delegate void LoadCompleteEvent();

	private static LoadingScreen instance;

	private GameObject bgOverlay;

	private Text progressText;

	private Text promptText;

	private Canvas canvas;

	private Animator anim;

	private Text loopCounterText;

	public LoadCompleteEvent loadCompleteEventHandlers;

	public GameProgressBoard gameProgressBoard;

	private bool fadeOutQueued;

	private bool promptFadeIn;

	private bool useFlickering;

	private float fadeTime = 0.5f;

	private int fadeStopwatchID = -1;

	private bool mouseWasVisible;

	[HideInInspector]
	public bool queueDisableOnly;

	private bool waitingForTPAnim;

	private bool tpFrameSkipped;

	private AnimEffect tpEffect;

	private string prevLevelName;

	private int prevStageCount;

	private int prevTierCount;

	private string levelName;

	public static bool loading;

	public static LoadingScreen Instance => instance;

	private void Awake()
	{
		if (instance != null && instance != this)
		{
			Object.Destroy(gameObject);
			return;
		}
		instance = this;
		bgOverlay = transform.Find("BlackOverlay").gameObject;
		progressText = transform.Find("BlackOverlay/Progress").GetComponent<Text>();
		promptText = transform.Find("BlackOverlay/Prompt").GetComponent<Text>();
		canvas = GetComponent<Canvas>();
		anim = GetComponent<Animator>();
		gameProgressBoard = transform.Find("GameProgress").GetComponent<GameProgressBoard>();
		loopCounterText = transform.Find("GameProgress/StartCircle/LoopCounter/Text").GetComponent<Text>();
		TextManager.AddUIRef(string.Empty, progressText);
		TextManager.AddUIRef(string.Empty, promptText);
		TextManager.AddUIRef(string.Empty, loopCounterText);
		Object.DontDestroyOnLoad(gameObject);
	}

	private void Start()
	{
		Disable();
	}

	private void Update()
	{
		if (loading && GameUI.pauseMenu.paused)
		{
			GameUI.TogglePause();
		}
		if (fadeOutQueued && gameProgressBoard.pieceFinishedMoving)
		{
			fadeOutQueued = false;
			FadeOut();
			return;
		}
		if (useFlickering && ChaosStopwatch.Check(fadeStopwatchID))
		{
			fadeStopwatchID = ChaosStopwatch.Begin(fadeTime);
			promptText.CrossFadeAlpha((!promptFadeIn) ? 0.6f : 1f, 0.25f, ignoreTimeScale: true);
			promptFadeIn = !promptFadeIn;
		}
		if (!waitingForTPAnim)
		{
			return;
		}
		if (!tpFrameSkipped)
		{
			tpFrameSkipped = true;
		}
		else if ((tpEffect == null || tpEffect.anim.AnimPlayed(0.25f) || !tpEffect.playing) && GameController.activePlayers.Length > 0)
		{
			AnnounceStage();
			waitingForTPAnim = false;
			StopLoading();
			tpFrameSkipped = false;
			tpEffect = null;
			GameController.PauseAllPlayers(state: false);
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				player.Show();
			}
		}
	}

	public void SetProgressText(string txt)
	{
		progressText.text = txt;
	}

	public void SetPromptText(string txt)
	{
		promptText.text = txt;
	}

	public void Enable(bool gameProgressMode = false)
	{
		canvas.enabled = true;

		canvas.enabled = true;
		waitingForTPAnim = false;
		tpFrameSkipped = false;
		bgOverlay.SetActive(value: true);
		anim.Play("Enabled", -1, 0f);
		if (gameProgressMode)
		{
			gameProgressBoard.Enable();
		}
		if (!GameController.mouseCursor.Hidden)
		{
			mouseWasVisible = true;
			GameController.mouseCursor.Hide();
		}
		else
		{
			mouseWasVisible = false;
		}
		prevLevelName = Application.loadedLevelName;
		prevStageCount = GameController.stageCount;
		prevTierCount = GameController.tierCount;
		loopCounterText.enabled = true;
		loopCounterText.text = ((GameController.loopCount <= 0) ? string.Empty : ("x" + (GameController.loopCount + 1)));
		loading = true;
	}

	public void StopLoading()
	{
		loading = false;
		if ((prevLevelName != levelName || prevStageCount != GameController.stageCount || prevTierCount != GameController.tierCount) && loadCompleteEventHandlers != null)
		{
			loadCompleteEventHandlers();
		}
	}

	public void FadeOut()
	{
		if (gameProgressBoard.visible && !gameProgressBoard.pieceFinishedMoving)
		{
			fadeOutQueued = true;
			return;
		}
		anim.Play("FadeOut", -1, 0f);
		gameProgressBoard.Disable();
		SetProgressText(string.Empty);
		loopCounterText.enabled = false;
		if (mouseWasVisible)
		{
			GameController.mouseCursor.Show();
			mouseWasVisible = false;
		}
	}

	public void Disable()
	{
		canvas.enabled = false;
		bgOverlay.SetActive(value: false);
		if (queueDisableOnly)
		{
			queueDisableOnly = false;
			StopLoading();
			return;
		}
		levelName = Application.loadedLevelName;
		if (levelName == "Credits" || levelName == "PlayerRoomTutorial")
		{
			StopLoading();
			return;
		}
		if (levelName == "PvPArena")
		{
			StopLoading();
			GameController.PauseAllPlayers(state: false);
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				player.Show();
			}
			return;
		}
		int num = -1;
		Player[] activePlayers2 = GameController.activePlayers;
		foreach (Player player2 in activePlayers2)
		{
			if (num == -1)
			{
				num = player2.playerID;
				tpEffect = PoolManager.GetPoolItem<AnimEffect>("TeleportEffect");
				tpEffect.Play(player2.transform.position, string.Empty);
			}
			else
			{
				player2.TeleportToPartner(num, showSpawnPortal: false, excludeOrigin: true);
			}
			waitingForTPAnim = true;
		}
		if (Application.loadedLevelName == "Tutorial" && GameController.activePlayers.Length == 0)
		{
			StopLoading();
			waitingForTPAnim = true;
		}
		if (!waitingForTPAnim)
		{
			StopLoading();
			AnnounceStage();
		}
	}

	private void AnnounceStage()
	{
		if (NextLevelLoader.InTierScene(string.Empty))
		{
			GameController.stageTitleUI.Announce(GameController.StageTitle, 0f, 60, null, null, showUnderline: true, 1f, 0f, numberMode: false, null, null, null, 0.2f);
			return;
		}
		levelName = Application.loadedLevelName;
		if (levelName == "Hub" || levelName == "Tutorial")
		{
			GameController.stageTitleUI.Announce(TextManager.GetUIText("stageTitle-" + levelName));
		}
	}
}

using System;
using System.Collections.Generic;
using Chaos.TransformExtensions;
using UnityEngine;
using UnityEngine.UI;

public class Minimap : MonoBehaviour
{
	public enum MinimapMode
	{
		STAGE_ARCHITECT,
		CRAFTED_ROOM,
		CRAFTED_ROOM_FINAL
	}

	private static Minimap instance;

	private Player player;

	private GameObject level;

	private Transform minimapTrans;

	public Camera minimapCamera;

	public static Rect minimapOriginalRect;

	public static float minimapSizePercentage;

	private TileGrid tileGrid;

	private int revealDistance = 4;

	public static float minimapZVal = -40f;

	private MinimapMode mode;

	private TileSet tileSet;

	public static int sectionCount;

	public static int revealedSectionCount;

	private Text revealPercentageText;

	private Text floorIndicatorText;

	private Transform enemyIndicatorTrans;

	private RectTransform enemySkullsTrans;

	private Vector2 enemySkullsAnchoredPos;

	public static Minimap Instance => instance;

	public static float RevealedVal => (sectionCount > 0) ? Mathf.Clamp01((float)revealedSectionCount / (float)sectionCount) : 0f;

	public static string RevealedPercentage => RevealedVal.ToString("P0");

	private void Awake()
	{
		if (instance != null && instance != this)
		{
			UnityEngine.Object.Destroy(gameObject);
			return;
		}
		instance = this;
		minimapCamera = GetComponent<Camera>();
		minimapOriginalRect = minimapCamera.rect;
		minimapSizePercentage = 1f;
		tileSet = TileSet.Factory("MinimapTileSet");
		revealPercentageText = transform.Find("TransparentBGCanvas/RevealPercentage").GetComponent<Text>();
		floorIndicatorText = transform.Find("TransparentBGCanvas/FloorIndicator").GetComponent<Text>();
		enemyIndicatorTrans = transform.Find("TransparentBGCanvas/EnemyIndicator");
		enemySkullsTrans = (RectTransform)transform.Find("TransparentBGCanvas/EnemyIndicator/Skulls");
		enemySkullsAnchoredPos = enemySkullsTrans.anchoredPosition;
		TextManager.AddUIRef("minimap-enemyIcons", enemyIndicatorTrans.GetComponent<Text>());
		TextManager.AddUIRef(string.Empty, floorIndicatorText);
		TextManager.AddUIRef(string.Empty, revealPercentageText);
		UnityEngine.Object.DontDestroyOnLoad(gameObject);
	}

	public void GenerateMinimapMeshes()
	{
		minimapTrans.DestroyChildren(destroyImmediate: true, string.Empty);
		sectionCount = 0;
		revealedSectionCount = 0;
		for (int i = 0; i < tileGrid.RowCount; i += revealDistance)
		{
			for (int j = 0; j < tileGrid.ColCount; j += revealDistance)
			{
				int num = i + revealDistance;
				int num2 = j + revealDistance;
				int num3 = 0;
				int num4 = 0;
				List<Vector3> list = new List<Vector3>();
				List<int> list2 = new List<int>();
				List<Vector2> list3 = new List<Vector2>();
				int num5 = 0;
				int num6 = i;
				while (num6 < num)
				{
					int num7 = j;
					while (num7 < num2)
					{
						if (num6 < tileGrid.RowCount && num7 < tileGrid.ColCount && tileGrid[num6, num7] != null)
						{
							Tile tile = tileGrid[num6, num7];
							if ((tile.terrain == Tile.TerrainType.Floor || tile.terrain == Tile.TerrainType.Wall || tile.terrain == Tile.TerrainType.Pit || tile.overlay != Tile.OverlayType.None) && (tile.terrain == Tile.TerrainType.Pit || AdjTileTest.FloorNorth.Test(tileGrid, num6, num7) || AdjTileTest.FloorSouth.Test(tileGrid, num6, num7) || AdjTileTest.FloorEast.Test(tileGrid, num6, num7) || AdjTileTest.FloorWest.Test(tileGrid, num6, num7)))
							{
								list.Add(new Vector3(num3 + 1, -num4, 0f));
								list.Add(new Vector3(num3 + 1, -num4 - 1, 0f));
								list.Add(new Vector3(num3, -num4, 0f));
								list.Add(new Vector3(num3, -num4 - 1, 0f));
								list2.Add(num5);
								list2.Add(num5 + 1);
								list2.Add(num5 + 2);
								list2.Add(num5 + 2);
								list2.Add(num5 + 1);
								list2.Add(num5 + 3);
								string tileLayerName = "Floor";
								if (tile.terrain == Tile.TerrainType.Pit)
								{
									tileLayerName = "Pit";
								}
								else if (tile.overlay != Tile.OverlayType.None)
								{
									tileLayerName = "Overlay";
								}
								else if (tile.terrain == Tile.TerrainType.Wall)
								{
									tileLayerName = "Wall";
								}
								Vector2 tilePositionInGrid = tileSet.GetTilePositionInGrid(tileGrid[num6, num7], tileLayerName, num6, num7, tileGrid);
								list3.AddRange(tileSet.GetUVFromTilePosition(tilePositionInGrid));
								num5 += revealDistance;
							}
						}
						num7++;
						num3++;
					}
					num3 = 0;
					num6++;
					num4++;
				}
				if (list.Count > 0)
				{
					GameObject gameObject = new GameObject();
					gameObject.transform.SetParent(minimapTrans);
					gameObject.name = "MinimapSection" + sectionCount;
					gameObject.layer = LayerMask.NameToLayer("Minimap");
					gameObject.tag = "Minimap";
					gameObject.transform.localPosition = new Vector3(j, -i, 0f);
					BoxCollider2D boxCollider2D = gameObject.AddComponent<BoxCollider2D>();
					boxCollider2D.size = new Vector2(revealDistance, revealDistance);
					boxCollider2D.offset = new Vector2((float)revealDistance / 2f, (0f - (float)revealDistance) / 2f);
					boxCollider2D.isTrigger = true;
					gameObject.AddComponent<MinimapSection>();
					MeshFilter meshFilter = gameObject.AddComponent<MeshFilter>();
					Mesh mesh = new Mesh();
					mesh.vertices = list.ToArray();
					mesh.triangles = list2.ToArray();
					mesh.normals = InitMeshNormals(list.Count);
					mesh.uv = list3.ToArray();
					mesh.colors = InitMeshColors(list.Count, new Color(1f, 1f, 1f, 0.65f));
					meshFilter.sharedMesh = mesh;
					MeshRenderer meshRenderer = gameObject.AddComponent<MeshRenderer>();
					meshRenderer.sharedMaterial = tileSet.material;
					meshRenderer.sortingLayerName = "Default";
					meshRenderer.enabled = false;
					sectionCount++;
				}
			}
		}
	}

	public Vector3[] InitMeshNormals(int vertCount)
	{
		Vector3[] array = new Vector3[vertCount];
		for (int i = 0; i < array.Length; i++)
		{
			ref Vector3 reference = ref array[i];
			reference = Vector3.back;
		}
		return array;
	}

	public Color[] InitMeshColors(int vertCount, Color newColor)
	{
		Color[] array = new Color[vertCount];
		for (int i = 0; i < array.Length; i++)
		{
			array[i] = newColor;
		}
		return array;
	}

	public void InitStageVars(TileGrid newTileGrid = null)
	{
		level = Level.levelContainer.gameObject;
		tileGrid = newTileGrid;
		if (newTileGrid == null)
		{
			tileGrid = Level.tileGrid;
		}
		if (level == null)
		{
			return;
		}
		Transform transform = level.transform.Find("Meshes");
		if (transform == null)
		{
			Debug.Log("Minimap: Unable to find mesh container. If custom scene, please reload tileGrid to generate proper mesh containers");
			return;
		}
		minimapTrans = level.transform.Find("Meshes/Minimap");
		if (minimapTrans == null)
		{
			GameObject gameObject = new GameObject();
			minimapTrans = gameObject.transform;
			minimapTrans.SetParent(transform);
			if (mode == MinimapMode.CRAFTED_ROOM_FINAL)
			{
				minimapTrans.localPosition = new Vector3(8f, -(8 + WallGenerator.wallHeight), minimapZVal);
			}
			else if (mode == MinimapMode.CRAFTED_ROOM)
			{
				minimapTrans.localPosition = new Vector3(0f, 0f, minimapZVal);
			}
			else
			{
				minimapTrans.localPosition = new Vector3(minimapTrans.localPosition.x, minimapTrans.localPosition.y, minimapZVal);
			}
			gameObject.name = "Minimap";
		}
		GenerateMinimapMeshes();
	}

	private void Start()
	{
		LevelGenerator.levelGeneratedEventHandlers = (LevelGenerator.LevelGeneratedEventHandler)Delegate.Combine(LevelGenerator.levelGeneratedEventHandlers, new LevelGenerator.LevelGeneratedEventHandler(OnLevelGeneratedEvent));
	}

	private void OnLevelWasLoaded(int level)
	{
		if (!NextLevelLoader.InTierScene(string.Empty))
		{
			floorIndicatorText.text = string.Empty;
			Disable();
		}
		else
		{
			floorIndicatorText.text = GameController.CurrentStageStr;
			Activate();
		}
	}

	public void OnLevelGeneratedEvent()
	{
		if (NextLevelLoader.InTierScene(string.Empty))
		{
			CompassIndicatorTrigger.Spawn(Compass.CompassIndicatorType.StartRoom, Level.startPosition, null, 2.75f);
		}
	}

	public void Disable()
	{
		minimapCamera.enabled = false;
	}

	public void Activate()
	{
		SetFontSize();
		minimapCamera.enabled = true;
	}

	public void SetFontSize()
	{
		enemySkullsTrans.anchoredPosition = enemySkullsAnchoredPos;
		floorIndicatorText.transform.localScale = Vector3.one;
		revealPercentageText.transform.localScale = Vector3.one;
		if (TextManager.currentLanguage == ChaosLang.Spanish)
		{
			floorIndicatorText.transform.localScale = new Vector3(1.1f, 1.1f, 1.1f);
			revealPercentageText.transform.localScale = new Vector3(1.1f, 1.1f, 1.1f);
			enemySkullsTrans.anchoredPosition = enemySkullsAnchoredPos + new Vector2(24f, 0f);
		}
		else if (TextManager.currentLanguage == ChaosLang.Korean)
		{
			floorIndicatorText.transform.localScale = new Vector3(0.9f, 0.9f, 1f);
			revealPercentageText.transform.localScale = new Vector3(0.9f, 0.9f, 1f);
			enemySkullsTrans.anchoredPosition = enemySkullsAnchoredPos + new Vector2(-72f, 0f);
		}
