public class MinimapSection : MonoBehaviour
{
	public delegate void MinimapRevealEvent(bool actual);

	private MeshRenderer meshRenderer;

	private BoxCollider2D minimapCol;

	private bool revealedByPlayer;

	public static MinimapRevealEvent minimapRevealEventHandlers;

	private static List<MinimapSection> _minimapSections;

	public static List<MinimapSection> MinimapSections
	{
		get
		{
			if (_minimapSections == null)
			{
				_minimapSections = new List<MinimapSection>();
			}
			return _minimapSections;
		}
	}

	private void Start()
	{
		meshRenderer = GetComponent<MeshRenderer>();
		minimapCol = GetComponent<BoxCollider2D>();
		MinimapSections.Add(this);
	}

	private void OnTriggerEnter2D(Collider2D col)
	{
		if (col.name == "AllyMinimapRevealer")
		{
			Reveal(collidedWithPlayer: true);
		}
	}

	public void Reveal(bool collidedWithPlayer = false)
	{
		if (meshRenderer != null && !meshRenderer.enabled)
		{
			meshRenderer.enabled = true;
			Minimap.revealedSectionCount++;
			if (minimapRevealEventHandlers != null)
			{
				minimapRevealEventHandlers(collidedWithPlayer);
			}
		}
		if (!revealedByPlayer && collidedWithPlayer)
		{
			revealedByPlayer = collidedWithPlayer;
			minimapCol.enabled = false;
		}
		if (!collidedWithPlayer && !revealedByPlayer)
		{
			meshRenderer.material.color = new Color(0.5f, 0.55f, 0.8f);
		}
		else
		{
			meshRenderer.material.color = Color.white;
		}
	}

	public void Hide(bool excludePlayerReveals = false)
	{
		if ((!excludePlayerReveals || !revealedByPlayer) && meshRenderer != null && meshRenderer.enabled)
		{
			meshRenderer.enabled = false;
			minimapCol.enabled = true;
			Minimap.revealedSectionCount--;
			if (minimapRevealEventHandlers != null)
			{
				minimapRevealEventHandlers(actual: false);
			}
		}
	}

	private void OnDestroy()
	{
		MinimapSections.Remove(this);
	}
}
