	{
		initialized = false;
	}

	public void Initialize(Player newPlayer, Color pColor)
	{
		playerTransform = newPlayer.transform;
		player = newPlayer;
		ogCoopColor = pColor;
		SetColors(pColor);
		initialized = true;
