	public void SetColors(Color pColor)
	{
		if (!(spriteRenderer == null) && !(outlineRenderer == null))
		{
			if (GameController.coopOn)
			{
				Color.RGBToHSV(pColor, out var H, out var S, out var V);
				coopColor = Color.HSVToRGB(H, S + 0.12f, V + 0.1f);
				coopColor = new Color(coopColor.r, coopColor.g, coopColor.b, pColor.a);
				spriteRenderer.color = coopColor;
				outlineRenderer.color = coopOutlineColor;
				outlineRenderer.sprite = glowSprite;
			}
			else
			{
				spriteRenderer.color = singlePlayerColor;
				outlineRenderer.sprite = outlineSprite;
				outlineRenderer.color = singleOutlineColor;
			}
		}
	}

	public void Activate()
	{
		if (initialized)
		{
			isActive = true;
			SetColors(ogCoopColor);
