	{
		lockAtPosition = false;
		if (disable)
		{
			Disable();
		}
	}

	public void Update()
	{
		if (initialized && !(player == null) && !player.currentStateName.Contains("Pause") && !player.currentStateName.Contains("Dead") && !player.currentStateName.Contains("Fall") && !GameUI.pauseMenu.paused)
		{
			transform.localEulerAngles = Globals.GetRotationVector(player.GetInputVector(faceInputVector: false));
		}
	}

	public void LateUpdate()
	{
		if (initialized && !(player == null))
		{
			if (lockAtPosition)
			{
				transform.position = lockPosition;
			}
			else
			{
				transform.position = playerTransform.position;
			}
		}
	}
