		{
			Object.Destroy(gameObject);
			return;
		}
		instance = this;
		minimapCamera = GetComponent<Camera>();
		Object.DontDestroyOnLoad(gameObject);
		canvas = transform.Find("TransparentBGCanvas").GetComponent<Canvas>();
		enemyIndicatorTrans = transform.Find("TransparentBGCanvas/EnemyIndicator");
