		enemySkullsAnchoredPos = enemySkullsTrans.anchoredPosition;
		stageIndicatorTrans = transform.Find("TransparentBGCanvas/StageIndicators");
		stageIndicators = new Image[5];
		for (int i = 0; i < stageIndicators.Length; i++)
		{
			stageIndicators[i] = stageIndicatorTrans.Find("Stage" + i).GetComponent<Image>();
		}
		revealPercentageText = transform.Find("TransparentBGCanvas/RevealPercentage").GetComponent<Text>();
		floorIndicatorText = transform.Find("TransparentBGCanvas/FloorIndicator").GetComponent<Text>();
		TextManager.AddUIRef("minimap-enemyIcons", transform.Find("TransparentBGCanvas/EnemyIndicator").GetComponent<Text>());
		TextManager.AddUIRef(string.Empty, floorIndicatorText);
		TextManager.AddUIRef(string.Empty, revealPercentageText);
		zPosition = transform.position.z;
		ResetPosition();
	}

	private void ResetPosition()
	{
		if (inTierScene)
		{
			stageAvgPos = Level.AvgTileGridPosition;
			SetPosition(stageAvgPos);
		}
		else
		{
			SetPosition(stageOrigin);
		}
	}

	private void Start()
	{
		SceneManager.sceneLoaded += OnSceneLoaded;
		Disable();
	}

	private void OnDestroy()
	{
		SceneManager.sceneLoaded -= OnSceneLoaded;
	}

	public void OnSceneLoaded(Scene scene, LoadSceneMode loadSceneMode)
	{
		if (!NextLevelLoader.InTierScene(string.Empty))
		{
			floorIndicatorText.text = string.Empty;
			floorIndicatorText.text = GameController.StageTitle;
			inTierScene = false;
			if (IsActive)
			{
				Disable();
			}
		}
		else
		{
			inTierScene = true;
			floorIndicatorText.text = GameController.StageTitle;
			ResetPosition();
		}
	}

	public void Disable()
	{
		minimapCamera.enabled = false;
		canvas.enabled = false;
		if (minimapWasEnabled && inTierScene)
		{
			GameController.minimap.Activate();
			GameController.compass.gameObject.SetActive(value: true);
		}
	}

	public void Activate()
	{
		if (!inTierScene)
		{
			SoundManager.PlayAudio("MenuError");
			return;
		}
		ResetPosition();
		GameController.compass.gameObject.SetActive(value: false);
		SetFontSize();
		UpdateStageOrder();
		minimapCamera.enabled = true;
		canvas.enabled = true;
		minimapWasEnabled = GameController.minimap.IsActive();
		GameController.minimap.Disable();
	}

	private void LateUpdate()
	{
		if (IsActive && inTierScene)
		{
			SetPosition(stageOrigin * 0.5f + (stageAvgPos + Camera.main.transform.position) * 0.25f);
		}
	}

	private void Update()
	{
		if (!inTierScene || GameController.minimap == null || LoadingScreen.loading || GameUI.pauseMenu.paused)
		{
			if (IsActive)
			{
				Disable();
			}
			return;
		}
		if (InputController.GetAnyDeviceButtonDown("Map") != null)
		{
			if (IsActive)
			{
				Disable();
			}
			else
			{
				Activate();
			}
		}
		revealPercentageText.text = Minimap.RevealedPercentage;
	}

	private void SetPosition(Vector3 givenPosition)
	{
		givenPosition.z = zPosition;
		transform.position = givenPosition;
	}

	private void UpdateStageOrder()
	{
		for (int i = 0; i < stageIndicators.Length; i++)
		{
			if (i >= GameController.MaxTierCount || i >= GameController.levelNameList.Count)
			{
				stageIndicators[i].enabled = false;
				continue;
			}
			switch (GameController.levelNameList[i])
			{
			case "Ice":
				stageIndicators[i].sprite = iceSprite;
				break;
			case "Earth":
				stageIndicators[i].sprite = earthSprite;
				break;
			case "Fire":
				stageIndicators[i].sprite = fireSprite;
				break;
			case "Air":
				stageIndicators[i].sprite = airSprite;
				break;
			case "Lightning":
				stageIndicators[i].sprite = lightningSprite;
				break;
			}
			stageIndicators[i].enabled = true;
		}
	}

	public void SetFontSize()
	{
		enemySkullsTrans.anchoredPosition = enemySkullsAnchoredPos;
		floorIndicatorText.transform.localScale = Vector3.one;
		revealPercentageText.transform.localScale = Vector3.one;
		if (TextManager.currentLanguage == ChaosLang.Spanish)
		{
			floorIndicatorText.transform.localScale = new Vector3(1.1f, 1.1f, 1.1f);
			revealPercentageText.transform.localScale = new Vector3(1.2f, 1.2f, 1.2f);
			enemySkullsTrans.anchoredPosition = enemySkullsAnchoredPos + new Vector2(5f, 0f);
		}
		else if (TextManager.currentLanguage == ChaosLang.Korean)
		{
			floorIndicatorText.transform.localScale = new Vector3(1.1f, 1.1f, 1f);
			revealPercentageText.transform.localScale = new Vector3(1.1f, 1.1f, 1f);
			enemySkullsTrans.anchoredPosition = enemySkullsAnchoredPos + new Vector2(-24f, 0f);
		}
		else if (TextManager.currentLanguage == ChaosLang.Japanese)
		{
			enemySkullsTrans.anchoredPosition = enemySkullsAnchoredPos + new Vector2(-24f, 0f);
		}
		else if (TextManager.currentLanguage == ChaosLang.Chinese)
		{
			floorIndicatorText.transform.localScale = new Vector3(0.9f, 0.9f, 0.9f);
			revealPercentageText.transform.localScale = new Vector3(0.9f, 0.9f, 0.9f);
			enemySkullsTrans.anchoredPosition = enemySkullsAnchoredPos + new Vector2(-16f, 0f);
		}
		else if (TextManager.currentLanguage == ChaosLang.French)
		{
			enemySkullsTrans.anchoredPosition = enemySkullsAnchoredPos + new Vector2(4f, 0f);
