using System.Collections;
using Chaos.AnimatorExtensions;
using UnityEngine;
using UnityEngine.UI;

public class StageTitleUI : MonoBehaviour
{
	public static Color redOutlineColor = new Color(0.4f, 0.1f, 0.1f, 0.9f);

	public static Color yellowOutlineColor = new Color(0.6f, 0.41f, 0.2f, 1f);

	public static Color yellowColor = new Color(0.93f, 0.85f, 0.4f, 1f);

	public static Vector3 thickLineScale = new Vector3(1f, 5f, 1f);

	public static Vector3 thickLongLineScale = new Vector3(1.15f, 5f, 1f);

	public static Vector3 longLineScale = new Vector3(1.35f, 1.2f, 1f);

	public static Vector3 slightlyLongLineScale = new Vector3(1.15f, 1.2f, 1f);

	private static StageTitleUI instance = null;

	private Text stageTitleText;

	private Image stageTitleUnderline;

	public static string stageTitle;

	private bool announcementInProgress;

	public Outline stageTitleOutline;

	public Outline underlineOutline;

	public Animator anim;

	public Canvas canvas;

	public Text numberText;

	private Vector2 ogUnderlinePos;

	public static float largeFontLineOffset = 20f;

	private void Awake()
	{
		if (instance != null && instance != this)
		{
			Object.Destroy(gameObject);
			return;
		}
		instance = this;
		stageTitleText = transform.Find("StageTitle").GetComponent<Text>();
		TextManager.AddUIRef(string.Empty, stageTitleText);
		stageTitleUnderline = transform.Find("Underline").GetComponent<Image>();
		stageTitle = string.Empty;
		Object.DontDestroyOnLoad(gameObject);
	}

	private void Start()
	{
		ogUnderlinePos = stageTitleUnderline.rectTransform.anchoredPosition;
	}

	public bool AnimIsPlaying(float threshold = 1f)
	{
		return !anim.AnimPlayed(threshold);
	}

	public void StopAnnounce()
	{
		anim.Play("Idle");
	}

	public void Announce(string announceText, float duration = 0f, int fontSize = 60, Color? textColor = null, Color? lineColor = null, bool showUnderline = true, float animSpeed = 1f, float startingFrame = 0f, bool numberMode = false, Color? outlineColor = null, Vector3? lineScale = null, Color? underlineOutlineColor = null, float delayTime = 0f)
	{
		if (!(announceText == string.Empty))
		{
			StartCoroutine(Announcement(announceText, duration, fontSize, textColor, lineColor, showUnderline, animSpeed, startingFrame, numberMode, outlineColor, lineScale, underlineOutlineColor, delayTime));
		}
	}

	private IEnumerator Announcement(string announceText, float duration, int fontSize, Color? textColor, Color? lineColor, bool showUnderline, float animSpeed, float startingFrame, bool numberMode, Color? outlineColor, Vector3? lineScale, Color? underlineOutlineColor, float delayTime = 0f)
	{
		if (delayTime > 0f)
		{
			yield return new WaitForSeconds(delayTime);
		}
		int durationStopwatchID = -1;
		if (announcementInProgress)
		{
			announcementInProgress = false;
			for (int i = 0; i < 3; i++)
			{
				yield return null;
			}
		}
		announcementInProgress = true;
		anim.Play("Idle");
		yield return null;
		anim.speed = animSpeed;
		Text textToMod = stageTitleText;
		if (numberMode)
		{
			textToMod = numberText;
		}
		else
		{
			stageTitle = announceText;
		}
		textToMod.text = announceText;
		textToMod.fontSize = TextManager.GetAdjustedFontSize(fontSize);
		textToMod.color = (textColor.HasValue ? textColor.Value : Color.white);
		stageTitleUnderline.color = (lineColor.HasValue ? lineColor.Value : Color.white);
		stageTitleUnderline.enabled = showUnderline && !numberMode;
		if ((float)textToMod.fontSize >= 90f * TextManager.CurrentFontSizeMultiplier)
		{
			stageTitleUnderline.rectTransform.anchoredPosition = new Vector2(ogUnderlinePos.x, ogUnderlinePos.y - largeFontLineOffset * (float)textToMod.fontSize / (90f * TextManager.CurrentFontSizeMultiplier));
		}
		else
		{
			stageTitleUnderline.rectTransform.anchoredPosition = ogUnderlinePos;
		}
		if (!lineScale.HasValue)
		{
			stageTitleUnderline.rectTransform.localScale = Vector3.one;
		}
		else
		{
			stageTitleUnderline.rectTransform.localScale = lineScale.Value;
		}
		if (!outlineColor.HasValue)
		{
			stageTitleOutline.effectColor = Color.clear;
		}
		else
		{
			stageTitleOutline.effectColor = outlineColor.Value;
		}
		if (!underlineOutlineColor.HasValue)
		{
			underlineOutline.effectColor = Color.clear;
		}
		else
		{
			underlineOutline.effectColor = underlineOutlineColor.Value;
		}
		if (announcementInProgress)
		{
			durationStopwatchID = ChaosStopwatch.Begin(duration);
			if (numberMode)
			{
				anim.Play("AnnounceNumber", -1, startingFrame);
			}
			else
			{
				anim.Play("Announce", -1, startingFrame);
			}
			yield return null;
		}
		while (announcementInProgress && anim.GetAnimTime() < 0.3f)
		{
			yield return null;
		}
		while (announcementInProgress && !ChaosStopwatch.Check(durationStopwatchID))
		{
			anim.Play("Announce", -1, 0.55f);
			yield return null;
		}
		announcementInProgress = false;
	}

	public void AnnounceVictory(string textOverride = null)
	{
		string announceText = ((textOverride != null) ? textOverride : TextManager.GetUIText("bossRoom-victory"));
		float duration = 1f;
		int fontSize = 120;
		Color? textColor = yellowColor;
		Color? outlineColor = yellowOutlineColor;
		Color? lineColor = yellowColor;
		Vector3? lineScale = slightlyLongLineScale;
		Color? underlineOutlineColor = yellowOutlineColor;
		Announce(announceText, duration, fontSize, textColor, lineColor, showUnderline: true, 1f, 0.5f, numberMode: false, outlineColor, lineScale, underlineOutlineColor);
		ConfettiEffect poolItem = PoolManager.GetPoolItem<ConfettiEffect>();
		poolItem.reqFollowTrans = true;
		ConfettiEffect confettiEffect = poolItem;
		int? particleCount = 24;
		lineScale = GameController.cameraController.cameraWorldTrans.position;
		Transform cameraWorldTrans = GameController.cameraController.cameraWorldTrans;
		ParticleSystemOverride localSpaceOverride = ParticleEffectOverrides.LocalSpaceOverride;
		confettiEffect.Emit(particleCount, lineScale, localSpaceOverride, null, 0.1f, null, cameraWorldTrans);
		poolItem = PoolManager.GetPoolItem<ConfettiEffect>();
		poolItem.Emit(8, GameController.cameraController.cameraWorldTrans.position - Vector3.right * 2.5f, ParticleEffectOverrides.LocalSpaceOverride, null, 0.1f);
		poolItem = PoolManager.GetPoolItem<ConfettiEffect>();
		poolItem.Emit(8, GameController.cameraController.cameraWorldTrans.position + Vector3.right * 2.5f, ParticleEffectOverrides.LocalSpaceOverride, null, 0.1f);
	}

	public void AnnounceCombo(int comboCount = 99)
	{
		string announceText = comboCount + TextManager.GetUIText("bossRoom-comboAnnounce");
		float duration = 0.75f;
		Color? textColor = Color.red;
		Announce(announceText, duration, 60, textColor, Globals.chaosRed, showUnderline: true, 1f, 0f, numberMode: false, redOutlineColor);
	}

	public void AnnounceFight(string textOverride = null)
	{
		Announce((textOverride != null) ? textOverride : TextManager.GetUIText("bossRoom-fight"), fontSize: 180, textColor: Color.red, lineColor: Color.red, animSpeed: 1.75f, lineScale: thickLineScale, duration: 0f, showUnderline: true, startingFrame: 0f, numberMode: false, outlineColor: redOutlineColor, underlineOutlineColor: redOutlineColor);
	}
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class EquipMenu : MonoBehaviour
{
	public Player player;

	public LowerHUD parentHUD;

	[HideInInspector]
	public bool referencesFound;

	private Image[] buttonImages;

	private Image[] skillIcons;

	private Image[] skillBorders;

	private int navigationIndex;

	private int maxSkillCount;

	private GameObject skillSelectedBorder;

	private Text swapText;

	private GameObject swapPrompt;

	[HideInInspector]
	public GameObject dropPrompt;

	private Image swapButtonImage;

	private Image dropButtonImage;

	private Image selectionBorder;

	private Color swapTextColor;

	private Color selectionColor;

	private Color skillToSwapColor = Color.green;

	private float fadeAlphaValue = 1f;

	private bool fadeOut;

	private Vector2 cursorVector;

	private bool inputReceived;

	private bool currentlySwapping;

	private int skillToSwapIndex;

	public Player.SkillState skillToSwap;

	private GameObject stockSkillBar;

	private bool menuClicked;

	private bool quickSwapCompleted;

	[HideInInspector]
	public InventoryMenu inventoryMenu;

	[HideInInspector]
	public OutfitMenu outfitMenu;

	[HideInInspector]
	public Text infoText;

	private bool hasFocus;

	public GameObject skillFlagsObj;

	public Image[] skillFlags = new Image[SpellBookUI.MaxSkillFlags];

	public Sprite[] skillFlagSprites = new Sprite[Player.SkillState.MaxSkillFlags];

	private List<int> skillFlagList = new List<int>(Player.SkillState.MaxSkillFlags);

	public bool HasFocus => hasFocus;

	private void Awake()
	{
		maxSkillCount = 6;
		TextManager.AddUIRef("playerMenu-spellsTitle", transform.Find("TitleBar/Text").GetComponent<Text>());
		TextManager.AddUIRef("playerMenu-swapping", transform.Find("SwapText").GetComponent<Text>());
		TextManager.AddUIRef("playerMenu-swapPrompt", transform.Find("SwapPrompt/Text").GetComponent<Text>());
		TextManager.AddUIRef("playerMenu-dropPrompt", transform.Find("DropPrompt/Text").GetComponent<Text>());
	}

	public void Release()
	{
		ExitMenu(playAudio: false);
		player = null;
	}

	private void Update()
	{
		if (player == null || !hasFocus)
		{
			return;
		}
		HandleSelectionColor();
		if (quickSwapCompleted)
		{
			parentHUD.SetEquipMenuStatus(givenStatus: false);
		}
		else
		{
			if (HandleQuickSwap())
			{
				return;
			}
			HandleNavigation();
			if (!player.inputDevice.GetButtonDown("Confirm") && !menuClicked)
			{
				return;
			}
			menuClicked = false;
			if (!currentlySwapping)
			{
				currentlySwapping = true;
				skillToSwapIndex = navigationIndex;
				skillToSwap = ((skillToSwapIndex >= maxSkillCount) ? (skillToSwap = player.stockSkill) : player.assignedSkills[skillToSwapIndex]);
				SelectSlot(navigationIndex);
				SoundManager.PlayAudio("Equip");
				return;
			}
			if (navigationIndex < maxSkillCount)
			{
				if ((skillToSwap == null && player.assignedSkills[navigationIndex] == null) || (skillToSwapIndex == maxSkillCount && IsSignificantSkill(player.assignedSkills[navigationIndex], skillToSwap)))
				{
					SelectSlot(navigationIndex);
				}
				string skillID = ((player.assignedSkills[navigationIndex] != null) ? player.assignedSkills[navigationIndex].skillID : string.Empty);
				if (skillToSwapIndex < maxSkillCount)
				{
					player.AssignSkillSlot(skillToSwapIndex, skillID);
				}
				else
				{
					if (IsSignificantSkill(player.assignedSkills[navigationIndex], skillToSwap))
					{
						SoundManager.PlayAudio("MenuError");
						return;
					}
					player.stockSkill = player.assignedSkills[navigationIndex];
				}
				skillID = ((skillToSwap != null) ? skillToSwap.skillID : string.Empty);
				player.AssignSkillSlot(navigationIndex, skillID);
			}
			else if (skillToSwapIndex < maxSkillCount)
			{
				if (IsSignificantSkill(player.assignedSkills[skillToSwapIndex], player.stockSkill))
				{
					SoundManager.PlayAudio("MenuError");
					return;
				}
				string skillID2 = player.stockSkill.skillID;
				player.stockSkill = skillToSwap;
				player.AssignSkillSlot(skillToSwapIndex, skillID2);
				SelectSlot(navigationIndex);
			}
			currentlySwapping = false;
			skillBorders[skillToSwapIndex].color = Color.white;
			skillToSwap = null;
			skillToSwapIndex = -1;
			SoundManager.PlayAudio("Equip");
			parentHUD.cooldownUI.RefreshEntries();
			LoadEquipMenu(resetIndices: false);
		}
	}

	private void HandleSelectionColor()
	{
		if ((fadeAlphaValue >= 1f && !fadeOut) || (fadeAlphaValue <= 0.6f && fadeOut))
		{
			fadeOut = !fadeOut;
		}
		fadeAlphaValue += Time.deltaTime * (float)((!fadeOut) ? 1 : (-1));
		selectionColor.a = fadeAlphaValue;
		selectionBorder.color = selectionColor;
		swapTextColor.a = fadeAlphaValue;
		swapText.color = swapTextColor;
		if (currentlySwapping)
		{
			skillToSwapColor.a = fadeAlphaValue;
			skillBorders[skillToSwapIndex].color = skillToSwapColor;
		}
	}

	private bool IsSignificantSkill(Player.SkillState skillToReplace, Player.SkillState incomingSkill = null)
	{
		if (incomingSkill != null && incomingSkill.isBasic)
		{
			return skillToReplace == null || !skillToReplace.isBasic;
		}
		if ((skillToReplace == null || !skillToReplace.isBasic) && incomingSkill != null && incomingSkill.isBasic)
		{
			return true;
		}
		return skillToReplace != null && (skillToReplace.isSignature || skillToReplace.isBasic || skillToReplace.isDash);
	}

	private bool HandleQuickSwap()
	{
		if (!quickSwapCompleted && player.inputDevice.GetButton("EquipMenu") && player.stockSkill != null)
		{
			skillBorders[6].color = Color.green;
			swapText.gameObject.SetActive(value: true);
			swapPrompt.SetActive(value: false);
			for (int i = 0; i < player.assignedSkills.Length; i++)
			{
				if (player.inputDevice.GetButton("Skill" + i))
				{
					if (!IsSignificantSkill(player.assignedSkills[i], player.stockSkill))
					{
						Player.SkillState stockSkill = player.stockSkill;
						player.stockSkill = player.assignedSkills[i];
						player.AssignSkillSlot(i, stockSkill.skillID);
						SoundManager.PlayAudio("Equip");
						parentHUD.cooldownUI.RefreshEntries();
						quickSwapCompleted = true;
						break;
					}
					SoundManager.PlayAudio("MenuError");
				}
			}
			return true;
		}
		if (!currentlySwapping)
		{
			skillSelectedBorder.transform.position = skillBorders[navigationIndex].transform.position;
			skillBorders[6].color = Color.white;
			swapText.gameObject.SetActive(value: false);
			swapPrompt.SetActive(value: true);
		}
		return false;
	}

	private void HandleNavigation()
	{
		cursorVector = player.inputDevice.GetMoveVector();
		if (inputReceived && cursorVector.magnitude < 0.2f)
		{
			inputReceived = false;
		}
		else
		{
			if (inputReceived || !(cursorVector.magnitude > 0.3f))
			{
				return;
			}
			SoundManager.PlayAudio("MenuMove");
			inputReceived = true;
			if (Mathf.Abs(cursorVector.x) > Mathf.Abs(cursorVector.y))
			{
				if (navigationIndex != maxSkillCount)
				{
					navigationIndex = ChangeHorizontalIndex(navigationIndex, cursorVector.x > 0f);
					SelectSlot(navigationIndex);
				}
			}
			else if (cursorVector.y > 0f)
			{
				if (navigationIndex >= 0 && navigationIndex < maxSkillCount)
				{
					SwapFocus(takeFocus: false, giveNavIndex: false, 1);
					return;
				}
				if (navigationIndex == maxSkillCount)
				{
					navigationIndex = 5;
				}
				SelectSlot(navigationIndex);
			}
			else if (player.stockSkill != null && player.stockSkill.skillID != string.Empty && navigationIndex < maxSkillCount)
			{
				navigationIndex = maxSkillCount;
				SelectSlot(navigationIndex);
			}
			else if (!currentlySwapping)
			{
				bool giveNavIndex = navigationIndex < maxSkillCount;
				SwapFocus(takeFocus: false, giveNavIndex);
			}
		}
	}

	private int ChangeHorizontalIndex(int navIndex, bool increment)
	{
		return (navIndex + (increment ? 1 : (-1)) + maxSkillCount) % maxSkillCount;
	}

	public void SelectSlot(int navIndex)
	{
		if (currentlySwapping)
		{
			for (int i = 0; i < 7; i++)
			{
				if (i != skillToSwapIndex)
				{
					skillBorders[i].color = Color.white;
				}
			}
			swapText.gameObject.SetActive(value: true);
			swapPrompt.SetActive(value: false);
			if (skillToSwapIndex == maxSkillCount)
			{
				for (int j = 0; j < maxSkillCount; j++)
				{
					if (IsSignificantSkill(player.assignedSkills[j], player.stockSkill))
					{
						skillBorders[j].color = Vector4.one * 0.5f;
						skillIcons[j].color = Vector4.one * 0.5f;
					}
				}
			}
			else if (IsSignificantSkill(skillToSwap, player.stockSkill) && player.stockSkill != null && player.stockSkill.skillID != string.Empty)
			{
				skillBorders[6].color = Vector4.one * 0.5f;
				skillIcons[6].color = Vector4.one * 0.5f;
			}
		}
		else
		{
			swapText.gameObject.SetActive(value: false);
			swapPrompt.SetActive(value: true);
			for (int k = 0; k < 7; k++)
			{
				skillIcons[k].color = Color.white;
				skillBorders[k].color = ((k >= maxSkillCount || !IsSignificantSkill(player.assignedSkills[k])) ? Color.white : Color.gray);
			}
		}
		navigationIndex = navIndex;
		skillSelectedBorder.transform.position = skillBorders[navigationIndex].transform.position;
		if (hasFocus)
		{
			Player.SkillState skillState = null;
			skillState = ((navIndex >= maxSkillCount) ? player.stockSkill : player.assignedSkills[navIndex]);
			if (skillState != null)
			{
				infoText.text = "[<color=#FFCC00>" + TextManager.GetSkillName(skillState.skillID) + "</color>]\n" + TextManager.GetSkillDescription(skillState.skillID, skillState.IsEmpowered, skillState.element == ElementType.Chaos);
			}
			else
			{
				infoText.text = string.Empty;
			}
			SetSkillFlagImages(skillState);
		}
	}

	public void LoadEquipMenu(bool resetIndices = true)
	{
		currentlySwapping = false;
		SwapFocus(takeFocus: true);
		player.fsm.ChangeState("Paused");
		SetUIButtonsToMatchInputDev();
		for (int i = 0; i < 7; i++)
		{
			skillBorders[i].color = Color.white;
		}
		for (int j = 0; j < player.assignedSkills.Length; j++)
		{
			if (player.assignedSkills[j] == null)
			{
				skillIcons[j].gameObject.SetActive(value: false);
				continue;
			}
			skillIcons[j].gameObject.SetActive(value: true);
			skillIcons[j].GetComponent<Image>().sprite = IconManager.GetSkillIcon(player.assignedSkills[j].skillID);
		}
		if (player.stockSkill == null || player.stockSkill.skillID == string.Empty)
		{
			if (resetIndices)
			{
				navigationIndex = 0;
			}
			stockSkillBar.SetActive(value: false);
		}
		else
		{
			if (resetIndices)
			{
				navigationIndex = maxSkillCount;
			}
			stockSkillBar.SetActive(value: true);
			skillIcons[maxSkillCount].sprite = IconManager.GetSkillIcon(player.stockSkill.skillID);
		}
		SelectSlot(navigationIndex);
		SoundManager.PlayMenuAudio(open: true);
	}

	private void SetUIButtonsToMatchInputDev()
	{
		ChaosInputDevice.InputScheme inputScheme = player.inputDevice.inputScheme;
		if (!referencesFound)
		{
			referencesFound = true;
			buttonImages = new Image[6];
			skillBorders = new Image[7];
			skillIcons = new Image[7];
			for (int i = 0; i < 6; i++)
			{
				buttonImages[i] = transform.Find("EquipBar/ButtonIcons/Button" + (i + 1)).GetComponent<Image>();
				skillBorders[i] = transform.Find("EquipBar/Skills/Skill" + (i + 1)).GetComponent<Image>();
				skillIcons[i] = skillBorders[i].transform.Find("SkillIcon").GetComponent<Image>();
			}
			stockSkillBar = transform.Find("StockSkillBar").gameObject;
			skillBorders[6] = transform.Find("StockSkillBar/StockSkill").GetComponent<Image>();
			skillIcons[6] = skillBorders[6].transform.Find("SkillIcon").GetComponent<Image>();
			skillSelectedBorder = transform.Find("EquipBar/SkillSelectedBorder").gameObject;
			selectionBorder = skillSelectedBorder.GetComponent<Image>();
			selectionColor = selectionBorder.color;
			swapText = transform.Find("SwapText").GetComponent<Text>();
			swapTextColor = swapText.color;
			swapText.gameObject.SetActive(value: false);
			swapPrompt = transform.Find("SwapPrompt").gameObject;
			swapButtonImage = swapPrompt.transform.Find("ButtonIcon").GetComponent<Image>();
			swapPrompt.SetActive(value: false);
			dropPrompt = transform.Find("DropPrompt").gameObject;
			dropButtonImage = dropPrompt.transform.Find("ButtonIcon").GetComponent<Image>();
			dropPrompt.SetActive(value: false);
		}
		if (swapButtonImage != null)
		{
			swapButtonImage.sprite = GameUI.GetInputSprite(inputScheme);
		}
		if (dropButtonImage != null)
		{
			dropButtonImage.sprite = GameUI.GetInputSprite(inputScheme, "Interact");
		}
		for (int j = 0; j < 6; j++)
		{
			buttonImages[j].sprite = GameUI.GetInputSprite(inputScheme, "Slot" + j);
		}
	}

	public void ExitMenu(bool playAudio = true)
	{
		if (player != null)
		{
			Player.SkillState[] assignedSkills = player.assignedSkills;
			for (int i = 0; i < assignedSkills.Length; i++)
			{
				assignedSkills[i]?.SetSkillSlot();
			}
			if (player.fsm.currentStateName == "Paused")
			{
				player.fsm.ChangeState("Idle");
			}
		}
		quickSwapCompleted = false;
		skillToSwap = null;
		skillToSwapIndex = -1;
		if (currentlySwapping)
		{
			currentlySwapping = false;
			SelectSlot(navigationIndex);
		}
		if (playAudio)
		{
			SoundManager.PlayMenuAudio(open: false);
		}
		gameObject.SetActive(value: false);
	}

	private void SwapFocus(bool takeFocus = false, bool giveNavIndex = false, int givenMenu = 0)
	{
		if (takeFocus)
		{
			SetFocus(status: true);
			inventoryMenu.SetFocus(status: false);
			outfitMenu.SetFocus(status: false);
		}
		else
		{
			SetFocus(status: false);
			inventoryMenu.SetFocus(givenMenu == 0, (player.stockSkill != null || !giveNavIndex) ? (-1) : navigationIndex);
			outfitMenu.SetFocus(givenMenu == 1);
		}
	}

	public void SetFocus(bool status, int incIndex = -1)
	{
		SetUIButtonsToMatchInputDev();
		hasFocus = status;
		skillSelectedBorder.SetActive(status);
		skillFlagsObj.SetActive(status || inventoryMenu.HasFocus);
		swapPrompt.SetActive(status);
		if (status)
		{
			if (incIndex > -1 && player.stockSkill == null)
			{
				navigationIndex = incIndex % maxSkillCount;
			}
			if (navigationIndex >= 0)
			{
				SelectSlot(navigationIndex);
			}
		}
		inputReceived = true;
	}

	public void SkillClicked(int slotNumber)
	{
		if (player.IsKeyboardInput || GameController.activePlayers.Length <= 1)
		{
			navigationIndex = slotNumber;
			menuClicked = true;
			SwapFocus(takeFocus: true);
		}
	}

	public void SkillHovered(int slotNumber)
	{
		if (player.IsKeyboardInput || GameController.activePlayers.Length <= 1)
		{
			navigationIndex = slotNumber;
			SelectSlot(slotNumber);
			SwapFocus(takeFocus: true);
		}
	}

	private void SetSkillFlagImages(Player.SkillState curSkill)
	{
		for (int i = 0; i < SpellBookUI.MaxSkillFlags; i++)
		{
			skillFlags[i].enabled = false;
		}
		if (curSkill == null)
		{
			return;
		}
		SpellBookUI.SetSkillFlagList(curSkill, ref skillFlagList);
		for (int j = 0; j < SpellBookUI.MaxSkillFlags; j++)
		{
			if (j >= skillFlagList.Count)
			{
				skillFlags[j].enabled = false;
				continue;
			}
			skillFlags[j].sprite = skillFlagSprites[skillFlagList[j]];
			skillFlags[j].enabled = true;
		}
	}
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class InventoryMenu : MonoBehaviour
{
	private class InventoryItemEntry
	{
		public string itemID;

		public RectTransform rectTrans;

		public Image image;

		public InventoryMenuItemEntry entryScript;

		public InventoryItemEntry(string id, RectTransform rTrans, Image img, InventoryMenuItemEntry entry)
		{
			itemID = id;
			rectTrans = rTrans;
			image = img;
			entryScript = entry;
		}
	}

	private GameObject itemEntryPrefab;

	private Transform itemArea;

	private List<InventoryItemEntry> itemEntries;

	private List<string> givenItemList;

	private GameObject itemObject;

	private InventoryItemEntry entry;

	private int itemCount;

	private int column;

	private int row;

	private float xMin;

	private float yMax;

	public Player player;

	[HideInInspector]
	public OutfitMenu outfitMenu;

	[HideInInspector]
	public EquipMenu equipMenu;

	[HideInInspector]
	public Text infoText;

	private string infoString;

	private bool hasFocus;

	public int columnCount = 6;

	public int rowCount = 2;

	public float entryWidth = 0.115f;

	public float initWidthSpacing = 0.03f;

	public float widthSpacing = 0.05f;

	public float entryHeight = 0.32f;

	public float initHeightSpacing = 0.1f;

	public float heightSpacing = 0.12f;

	private int navigationIndex;

	private Vector2 navigationVector;

	private bool inputReceived;

	private RectTransform selectionTrans;

	private Image selectionBorder;

	private Color selectionColor;

	private bool fadeOut;

	private Item selectedItem;

	public Sprite[] itemFlagSprites = new Sprite[3];

	private int itemFlagIndex = -1;

	public bool HasFocus => hasFocus;

	public void Awake()
	{
		itemEntryPrefab = ChaosBundle.Get("Assets/Prefabs/UI/InventoryUIItemEntry.prefab");
		itemEntries = new List<InventoryItemEntry>();
		itemArea = transform.Find("ItemArea");
		selectionTrans = transform.Find("SelectionBorder").GetComponent<RectTransform>();
		selectionBorder = transform.Find("SelectionBorder").GetComponent<Image>();
		selectionColor = selectionBorder.color;
		itemFlagSprites[0] = IconManager.GetRelicUISprite("ItemFlagOffense");
		itemFlagSprites[1] = IconManager.GetRelicUISprite("ItemFlagDefense");
		itemFlagSprites[2] = IconManager.GetRelicUISprite("ItemFlagMisc");
		TextManager.AddUIRef("playerMenu-relicsTitle", transform.Find("TitleBar/Text").GetComponent<Text>());
		selectionTrans.gameObject.SetActive(value: false);
		gameObject.SetActive(value: false);
	}

	public void Update()
	{
		if (!(player == null) && hasFocus && itemCount != 0)
		{
			HandleNavigation();
			HandleSelectionColor();
			HandleDropItem();
			HandleItemHeadgear();
		}
	}

	private void HandleSelectionColor()
	{
		if ((selectionBorder.color.a >= 1f && !fadeOut) || (selectionBorder.color.a <= 0.6f && fadeOut))
		{
			fadeOut = !fadeOut;
		}
		selectionColor.a += Time.deltaTime * (float)((!fadeOut) ? 1 : (-1));
		selectionBorder.color = selectionColor;
	}

	private void HandleNavigation()
	{
		navigationVector = player.inputDevice.GetMoveVector();
		if (inputReceived && navigationVector.magnitude < 0.2f)
		{
			inputReceived = false;
		}
		else
		{
			if (inputReceived || !(navigationVector.magnitude > 0.3f))
			{
				return;
			}
			SoundManager.PlayAudio("MenuMove");
			inputReceived = true;
			row = navigationIndex / columnCount * columnCount;
			if (Mathf.Abs(navigationVector.x) > Mathf.Abs(navigationVector.y))
			{
				if (navigationVector.x > 0f)
				{
					column = navigationIndex + 1;
					navigationIndex = ((column >= row + columnCount || column >= itemCount) ? row : column);
				}
				else
				{
					column = navigationIndex - 1;
					if (column < row)
					{
						if (column + columnCount < itemCount)
						{
							navigationIndex = column + columnCount;
						}
						else
						{
							navigationIndex = itemCount - 1;
						}
					}
					else
					{
						navigationIndex = column;
					}
				}
			}
			else if (navigationVector.y > 0f)
			{
				if (navigationIndex - columnCount < 0)
				{
					SwapFocus(takeFocus: false, giveNavIndex: true);
					return;
				}
				navigationIndex -= columnCount;
			}
			else if (navigationIndex + columnCount < itemCount)
			{
				navigationIndex += columnCount;
			}
			else if (row + columnCount < itemCount)
			{
				navigationIndex = itemCount - 1;
			}
			SelectItem(navigationIndex);
		}
	}

	private void HandleItemHeadgear()
	{
		if (player.inputDevice.GetButtonDown("Confirm") && player.inventory.GetItem(selectedItem.ID) is HeadgearItem headgearItem && headgearItem.curHeadgear != null)
		{
			headgearItem.curHeadgear.Equip();
		}
	}

	private void HandleDropItem()
	{
		if (player.inputDevice.GetButtonDown("Interact"))
		{
			player.inventory.DropItem(selectedItem.ID);
			int num = navigationIndex;
			LoadMenu(player);
			if (num >= itemCount)
			{
				num--;
			}
			if (num < 0)
			{
				navigationIndex = 0;
				SwapFocus();
			}
			else
			{
				navigationIndex = num;
				SelectItem(navigationIndex);
			}
		}
	}

	private void SelectItem(int navIndex)
	{
		selectionTrans.position = itemEntries[navIndex].rectTrans.position;
		selectedItem = player.inventory.GetItem(givenItemList[navIndex]);
		if (hasFocus)
		{
			infoString = "[<color=#FFCC00>" + TextManager.GetItemName(selectedItem.ID) + "</color>]";
			if (selectedItem.isCursed)
			{
				infoString = infoString + " [<color=#FF0000>" + TextManager.GetUIText("inventory-cursedTag") + "</color>]";
			}
			if (selectedItem.isGroupItem)
			{
				infoString += (selectedItem as GroupItem).CompletionProgStr;
			}
			else if (GroupItemManager.groupsDict.ContainsKey(selectedItem.parentGroupID))
			{
				string text = infoString;
				infoString = text + "  (1/" + GroupItemManager.groupsDict[selectedItem.parentGroupID].Count + ")";
			}
			infoString = infoString + "\n" + TextManager.GetItemDescription(selectedItem.ID, player.playerID);
			infoText.text = infoString;
			SetItemFlagImages(selectedItem);
		}
	}

	public void LoadMenu(Player p)
	{
		player = p;
		givenItemList = player.inventory.GetItemIDList();
		itemCount = givenItemList.Count;
		if (givenItemList.Count > 30)
		{
			Debug.Log("Items won't fit in inventory");
			itemCount = 30;
		}
		for (int i = itemEntries.Count; i < itemCount; i++)
		{
			itemObject = Object.Instantiate(itemEntryPrefab);
			itemObject.transform.SetParent(itemArea.transform);
			itemEntries.Add(new InventoryItemEntry(string.Empty, itemObject.GetComponent<RectTransform>(), itemObject.GetComponent<Image>(), itemObject.GetComponent<InventoryMenuItemEntry>()));
		}
		for (int j = 0; j < itemCount; j++)
		{
			column = j % columnCount;
			row = j / columnCount;
			xMin = initWidthSpacing + (entryWidth + widthSpacing) * (float)column;
			yMax = 1f - (initHeightSpacing + (entryHeight + heightSpacing) * (float)row);
			entry = itemEntries[j];
			entry.rectTrans.gameObject.name = givenItemList[j];
			entry.entryScript.parentInventoryMenu = this;
			entry.entryScript.index = j;
			entry.itemID = givenItemList[j];
			entry.rectTrans.anchorMin = new Vector2(xMin, yMax - entryHeight);
			entry.rectTrans.anchorMax = new Vector2(xMin + entryWidth, yMax);
			entry.rectTrans.offsetMin = Vector2.zero;
			entry.rectTrans.offsetMax = Vector2.zero;
			entry.rectTrans.localScale = Vector3.one;
			entry.image.enabled = true;
			entry.image.sprite = IconManager.GetItemIcon((j >= givenItemList.Count) ? IconManager.unavailableItemName : givenItemList[j]);
		}
		for (int k = itemCount; k < itemEntries.Count; k++)
		{
			entry = itemEntries[k];
			entry.rectTrans.gameObject.name = "(None)";
			entry.entryScript.parentInventoryMenu = this;
			entry.entryScript.index = -1;
			entry.itemID = string.Empty;
			entry.image.enabled = false;
		}
		gameObject.SetActive(value: true);
		if (itemCount == 0)
		{
			SwapFocus();
			return;
		}
		navigationIndex = 0;
		SelectItem(navigationIndex);
	}

	public void ExitMenu()
	{
		gameObject.SetActive(value: false);
	}

	private void SwapFocus(bool takeFocus = false, bool giveNavIndex = false)
	{
		SetFocus(takeFocus);
		equipMenu.SetFocus(!takeFocus, (!giveNavIndex) ? (-1) : navigationIndex);
		outfitMenu.SetFocus(status: false);
	}

	public void SetFocus(bool status, int incIndex = -1)
	{
		if (status && itemCount == 0)
		{
			SwapFocus();
			return;
		}
		hasFocus = status;
		equipMenu.skillFlagsObj.SetActive(status || equipMenu.HasFocus);
		equipMenu.dropPrompt.SetActive(status);
		if (selectionTrans != null)
		{
			selectionTrans.gameObject.SetActive(status);
		}
		if (status)
		{
			if (incIndex < 0)
			{
				incIndex = 5;
			}
			incIndex = ((incIndex >= itemCount) ? (itemCount - 1) : (incIndex % 6));
			navigationIndex = incIndex;
			SelectItem(navigationIndex);
		}
		inputReceived = true;
	}

	public void ItemSelected(int itemIndex)
	{
		if ((player.IsKeyboardInput || GameController.activePlayers.Length <= 1) && itemIndex >= 0 && itemIndex < itemCount)
		{
			SwapFocus(takeFocus: true);
			SelectItem(itemIndex);
			navigationIndex = itemIndex;
		}
	}

	private void SetItemFlagImages(Item selectedItem)
	{
		for (int i = 0; i < SpellBookUI.MaxSkillFlags; i++)
		{
			equipMenu.skillFlags[i].enabled = false;
		}
		if (selectedItem != null)
		{
			switch (selectedItem.category)
			{
			case Item.Category.Offense:
				itemFlagIndex = 0;
				break;
			case Item.Category.Defense:
				itemFlagIndex = 1;
				break;
			case Item.Category.Misc:
				itemFlagIndex = 2;
				break;
			default:
				itemFlagIndex = -1;
				break;
			}
			if (itemFlagIndex > -1)
			{
				equipMenu.skillFlags[0].sprite = itemFlagSprites[itemFlagIndex];
				equipMenu.skillFlags[0].enabled = true;
			}
		}
	}
}
