	private void LoadPlayerRelics()
	{
		categoryInfoDict.Clear();
		categoryInfoDict[Item.Category.Offense] = new CategoryInfo();
		switch (currentFocus)
		{
		case RCFocus.TypePage:
			switch (currentTypeIndex)
			{
			case 0:
				currentCategory = Item.Category.Offense;
				break;
			case 1:
				currentCategory = Item.Category.Defense;
				break;
			case 2:
				currentCategory = Item.Category.Misc;
				break;
			}
			{
				foreach (KeyValuePair<Item.Category, RelicChestUIDrawer> item in rcRef.drawerDict)
				{
					if (item.Key == currentCategory)
					{
						item.Value.Open();
					}
					else
					{
						item.Value.Close();
					}
				}
				break;
			}
		case RCFocus.SelectionPage:
			rcRef.selectCursor.gameObject.SetActive(value: true);
			rcRef.selectCursor.position = rcRef.selectIcons[currentSelectionIndex].transform.position;
			break;
		}
	}

	public void ConfirmSelected()
	{
		switch (currentFocus)
		{
		case RCFocus.TypePage:
			LoadSelectionPage();
			SetFocus(RCFocus.SelectionPage);
			break;
		case RCFocus.SelectionPage:
			if (AssignPlayerItem())
			{
				SetFocus(RCFocus.TypePage, activateCall: false, relicSelected: true);
				SoundManager.PlayAudio("WoodPickUp");
			}
			break;
		}
	}

	public void CancelSelected()
	{
		switch (currentFocus)
		{
		case RCFocus.TypePage:
			Deactivate();
			break;
		case RCFocus.SelectionPage:
			SetFocus(RCFocus.TypePage);
			break;
		}
	}

	public void SetFocus(RCFocus givenFocus, bool activateCall = false, bool relicSelected = false)
	{
		switch (givenFocus)
		{
		case RCFocus.TypePage:
			currentFocus = givenFocus;
			if (activateCall)
			{
				rcRef.typeUIBase.Toggle(show: true, forceInstant: true);
				LoadTypePage();
			}
			else if (relicSelected)
			{
				rcRef.relicSelectTrans.position = rcRef.selectCursor.position;
				rcRef.relicSelectTrans.anchoredPosition += new Vector2(-12f, -12f);
				rcRef.relicSelectIcon.sprite = IconManager.GetItemIcon(currentPlayer.designatedItemID);
				rcRef.relicSelectTrans.gameObject.SetActive(value: true);
				rcRef.currentIcon.enabled = false;
				rcRef.typeBG.enabled = false;
				rcRef.offenseDrawer.Show(visible: false);
				rcRef.defenseDrawer.Show(visible: false);
				rcRef.miscDrawer.Show(visible: false);
				PlayerUIBase typeUIBase = rcRef.typeUIBase;
				typeUIBase.toggleEndEventHandlers = (PlayerUIBase.ToggleEndEventHandler)Delegate.Combine(typeUIBase.toggleEndEventHandlers, new PlayerUIBase.ToggleEndEventHandler(RelicSelectCallback));
				rcRef.typeUIBase.Toggle();
			}
			else
			{
				rcRef.typeUIBase.Toggle();
				LoadTypePage();
			}
			rcRef.selectRelicUIBase.Toggle(show: false);
			break;
		case RCFocus.SelectionPage:
			SoundManager.PlayAudio("RelicChestOpenFull");
			currentFocus = givenFocus;
			rcRef.typeUIBase.Toggle(show: false, forceInstant: true);
			rcRef.selectRelicUIBase.Toggle(show: true, forceInstant: true);
			break;
		}
		rcRef.selectCursor.gameObject.SetActive(value: false);
	}

	private void RelicSelectCallback()
	{
		StartCoroutine("PlayRelicSelectAnim");
	}

	private IEnumerator PlayRelicSelectAnim()
	{
		PlayerUIBase typeUIBase = rcRef.typeUIBase;
		typeUIBase.toggleEndEventHandlers = (PlayerUIBase.ToggleEndEventHandler)Delegate.Remove(typeUIBase.toggleEndEventHandlers, new PlayerUIBase.ToggleEndEventHandler(RelicSelectCallback));
		LoadTypePage(animMode: true);
		rcRef.relicSelectTrans.gameObject.SetActive(value: true);
		ChaosQuickStopwatch relicSelectTimer = new ChaosQuickStopwatch(0.15f)
		{
			IsRunning = true
		};
		Vector2 startPos = rcRef.relicSelectTrans.anchoredPosition;
		Vector2 targetPos = new Vector2(22f, -226f);
		while (relicSelectTimer.IsRunning)
		{
			rcRef.relicSelectTrans.anchoredPosition = Vector2.Lerp(startPos, targetPos, relicSelectTimer.TimePercentage);
			yield return null;
		}
		rcRef.typeBG.enabled = true;
		rcRef.offenseDrawer.Show();
		rcRef.defenseDrawer.Show();
		rcRef.miscDrawer.Show();
		rcRef.relicSelectTrans.gameObject.SetActive(value: false);
		rcRef.currentIcon.enabled = true;
		rcRef.typePageAnim.Play("RelicSelected", -1, 0f);
		SoundManager.PlayAudio("Equip");
	}

	public bool AssignPlayerItem()
	{
		string text = currentSelectionList[currentStartIndex + currentSelectionIndex];
		if (Item.IsUnlocked(text))
		{
			currentPlayer.inventory.RemoveItem(currentPlayer.designatedItemID);
			currentPlayer.designatedItemID = text;
			currentPlayer.GiveDesignatedItem(text);
			GameDataManager.Save(updateCurrentData: true, updatePlayerData: true);
			currentPlayer.health.RestoreHealth(9999, showDisplayText: false, playSound: false, fullyRestoreHealth: true);
			currentID = text;
			return true;
		}
		SoundManager.PlayAudio("MenuError");
		return false;
	}

	private int GetNavigationIndex(int givenIndex, int givenRowCount, int givenColCount, InputDirection givenInputDir)
	{
		if (givenInputDir == InputDirection.None)
		{
			initNavDelayReset = true;
			navTimer.IsRunning = false;
			autoNavTimer.IsRunning = false;
			return givenIndex;
		}
		if (navTimer.IsRunning || autoNavTimer.IsRunning)
		{
			return givenIndex;
		}
		int num = givenIndex;
		switch (givenInputDir)
		{
		case InputDirection.Up:
			if (givenIndex >= givenColCount)
			{
				num = givenIndex - givenColCount;
			}
			break;
		case InputDirection.Down:
			if (givenIndex < (givenRowCount - 1) * givenColCount)
			{
				num = givenIndex + givenColCount;
			}
			break;
		case InputDirection.Left:
			if ((givenIndex + givenColCount) % givenColCount != 0)
			{
				num = givenIndex - 1;
			}
			else if (currentFocus == RCFocus.SelectionPage && currentPage > 0)
			{
				currentPage--;
				LoadSelectionPage();
				num = givenIndex + givenColCount - 1;
			}
			break;
		case InputDirection.Right:
			if (givenInputDir == InputDirection.Right && (givenIndex + givenColCount) % givenColCount != givenColCount - 1)
			{
				num = givenIndex + 1;
			}
			else if (currentFocus == RCFocus.SelectionPage && currentPage < maxPageCount)
			{
				currentPage++;
				LoadSelectionPage();
				num = givenIndex - givenColCount + 1;
			}
			break;
		}
		if (num != givenIndex)
		{
			if (currentFocus == RCFocus.SelectionPage)
			{
				SoundManager.PlayAudio("MenuMove");
			}
			else
			{
				SoundManager.PlayAudio("RelicChestOpen");
			}
			if (initNavDelayReset)
			{
				initNavDelayReset = false;
				navTimer.IsRunning = true;
			}
			else
			{
				autoNavTimer.IsRunning = true;
			}
		}
		return num;
	}
