private bool AssignPlayerSkill(SBFocus givenFocus)
{
	if (player == null || currentSkill == null)
	{
		return false;
	}
	int num = 0;
	switch (givenFocus)
	{
	case SBFocus.Player:
		num = sbRef.skillEquipSlots[playerInfoSelectedType];
		break;
	case SBFocus.Overdrive:
		num = 3;
		break;
	case SBFocus.Spell:
		if (player.GetSignatureSkill().skillID == currentSkill.skillID)
		{
			SoundManager.PlayAudio("MenuError");
			return false;
		}
		num = ((!currentSkill.isBasic) ? (currentSkill.isDash ? 1 : 2) : 0);
		break;
	}
	StartCoroutine(PlayArcanaEquipAnimation(currentSkill.skillID, num));
	if (num == 3)
	{
		Player.SkillState assignedSkill = player.GetAssignedSkill(currentSkill.skillID);
		Player.SkillState signatureSkill = player.GetSignatureSkill();
		if (assignedSkill == null)
		{
			signatureSkill.isSignature = false;
			signatureSkill.SetEmpowered(givenStatus: false, EmpowerStatMods.DefaultEmpowerMod);
			player.AssignSkillSlot(signatureSkill.SetSkillSlot(), currentSkill.skillID, setSignature: true, signatureStatus: true);
		}
		else if (!assignedSkill.isSignature)
		{
			player.AssignSkillSlot(signatureSkill.SetSkillSlot(), assignedSkill.skillID, setSignature: true, signatureStatus: true);
			player.AssignSkillSlot(assignedSkill.SetSkillSlot(), signatureSkill.skillID, setSignature: true);
		}
	}
	else
	{
		for (int i = 0; i < 6; i++)
		{
			if (player.assignedSkills[i] != null && !(player.assignedSkills[i].isBasic ^ currentSkill.isBasic) && !(player.assignedSkills[i].isDash ^ currentSkill.isDash) && !player.assignedSkills[i].isSignature)
			{
				player.AssignSkillSlot(i, currentSkill.skillID, setSignature: true);
				break;
			}
		}
	}
	player.lowerHUD.cooldownUI.RefreshEntries();
	SetEquipSlots(player);
	GameDataManager.Save(updateCurrentData: true, updatePlayerData: true);
	player.health.RestoreHealth(9999, showDisplayText: false, playSound: false, fullyRestoreHealth: true);
	return true;
}

private IEnumerator PlayArcanaEquipAnimation(string skillID, int equipSlot)
{
	pendingTransitions.Add("ArcanaEquipAnim");
	SoundManager.PlayAudio("CardSelect");
	sbRef.arcanaObj.SetActive(value: true);
	if (equipSlot == SBPlayerPageUI.maxPlayerCardCount - 1)
	{
		sbRef.arcanaAnim.Play("SpinSig", -1, 0f);
	}
	else
	{
		sbRef.arcanaAnim.Play("Spin", -1, 0f);
	}
	sbRef.arcanaRectTrans.position = sbRef.infoPage.cardArray[2].transform.position;
	sbRef.infoPage.cardArray[2].gameObject.SetActive(value: false);
	sbRef.arcanaSpellIcon.sprite = IconManager.GetSkillIcon(skillID);
	Vector3 ogPos = sbRef.arcanaRectTrans.position;
	Vector3 prepTargetPos = ogPos + Vector3.up * 180f;
	while (sbRef.arcanaRectTrans.position.y < prepTargetPos.y)
	{
		sbRef.arcanaRectTrans.position += Vector3.up * Time.deltaTime * 900f;
		yield return null;
	}
	sbRef.arcanaRectTrans.position = prepTargetPos;
	SetFocus(SBFocus.Player);
	sbRef.playerPage.cardBGTransArray[equipSlot].gameObject.SetActive(value: false);
	sbRef.playerPage.spellIconArray[equipSlot].gameObject.SetActive(value: false);
	while (pendingTransitions.Contains("PlayerPageTransition") || pendingTransitions.Contains("InfoPageTransition"))
	{
		yield return null;
	}
	Vector3 equipTargetPos = sbRef.playerPage.cardBGTransArray[equipSlot].position;
	ChaosQuickStopwatch equipEffectQSW = new ChaosQuickStopwatch();
	equipEffectQSW.SetDelay(0.15f);
	equipEffectQSW.IsRunning = true;
	while (equipEffectQSW.IsRunning)
	{
		sbRef.arcanaRectTrans.position = Vector3.Lerp(prepTargetPos, equipTargetPos, equipEffectQSW.TimePercentage);
		yield return null;
	}
	sbRef.arcanaRectTrans.position = equipTargetPos;
	sbRef.playerPage.cardBGTransArray[equipSlot].gameObject.SetActive(value: true);
	sbRef.playerPage.spellIconArray[equipSlot].gameObject.SetActive(value: true);
	sbRef.arcanaObj.SetActive(value: false);
	if (equipSlot == SBPlayerPageUI.maxPlayerCardCount - 1)
	{
		sbRef.playerPage.cardAnimArray[equipSlot].Play("FlashSig", -1, 0f);
	}
	else
	{
		sbRef.playerPage.cardAnimArray[equipSlot].Play("Flash", -1, 0f);
	}
	SoundManager.PlayAudio("Equip");
	yield return null;
	while (!sbRef.playerPage.cardAnimArray[equipSlot].AnimPlayed())
	{
		yield return null;
	}
	pendingTransitions.Remove("ArcanaEquipAnim");
}

