using UnityEngine;

public class PlayerUIBase : MonoBehaviour
{
	public delegate void ToggleEndEventHandler();

	public ToggleEndEventHandler toggleEndEventHandlers;

	private static Dictionary<string, bool> _transitionLocks;

	[HideInInspector]
	public RectTransform parentTrans;

	[HideInInspector]
	public RectTransform rectTransform;

	public string transitionGroupID = string.Empty;

	public Vector3 initialPos;

	public Vector3 horHidePos;

	public Vector3 vertHidePos;

	public bool rightAligned;

	protected bool hidden;

	private float horOffscreenDist = 300f;

	private float vertOffscreenDist = 600f;

	public bool hideHorizontal = true;

	public bool enterFromTop;

	public float timeToHide;

	private ChaosQuickStopwatch hideStopwatch;

	public static Dictionary<string, bool> TransitionLocks
	{
		get
		{
			if (_transitionLocks == null)
			{
				_transitionLocks = new Dictionary<string, bool>();
			}
			return _transitionLocks;
		}
	}

	public virtual void Awake()
	{
		rectTransform = (RectTransform)transform;
		parentTrans = rectTransform.parent as RectTransform;
	}

	public virtual void Start()
	{
		initialPos = rectTransform.anchoredPosition;
		horHidePos = initialPos - Vector3.right * horOffscreenDist;
		vertHidePos = initialPos - Vector3.up * vertOffscreenDist * ((!enterFromTop) ? 1f : (-1f));
		if (parentTrans.anchorMin.x > 0f)
		{
			rightAligned = true;
			horHidePos = initialPos + Vector3.right * horOffscreenDist;
		}
		Toggle(show: false, forceInstant: true);
	}

	public void Toggle(bool show = true, bool forceInstant = false)
	{
		if ((show && !hidden) || (!show && hidden))
		{
			return;
		}
		StopCoroutine("ToggleOverTime");
		if (timeToHide > 0f && !forceInstant)
		{
			gameObject.SetActive(value: true);
			StartCoroutine(ToggleOverTime(show));
			return;
		}
		gameObject.SetActive(show);
		if (show)
		{
			rectTransform.anchoredPosition = initialPos;
		}
		else if (hideHorizontal)
		{
			rectTransform.anchoredPosition = horHidePos;
		}
		else
		{
			rectTransform.anchoredPosition = vertHidePos;
		}
		hidden = !show;
	}

	public virtual void PreToggleOverTime()
	{
	}

	public virtual void PostToggleOverTime()
	{
	}

	public IEnumerator ToggleOverTime(bool show = true)
	{
		while (TransitionLocks.ContainsKey(transitionGroupID) && TransitionLocks[transitionGroupID])
		{
			yield return null;
		}
		SetLock(transitionGroupID);
		PreToggleOverTime();
		hideStopwatch = new ChaosQuickStopwatch();
		hideStopwatch.SetDelay(timeToHide);
		hideStopwatch.IsRunning = true;
		Vector3 startPos = rectTransform.anchoredPosition;
		Vector3 targetPos;
		if (show)
		{
			targetPos = initialPos;
		}
		else
		{
			targetPos = ((!hideHorizontal) ? vertHidePos : horHidePos);
		}
		while (hideStopwatch.IsRunning)
		{
			rectTransform.anchoredPosition = Vector3.Lerp(startPos, targetPos, hideStopwatch.TimePercentage);
			yield return null;
		}
		rectTransform.anchoredPosition = targetPos;
		hidden = !show;
		if (hidden)
		{
			gameObject.SetActive(value: false);
		}
		PostToggleOverTime();
		SetLock(transitionGroupID, setLock: false);
		if (toggleEndEventHandlers != null)
		{
			toggleEndEventHandlers();
		}
	}

	public static void SetLock(string transitionGroupID, bool setLock = true)
	{
		if (transitionGroupID != string.Empty)
		{
			TransitionLocks[transitionGroupID] = setLock;
		}
	}

	public static bool GetLock(string givenID)
	{
		return TransitionLocks.ContainsKey(givenID) && TransitionLocks[givenID];
	}
}
