using System.Collections.Generic;
using Chaos.AnimatorExtensions;
using UnityEngine;
using UnityEngine.UI;

public class GlobalDialog : MonoBehaviour
{
	private class GlobalNotice
	{
		public string uiTextID;

		public float duration;

		public GlobalNotice(string uiTextID, float duration)
		{
			this.uiTextID = uiTextID;
			this.duration = duration;
		}
	}

	private static GlobalDialog instance;

	private Animator anim;

	private bool noticeActive;

	private bool hideAnimPlaying;

	private ChaosQuickStopwatch noticeTimer;

	public Text noticeText;

	private Queue<GlobalNotice> noticeQueue;

	private string currentUITextID;

	public static GlobalDialog Instance => instance;

	private void Awake()
	{
		if (instance != null && instance != this)
		{
			Object.Destroy(gameObject);
			return;
		}
		instance = this;
		Object.DontDestroyOnLoad(gameObject);
		noticeQueue = new Queue<GlobalNotice>(10);
		anim = GetComponent<Animator>();
		noticeTimer = new ChaosQuickStopwatch();
	}

	public void Update()
	{
		if (noticeActive && LoadingScreen.loading && noticeQueue.Count == 0)
		{
			Reset();
		}
	}

	private void Reset()
	{
		noticeActive = false;
		anim.Play("Idle", -1, 0f);
		hideAnimPlaying = false;
		currentUITextID = string.Empty;
		noticeTimer.IsRunning = false;
	}

	public void LateUpdate()
	{
		if (!noticeActive)
		{
			return;
		}
		if (!hideAnimPlaying)
		{
			if (anim.AnimPlayed() && !noticeTimer.IsRunning)
			{
				anim.Play("Hide", -1, 0f);
				hideAnimPlaying = true;
			}
		}
		else if (anim.AnimPlayed(0.75f))
		{
			hideAnimPlaying = false;
			if (noticeQueue.Count > 0)
			{
				GlobalNotice globalNotice = noticeQueue.Dequeue();
				DisplayImmediate(globalNotice.uiTextID, globalNotice.duration);
			}
			else
			{
				noticeActive = false;
				currentUITextID = string.Empty;
			}
		}
	}

	public void DisplayImmediate(string uiTextID, float duration = 1f, bool skipQueue = false, bool skipDuplicates = true)
	{
		noticeTimer.SetDelay(duration + 0.5f);
		noticeTimer.IsRunning = true;
		noticeText.text = TextManager.GetUIText(uiTextID);
		noticeActive = true;
		anim.Play("Show");
		currentUITextID = uiTextID;
	}

	public static void Display(string uiTextID, float duration = 1f, bool skipDuplicates = true)
	{
		if (instance == null)
		{
			return;
		}
		if (instance.noticeActive)
		{
			if (skipDuplicates)
			{
				if (instance.currentUITextID == uiTextID)
				{
					return;
				}
				foreach (GlobalNotice item in instance.noticeQueue)
				{
					if (item.uiTextID == uiTextID)
					{
						return;
					}
				}
			}
			instance.noticeQueue.Enqueue(new GlobalNotice(uiTextID, duration));
		}
		else
		{
			instance.DisplayImmediate(uiTextID, duration);
		}
	}
}

