		{
			speakerDict.Add(dialogSpeakers.speakers[i].speakerID, dialogSpeakers.speakers[i]);
		}
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (!(player == null))
			{
				speakerDict[player.skillCategory] = new DialogSpeakerInfo(player.skillCategory, player.playerData.name, "#FFFFFF", portraitSpriteID: "Player", paletteIndex: player.outfitColorIndex, nameColor: null, fillColorHex: string.Empty, fillColor: null, borderSpriteID: "GrayPanelUnfilled", messageBoxColorHex: string.Empty);
			}
		}
	}

	private void InitDialogDictionary(string givenFilePath)
	{
		if (dialogDict == null)
		{
			dialogDict = new Dictionary<string, DialogEntry>();
		}
		dialogDict.Clear();
		string text = ChaosBundle.Get<TextAsset>(givenFilePath).text;
		DialogEntries dialogEntries = JsonUtility.FromJson<DialogEntries>(text);
		DialogEntry[] entries = dialogEntries.entries;
		foreach (DialogEntry dialogEntry in entries)
		{
			dialogEntry.Initialize();
			dialogDict.Add(dialogEntry.ID, dialogEntry);
		}
	}

