		{
			dialogDict[dialogID].ResetToIndex(overrideIndex);
		}
	}

	private void Activate(DialogMessage message, bool isSign, bool skipGhostWriter)
	{
		options.SetActive(value: false);
		continuePrompt.enabled = false;
		gameObject.SetActive(value: true);
		leftBackgroundImage.enabled = message.leftActive;
		rightBackgroundImage.enabled = false;
		leftBackgroundImage.color = message.LeftSpeaker.messageBoxColor;
		leftPortraitImage.color = solid;
		leftPortraitImage.transform.localScale = Vector3.one;
		leftPlayerImage.color = solid;
		leftPlayerImage.transform.localScale = Vector3.one;
		leftPortraitFillImage.color = solid;
		leftPortraitFillImage.transform.localScale = Vector3.one;
		leftPortraitBorderImage.color = solid;
		leftPortraitBorderImage.transform.localScale = Vector3.one;
		rightPortraitImage.color = darkened;
		rightPortraitImage.transform.localScale = reversed * outOfFocusScale;
		rightPlayerImage.color = darkened;
		rightPlayerImage.transform.localScale = reversed * outOfFocusScale;
		rightPortraitFillImage.color = darkened;
		rightPortraitFillImage.transform.localScale = Vector3.one * outOfFocusScale;
		rightPortraitBorderImage.color = darkened;
		rightPortraitBorderImage.transform.localScale = Vector3.one * outOfFocusScale;
		nameText.text = message.LeftSpeaker.displayName ?? nameText.text;
		nameText.color = message.LeftSpeaker.nameColor;
		leftPortraitFillImage.enabled = message.leftActive;
		leftPortraitBorderImage.enabled = message.leftActive;
		leftPortraitImage.enabled = message.leftActive;
		leftPlayerImage.enabled = message.leftActive;
		if (message.LeftSpeaker != null)
		{
			if (message.LeftSpeaker.speakerID.Contains("Player"))
			{
				leftPortraitImage.enabled = false;
				leftPlayerImage.material.SetFloat("_PaletteIndex", message.LeftSpeaker.paletteIndex);
			}
			else
			{
				leftPlayerImage.enabled = false;
			}
			if (message.leftActive)
			{
				leftPortraitFillImage.color = message.LeftSpeaker.fillColor;
				leftPortraitImage.sprite = message.LeftSpeaker.portraitSprite ?? leftPortraitImage.sprite;
				leftPlayerImage.sprite = message.LeftSpeaker.portraitSprite ?? leftPlayerImage.sprite;
				leftPortraitBorderImage.sprite = message.LeftSpeaker.borderSprite ?? leftPortraitBorderImage.sprite;
			}
		}
		rightPortraitFillImage.enabled = message.rightActive;
		rightPortraitBorderImage.enabled = message.rightActive;
		rightPortraitImage.enabled = message.rightActive;
		rightPlayerImage.enabled = message.rightActive;
		if (message.RightSpeaker != null)
		{
			if (message.RightSpeaker.speakerID.Contains("Player"))
			{
				rightPortraitImage.enabled = false;
				rightPlayerImage.material.SetFloat("_PaletteIndex", message.RightSpeaker.paletteIndex);
			}
			else
			{
				rightPlayerImage.enabled = false;
			}
			if (message.rightActive)
			{
				rightPortraitFillImage.color = message.RightSpeaker.fillColor;
				rightPortraitImage.sprite = message.RightSpeaker.portraitSprite ?? rightPortraitImage.sprite;
				rightPlayerImage.sprite = message.RightSpeaker.portraitSprite ?? rightPlayerImage.sprite;
				rightPortraitBorderImage.sprite = message.RightSpeaker.borderSprite ?? rightPortraitBorderImage.sprite;
			}
		}
		dialogBoxBGImage.enabled = message.leftActive && message.rightActive;
		if (isSign)
		{
			messageText.text = message.message;
			messageText.alignment = TextAnchor.MiddleCenter;
		}
		else
		{
			if (skipGhostWriter)
			{
				messageText.text = message.message;
				endGhostWriter = true;
				HandleShowOptions(message);
			}
			else
			{
				StartCoroutine(GhostWrite(message, messageText));
			}
			messageText.alignment = TextAnchor.UpperLeft;
		}
		messageText.color = Color.white;
	}

	private void HandleShowOptions(DialogMessage message)
	{
		StartCoroutine(ShowOptions(message));
	}

	private IEnumerator ShowOptions(DialogMessage message)
	{
		if (message.showOptions == 1)
		{
			optionsConfirmText.text = message.confirmText;
			optionsCancelText.text = message.cancelText;
			optionsConfirmButtonImage.sprite = GameUI.GetInputSprite(GameController.activePlayers[0].inputDevice.inputScheme);
			optionsCancelButtonImage.sprite = GameUI.GetInputSprite(GameController.activePlayers[0].inputDevice.inputScheme, "Cancel");
			float alpha = 0.01f;
			float num = 0.5f;
			float num2 = 0.1f;
			options.SetActive(value: true);
			optionsConfirmText.canvasRenderer.SetAlpha(alpha);
			optionsCancelText.canvasRenderer.SetAlpha(alpha);
			optionsConfirmButtonImage.canvasRenderer.SetAlpha(alpha);
			optionsCancelButtonImage.canvasRenderer.SetAlpha(alpha);
			optionsConfirmText.CrossFadeAlpha(1f, (!endGhostWriter) ? num : num2, ignoreTimeScale: true);
			optionsCancelText.CrossFadeAlpha(1f, (!endGhostWriter) ? num : num2, ignoreTimeScale: true);
			optionsConfirmButtonImage.CrossFadeAlpha(1f, (!endGhostWriter) ? num : num2, ignoreTimeScale: true);
			optionsCancelButtonImage.CrossFadeAlpha(1f, (!endGhostWriter) ? num : num2, ignoreTimeScale: true);
		}
		else
		{
			continuePrompt.sprite = GameUI.GetInputSprite(GameController.activePlayers[0].inputDevice.inputScheme);
			continuePrompt.enabled = true;
			continuePrompt.canvasRenderer.SetAlpha(0.01f);
			continuePrompt.CrossFadeAlpha(1f, (!endGhostWriter) ? 1f : 0.1f, ignoreTimeScale: true);
		}
		yield break;
	}

	public void Deactivate(bool resetDialog = false)
	{
		if (IsActive || dialogInProgress)
		{
			if (resetDialog)
			{
				ResetDialog(currentDialogID);
			}
			dialogInProgress = false;
			currentDialogID = string.Empty;
			EndGhostWrite();
			gameObject.SetActive(value: false);
		}
	}

	public bool EndGhostWrite()
	{
		endGhostWriter = ghostWriterActive;
		return endGhostWriter;
	}

	private IEnumerator GhostWrite(DialogMessage message, Text textField)
	{
		textField.text = string.Empty;
		endGhostWriter = false;
		ghostWriterActive = true;
		textToWrite = message.message;
		textLength = textToWrite.Length;
		textToWrite += endColorStr;
		for (int i = 0; i < textLength; i++)
		{
			if (textToWrite[i] == '\\' && textToWrite[i + 1] == 'n')
			{
				textField.text += "\n";
				i++;
				continue;
			}
			textField.text = textToWrite.Substring(0, i) + startColorStr + textToWrite.Substring(i);
			if (!endGhostWriter)
			{
				SoundManager.PlayAudio("Dialog");
				yield return waitForDialogDelay;
			}
		}
		textField.text = message.message;
		ghostWriterActive = false;
		HandleShowOptions(message);
		if (!endGhostWriter)
		{
			yield return new WaitForSeconds(0.25f);
		}
	}

	public bool HandleDialog(string dialogID, bool resetOnExit = true, bool unpauseOnComplete = false, float initDelay = 0f)
	{
		GameController.PauseAllPlayers();
		if (!gameObject.activeSelf)
		{
			DisplayDialog(dialogID, -1, string.Empty, string.Empty, string.Empty);
			handleDialogDelayStopwatchID = ChaosStopwatch.Begin(initDelay);
			return false;
		}
		if (!ChaosStopwatch.Check(handleDialogDelayStopwatchID))
		{
			return false;
		}
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (player.inputDevice.GetButtonDown("Cancel") || ((player.inputDevice.GetButtonDown("Interact") || player.inputDevice.GetButtonDown("Confirm")) && !EndGhostWrite() && !DisplayDialog(dialogID, -1, string.Empty, string.Empty, string.Empty)))
			{
				if (resetOnExit)
				{
					ResetDialog(dialogID);
				}
				Deactivate();
				if (unpauseOnComplete)
				{
					GameController.PauseAllPlayers(state: false);
				}
				return true;
			}
		}
		return false;
	}
