using System.Collections;
using System.Collections.Generic;
using System.Linq;
using Steamworks;
using UnityEngine;

public class AchievementManager
{
	private delegate bool ReqPassed();

	private static Dictionary<Achievement, ReqPassed> reqDict;

	private static Dictionary<Achievement, string> achKeyDict;

	private static bool initQueued;

	private static bool initSuccess;

	public const int ComboCountReq = 50;

	public static void Initialize(MonoBehaviour givenMono, bool forceOverride = false)
	{
		givenMono.StartCoroutine(Init(forceOverride));
	}

	private static IEnumerator Init(bool forceOverride = false)
	{
		if (!initQueued || forceOverride)
		{
			initQueued = true;
			InitDictionaries();
			while (!SteamManager.Initialized && !SteamUserStats.RequestCurrentStats())
			{
				yield return null;
			}
			List<Achievement> keyList = reqDict.Keys.ToList();
			for (int num = keyList.Count - 1; num >= 0; num--)
			{
				UnlockAchievement(keyList[num]);
			}
			initSuccess = true;
		}
	}

	private static void InitDictionaries()
	{
		if (reqDict != null)
		{
			reqDict.Clear();
		}
		Dictionary<Achievement, ReqPassed> dictionary = new Dictionary<Achievement, ReqPassed>();
		dictionary.Add(Achievement.CompleteTutorial, CompletedTutorial);
		dictionary.Add(Achievement.StartCoopRun, StartedCoopRun);
		dictionary.Add(Achievement.DefeatFireBoss, DefeatedFireBoss);
		dictionary.Add(Achievement.DefeatEarthBoss, DefeatedEarthBoss);
		dictionary.Add(Achievement.DefeatIceBoss, DefeatedIceBoss);
		dictionary.Add(Achievement.DefeatFinalBoss, DefeatedFinalBoss);
		dictionary.Add(Achievement.HitSpellCombo, HitSpellComboCount);
		dictionary.Add(Achievement.PerfectBoss, BossPerfected);
		dictionary.Add(Achievement.UnlockHalfArcana, UnlockedHalfArcana);
		dictionary.Add(Achievement.UnlockAllArcana, UnlockedAllArcana);
		dictionary.Add(Achievement.UnlockHalfRelics, UnlockedHalfRelics);
		dictionary.Add(Achievement.UnlockAllRelics, UnlockedAllRelics);
		dictionary.Add(Achievement.UnlockAllOutfits, UnlockedAllOutfits);
		dictionary.Add(Achievement.DefeatPinata, DefeatedPinata);
		dictionary.Add(Achievement.MaxGems, MaxedGems);
		dictionary.Add(Achievement.DestroyPaintings, DestroyedPaintings);
		dictionary.Add(Achievement.SpeedRun, SuperSpeed);
		dictionary.Add(Achievement.HoldFourCursed, HoldingFourCursed);
		dictionary.Add(Achievement.UnlockThreeChaos, UnlockedThreeChaos);
		reqDict = dictionary;
		if (achKeyDict != null)
		{
			achKeyDict.Clear();
		}
		Dictionary<Achievement, string> dictionary2 = new Dictionary<Achievement, string>();
		dictionary2.Add(Achievement.CompleteTutorial, "COMPLETE_TUTORIAL");
		dictionary2.Add(Achievement.StartCoopRun, "START_COOP");
		dictionary2.Add(Achievement.DefeatFireBoss, "DEFEAT_FIREBOSS");
		dictionary2.Add(Achievement.DefeatEarthBoss, "DEFEAT_EARTHBOSS");
		dictionary2.Add(Achievement.DefeatIceBoss, "DEFEAT_ICEBOSS");
		dictionary2.Add(Achievement.DefeatFinalBoss, "DEFEAT_FINALBOSS");
		dictionary2.Add(Achievement.HitSpellCombo, "ULTRA_COMBO");
		dictionary2.Add(Achievement.PerfectBoss, "DEFEAT_BOSS_PERFECT");
		dictionary2.Add(Achievement.UnlockHalfArcana, "UNLOCK_ARCANA_50");
		dictionary2.Add(Achievement.UnlockAllArcana, "UNLOCK_ARCANA_99");
		dictionary2.Add(Achievement.UnlockHalfRelics, "UNLOCK_RELIC_50");
		dictionary2.Add(Achievement.UnlockAllRelics, "UNLOCK_RELIC_99");
		dictionary2.Add(Achievement.UnlockAllOutfits, "UNLOCK_OUTFIT_9");
		dictionary2.Add(Achievement.DefeatPinata, "DEFEAT_PINATA_5");
		dictionary2.Add(Achievement.MaxGems, "COLLECT_GEMS_999");
		dictionary2.Add(Achievement.DestroyPaintings, "DESTROY_PAINTINGS_99");
		dictionary2.Add(Achievement.SpeedRun, "SPEED_RUN");
		dictionary2.Add(Achievement.HoldFourCursed, "COLLECT_CURSED_4");
		dictionary2.Add(Achievement.UnlockThreeChaos, "UNLOCK_ARCANA_CHAOS_5");
		achKeyDict = dictionary2;
	}

	public static void UnlockAchievement(Achievement givenAC, bool forceUnlock = false)
	{
		if (initSuccess && achKeyDict.ContainsKey(givenAC) && reqDict.ContainsKey(givenAC) && (forceUnlock || reqDict[givenAC]()))
		{
			SteamUserStats.SetAchievement(achKeyDict[givenAC]);
			SteamUserStats.StoreStats();
			reqDict.Remove(givenAC);
		}
	}

	private static bool CompletedTutorial()
	{
		return Application.loadedLevelName == "PlayerRoomTutorial";
	}

	private static bool DefeatedEnemy(string givenStr, int minCount = 1)
	{
		return GameDataManager.gameData.gameStats.GetEnemyDefeatedCount(givenStr) >= minCount;
	}

	private static bool DefeatedIceBoss()
	{
		return DefeatedEnemy("IceBoss");
	}

	private static bool DefeatedEarthBoss()
	{
		return DefeatedEnemy("EarthBoss");
	}

	private static bool DefeatedFireBoss()
	{
		return DefeatedEnemy("FireBoss");
	}

	private static bool DefeatedFinalBoss()
	{
		return DefeatedEnemy("FinalBoss");
	}

	private static bool DefeatedPinata()
	{
		return DefeatedEnemy("Pinata", 5);
	}

	private static bool UnlockedAllArcana()
	{
		return GameDataManager.gameData.GetUnlockedSkillCount() >= 99;
	}

	private static bool UnlockedHalfArcana()
	{
		return GameDataManager.gameData.GetUnlockedSkillCount() >= 50;
	}

	private static bool UnlockedThreeChaos()
	{
		return GameDataManager.gameData.GetUnlockedChaosCountCount() >= 3;
	}

	private static bool UnlockedAllRelics()
	{
		return GameDataManager.gameData.GetUnlockedItemCount() >= 99;
	}

	private static bool UnlockedHalfRelics()
	{
		return GameDataManager.gameData.GetUnlockedItemCount() >= 50;
	}

	private static bool HoldingFourCursed()
	{
		for (int i = 0; i < GameController.activePlayers.Length; i++)
		{
			if (GameController.activePlayers[i] != null && GameController.activePlayers[i].inventory != null && GameController.activePlayers[i].inventory.CursedCount > 3)
			{
				return true;
			}
		}
		return false;
	}

	private static bool UnlockedAllOutfits()
	{
		return GameDataManager.gameData.GetUnlockedOutfitCount() >= 9;
	}

	private static bool StartedCoopRun()
	{
		if (GameController.coopOn)
		{
			return true;
		}
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (player != null && player.inventory.ContainsItem(BuffWithFriendship.staticID))
			{
				return true;
			}
		}
		return false;
	}

	private static bool HitSpellComboCount()
	{
		return false;
	}

	private static bool DestroyedPaintings()
	{
		return GameDataManager.gameData.gameStats.GetIntStatValue(GameData.Stat.Painting) >= 99;
	}

	private static bool BossPerfected()
	{
		return false;
	}

	private static bool SuperSpeed()
	{
		return false;
	}

	private static bool MaxedGems()
	{
		return GameDataManager.gameData.GetPlatinumBalance() >= 999;
	}
}
using System;
using System.Text;
using Steamworks;
using UnityEngine;

[DisallowMultipleComponent]
internal class SteamManager : MonoBehaviour
{
	private static SteamManager s_instance;

	private static bool s_EverInialized;

	private bool m_bInitialized;

	private SteamAPIWarningMessageHook_t m_SteamAPIWarningMessageHook;

	private static SteamManager Instance => s_instance ?? new GameObject("SteamManager").AddComponent<SteamManager>();

	public static bool Initialized => Instance.m_bInitialized;

	private static void SteamAPIDebugTextHook(int nSeverity, StringBuilder pchDebugText)
	{
		Debug.LogWarning(pchDebugText);
	}

	private void Awake()
	{
		if (s_instance != null)
		{
			UnityEngine.Object.Destroy(gameObject);
			return;
		}
		s_instance = this;
		if (s_EverInialized)
		{
			throw new Exception("Tried to Initialize the SteamAPI twice in one session!");
		}
		UnityEngine.Object.DontDestroyOnLoad(gameObject);
		if (!Packsize.Test())
		{
			Debug.LogError("[Steamworks.NET] Packsize Test returned false, the wrong version of Steamworks.NET is being run in this platform.", this);
		}
		if (!DllCheck.Test())
		{
			Debug.LogError("[Steamworks.NET] DllCheck Test returned false, One or more of the Steamworks binaries seems to be the wrong version.", this);
		}
		try
		{
			if (SteamAPI.RestartAppIfNecessary(AppId_t.Invalid))
			{
				Application.Quit();
				return;
			}
		}
		catch (DllNotFoundException ex)
		{
			Debug.LogError("[Steamworks.NET] Could not load [lib]steam_api.dll/so/dylib. It's likely not in the correct location. Refer to the README for more details.\n" + ex, this);
			Application.Quit();
			return;
		}
		m_bInitialized = SteamAPI.Init();
		if (!m_bInitialized)
		{
			Debug.LogError("[Steamworks.NET] SteamAPI_Init() failed. Refer to Valve's documentation or the comment above this line for more information.", this);
		}
		else
		{
			s_EverInialized = true;
		}
	}

	private void OnEnable()
	{
		if (s_instance == null)
		{
			s_instance = this;
		}
		if (m_bInitialized && m_SteamAPIWarningMessageHook == null)
		{
			m_SteamAPIWarningMessageHook = SteamAPIDebugTextHook;
			SteamClient.SetWarningMessageHook(m_SteamAPIWarningMessageHook);
		}
	}

	private void OnDestroy()
	{
		if (!(s_instance != this))
		{
			s_instance = null;
			if (m_bInitialized)
			{
				SteamAPI.Shutdown();
			}
		}
	}

	private void Update()
	{
		if (m_bInitialized)
		{
			SteamAPI.RunCallbacks();
		}
	}
}

using System;
using System.Collections.Generic;
using UnityEngine;

[Serializable]
public class GameData
{
	public enum Stat
	{
		Death = 0,
		Gold = 1,
		Spike = 2,
		Fall = 3,
		Damage = 5,
		Destructible = 6,
		Plat = 7,
		Painting = 8
	}

	[Serializable]
	public class GameStats
	{
		public float totalPlayTime;

		private int tempStatVal;

		private int tempValue;

		private Dictionary<int, int> intStatsDictionary;

		public Dictionary<string, int> enemiesDefeatedDictionary;

		public GameStats()
		{
			Reset();
		}

		public void UpdatePlayTime()
		{
			totalPlayTime += GameController.timeSinceLastTimeSave;
			GameController.timeSinceLastTimeSave = 0f;
		}

		public int GetIntStatValue(Stat givenStat)
		{
			return (!intStatsDictionary.ContainsKey((int)givenStat)) ? (-1) : intStatsDictionary[(int)givenStat];
		}

		public void UpdateIntStatValue(Stat givenStat, int givenAmount = 1)
		{
			if (Globals.InGameScene(string.Empty) && givenAmount >= 1)
			{
				tempStatVal = (int)givenStat;
				if (!intStatsDictionary.ContainsKey(tempStatVal))
				{
					intStatsDictionary.Add(tempStatVal, 0);
				}
				tempValue = intStatsDictionary[tempStatVal];
				intStatsDictionary[tempStatVal] = Mathf.Min(99999999, tempValue + givenAmount);
			}
		}

		public void EnemyDefeated(string name)
		{
			if (!enemiesDefeatedDictionary.ContainsKey(name))
			{
				enemiesDefeatedDictionary.Add(name, 0);
			}
			enemiesDefeatedDictionary[name]++;
		}

		public int GetEnemyDefeatedCount(string givenName)
		{
			return enemiesDefeatedDictionary.ContainsKey(givenName) ? enemiesDefeatedDictionary[givenName] : 0;
		}

		public void Reset()
		{
			totalPlayTime = 0f;
			InitEnemiesDefeatedDictionary();
			InitIntStatsDictionary();
		}

		private void InitEnemiesDefeatedDictionary()
		{
			if (enemiesDefeatedDictionary == null)
			{
				enemiesDefeatedDictionary = new Dictionary<string, int>();
			}
			enemiesDefeatedDictionary.Clear();
		}

		private void InitIntStatsDictionary()
		{
			if (intStatsDictionary == null)
			{
				intStatsDictionary = new Dictionary<int, int>();
			}
			intStatsDictionary.Clear();
			intStatsDictionary.Add(1, 0);
			intStatsDictionary.Add(7, 0);
			intStatsDictionary.Add(0, 0);
			intStatsDictionary.Add(2, 0);
			intStatsDictionary.Add(3, 0);
			intStatsDictionary.Add(5, 0);
			intStatsDictionary.Add(6, 0);
			intStatsDictionary.Add(8, 0);
		}
	}

