using System.Collections.Generic;

public class PlayerEndStats
{
	public enum Stat
	{
		Basic,
		Spell,
		Taken,
		Enemies,
		Spent
	}

	private Dictionary<Stat, int> endStats;

	private Dictionary<Stat, int> totalEndStats;

	public PlayerEndStats()
	{
		ResetStats(resetTotals: true);
	}

	public void ResetStats(bool resetTotals = false)
	{
		if (endStats == null)
		{
			endStats = new Dictionary<Stat, int>();
		}
		endStats.Clear();
		endStats[Stat.Basic] = 0;
		endStats[Stat.Spell] = 0;
		endStats[Stat.Taken] = 0;
		endStats[Stat.Enemies] = 0;
		endStats[Stat.Spent] = 0;
		if (resetTotals)
		{
			if (totalEndStats == null)
			{
				totalEndStats = new Dictionary<Stat, int>();
			}
			totalEndStats.Clear();
			totalEndStats[Stat.Basic] = 0;
			totalEndStats[Stat.Spell] = 0;
			totalEndStats[Stat.Taken] = 0;
			totalEndStats[Stat.Enemies] = 0;
			totalEndStats[Stat.Spent] = 0;
		}
	}

	public void ModifyValue(Stat stat, int value = 1)
	{
		endStats[stat] += value;
		totalEndStats[stat] += value;
	}

	public int GetStatValue(Stat stat, bool total = false)
	{
		return (!total) ? endStats[stat] : totalEndStats[stat];
	}
}
using System;

[Serializable]
public class RunHistoryEntry
{
	public GameMode gameMode;

	public int loopCount;

	public int tierCount = 1;

	public int stageCount = 1;

	public string timeText = "0:0";

	public string timeStr = "0.0";

	public string[] relicIDs = new string[12];

	public string[] arcanaIDs = new string[7];

	public int[] arcanaTypes = new int[7];

	public string outfitID = "Hope";

	public bool outfitUpgraded;

	public bool loopMode;

	public bool speedMode;

	public bool hardMode;

	public bool extraGold;

	public bool randomMode;

	public bool floorLock;

	public bool superSura;

	public bool coop;

	public static bool IsBetterRun(RunHistoryEntry newEntry, RunHistoryEntry oldEntry = null)
	{
		if (oldEntry == null)
		{
			return true;
		}
		if (newEntry.gameMode == GameMode.Endless)
		{
			int num = newEntry.loopCount * 100 + newEntry.tierCount * 10 + newEntry.stageCount;
			int num2 = oldEntry.loopCount * 100 + oldEntry.tierCount * 10 + oldEntry.stageCount;
			if (num > num2)
			{
				return true;
			}
			if (num < num2)
			{
				return false;
			}
		}
		return double.Parse(newEntry.timeStr) < double.Parse(oldEntry.timeStr);
	}

	public static void Save()
	{
		int num = 0;
		Player player = null;
		if (GameController.coopOn)
		{
			PlayerRunData winnerData = RunData.GetWinnerData();
			if (winnerData == null)
			{
				num = 0;
			}
			else if (winnerData.playerID >= 0)
			{
				num = winnerData.playerID;
			}
		}
		RunHistoryEntry runHistoryEntry = new RunHistoryEntry();
		runHistoryEntry.loopCount = GameController.loopCount;
		runHistoryEntry.tierCount = GameController.tierCount;
		runHistoryEntry.stageCount = GameController.stageCount;
		runHistoryEntry.coop = GameController.coopOn;
		runHistoryEntry.timeText = Globals.TimeToString(GameController.totalTime);
		runHistoryEntry.timeStr = GameController.totalTime.ToString();
		runHistoryEntry.loopMode = GameController.loopCount > 0;
		runHistoryEntry.speedMode = Level.isBossRushMode;
		runHistoryEntry.hardMode = GameController.runModifier.HasMod(HardRunMod.staticID);
		runHistoryEntry.extraGold = !Level.isBossRushMode && JewelerNpc.goldTraded;
		runHistoryEntry.randomMode = GameController.runModifier.HasMod(RandRunMod.staticID);
		runHistoryEntry.floorLock = EpicBeardWizardNpc.levelLocked;
		runHistoryEntry.superSura = RunData.superSuraDefeated;
		player = GameController.activePlayers[num];
		for (int i = 0; i < runHistoryEntry.arcanaIDs.Length - 1; i++)
		{
			if (player.assignedSkills[i] != null)
			{
				runHistoryEntry.arcanaIDs[i] = player.assignedSkills[i].skillID;
				if (player.assignedSkills[i].isSignature)
				{
					runHistoryEntry.arcanaTypes[i] = 2;
				}
				else
				{
					runHistoryEntry.arcanaTypes[i] = (player.assignedSkills[i].IsEmpowered ? 1 : 0);
				}
			}
		}
		if (player.stockSkill != null)
		{
			runHistoryEntry.arcanaIDs[runHistoryEntry.arcanaIDs.Length - 1] = player.stockSkill.skillID;
			runHistoryEntry.arcanaTypes[runHistoryEntry.arcanaIDs.Length - 1] = (player.stockSkill.IsEmpowered ? 1 : 0);
		}
		string[] array = player.inventory.GetItemIDList().ToArray();
		for (int j = 0; j < array.Length; j++)
		{
			if (array[j] != null && !(array[j] == string.Empty))
			{
				runHistoryEntry.relicIDs[j] = array[j];
			}
		}
		runHistoryEntry.outfitID = player.equippedOutfit.outfitID;
		runHistoryEntry.outfitUpgraded = player.outfitEnhanced;
		if (Level.isBossRushMode)
		{
			runHistoryEntry.gameMode = GameMode.Speed;
		}
		else if (GameController.loopCount > 0)
		{
			runHistoryEntry.gameMode = GameMode.Endless;
		}
		else
		{
			runHistoryEntry.gameMode = GameMode.Standard;
		}
		if (IsBetterRun(runHistoryEntry, GameDataManager.gameVars.GetRunEntries()[(int)runHistoryEntry.gameMode]))
		{
			GameDataManager.gameVars.SetRunEntry(runHistoryEntry);
			RunHistoryUI.newRecordFlags[(int)runHistoryEntry.gameMode] = true;
		}
	}
}
