public class TrophyShelf : MonoBehaviour
{
	public GameObject trophyStandard;

	public GameObject trophySpeed;

	public GameObject trophyEndless;

	private Player curPlayer;

	private bool activated;

	private void Start()
	{
		RunHistoryUI.LoadData();
		UpdateTrophies();
	}

	public void UpdateTrophies()
	{
		trophyStandard.SetActive(value: false);
		trophySpeed.SetActive(value: false);
		trophyEndless.SetActive(value: false);
		if (RunHistoryUI.runEntryData[0] != null)
		{
			trophyStandard.SetActive(value: true);
		}
		if (RunHistoryUI.runEntryData[1] != null)
		{
			trophySpeed.SetActive(value: true);
		}
		if (RunHistoryUI.runEntryData[2] != null)
		{
			trophyEndless.SetActive(value: true);
		}
	}

	private void OnTriggerStay2D(Collider2D col)
	{
		if (PlayerRoomUI.CurrentUI.AnyUIOpen || GameUI.dialogManager.IsActive || GameUI.pauseMenu.paused)
		{
			Disable();
		}
		else if (activated)
		{
			if (curPlayer.facingDirection != FacingDirection.Up)
			{
				Disable();
			}
		}
		else if (col.gameObject.name == "AllyFloorContact" && col.gameObject.tag == "Player")
		{
			curPlayer = col.transform.parent.gameObject.GetComponent<Player>();
			if (!(curPlayer == null) && curPlayer.facingDirection == FacingDirection.Up)
			{
				RunHistoryUI.Instance.Toggle(show: true, curPlayer, this);
				activated = true;
			}
		}
	}

	private void OnTriggerExit2D(Collider2D col)
	{
		if (activated && col.gameObject.name == "AllyFloorContact" && col.gameObject.tag == "Player" && curPlayer == col.transform.parent.gameObject.GetComponent<Player>())
		{
			Disable();
		}
	}

	private void Disable()
	{
		RunHistoryUI.Instance.Toggle(show: false, curPlayer);
		curPlayer = null;
		for (int i = 0; i < RunHistoryUI.newRecordFlags.Length; i++)
		{
			RunHistoryUI.newRecordFlags[i] = false;
		}
		activated = false;
	}

	private void OnDestroy()
	{
		if (RunHistoryUI.Instance != null)
		{
			Disable();
		}
	}
}
