public class EnemyHPBars : Item
{
	private HealthBar tempHPBar;

	private static bool poolCreated;

	private static int maxHPBarCount = 25;

	private static EnemyHPBarActivator enemyHPBarActivator;

	public static string staticID = "EnemyHPBars";

	private bool itemHeld;

	private NumVarStatMod damageMod;

	private static EnemyHPBarActivator EHPBActivator => enemyHPBarActivator ?? (enemyHPBarActivator = Globals.ChaosInst<EnemyHPBarActivator>(EnemyHPBarActivator.Prefab));

	protected override string ExtraInfo => PercentToStr(damageMod, "+");

	public EnemyHPBars()
	{
		ID = staticID;
		category = Category.Offense;
		damageMod = new NumVarStatMod(ID, 0.05f, 10, VarStatModType.Multiplicative);
	}

	public override void Activate()
	{
		SetStatus();
	}

	public override void Deactivate()
	{
		SetStatus(givenStatus: false);
	}

	private void SetStatus(bool givenStatus = true)
	{
		if (!SetParentAsPlayer())
		{
			return;
		}
		itemHeld = givenStatus;
		CreateHPBarPool();
		StatManager.ModifyAllStatData(damageMod, parentSkillCategory, "damage", IgnoreStatusConditional, givenStatus);
		if (!givenStatus)
		{
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				if (player != null && player != parentPlayer && player.inventory.ContainsItem(staticID))
				{
					return;
				}
			}
			if (poolCreated)
			{
				for (int j = 0; j < maxHPBarCount; j++)
				{
					tempHPBar = PoolManager.GetPoolItem<HealthBar>();
					tempHPBar.canvas.enabled = false;
				}
			}
		}
		ToggleEnemyHPBars(givenStatus);
	}

	public static void ToggleEnemyHPBars(bool enable = true)
	{
		EHPBActivator.Toggle(enable);
		EHPBActivator.enabled = enable;
	}

	private void CreateHPBarPool()
	{
		if (!poolCreated)
		{
			poolCreated = true;
			PoolManager.CreatePool<HealthBar>("Assets/Prefabs/UI/HealthBar.prefab", maxHPBarCount, string.Empty);
			for (int i = 0; i < maxHPBarCount; i++)
			{
				tempHPBar = PoolManager.GetPoolItem<HealthBar>();
				tempHPBar.destroyOnNullParent = false;
				tempHPBar.canvas.enabled = false;
			}
		}
	}
}
